import { GoogleGenAI, Type } from "@google/genai";
import { Block, DesignTone } from "../types";

const TEXT_MODEL = 'gemini-3-pro-preview';
const IMAGE_MODEL = 'gemini-3-pro-image-preview';

export class GeminiService {
  private getAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  async parseToBlocks(prompt: string, tone: DesignTone = 'professional', existingHtml?: string): Promise<{ blocks: Block[], globalCss: string }> {
    const ai = this.getAI();

    const toneGuidelines = {
      professional: "Clean, corporate, high-trust. Use whitespace and modern sans-serif.",
      minimalist: "Essential only. Mono palette, thin borders, monochrome accents.",
      cyberpunk: "Neon glows, dark bg, high contrast, glitch elements, futuristic fonts.",
      playful: "Rounded, soft shadows, pastel gradients, friendly UI.",
      brutalist: "Raw, bold typography, black borders, high contrast, non-grid layouts."
    };

    const systemInstruction = `
      You are the "2025 HTML Architect". Your mission is to build or upgrade websites to be high-performance (up to 10k lines) and semantic.

      Design Style: ${toneGuidelines[tone]}

      Workflow:
      1. If existingHtml is provided, analyze its structure and UPGRADE it to modern 2025 standards (Semantic tags like <article>, <section>, <nav>).
      2. If it's a new prompt, generate a complete structure.
      3. Use Tailwind CSS for styling.
      4. FOR ALL IMAGES: Use <img data-ai-prompt="DESCRIPTION">. Leave 'src' empty. Description must be in English, highly detailed.
      5. Split the page into logical blocks (Header, Hero, Services, Footer, etc.).
      6. Return ONLY a JSON object with 'blocks' array and 'globalCss' string.
    `;

    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: existingHtml 
          ? `UPGRADE THIS LEGACY HTML TO 2025 STANDARDS: ${existingHtml}` 
          : `CREATE NEW DESIGN FROM PROMPT: ${prompt}`,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              blocks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    type: { type: Type.STRING },
                    name: { type: Type.STRING },
                    html: { type: Type.STRING }
                  },
                  required: ["id", "type", "name", "html"]
                }
              },
              globalCss: { type: Type.STRING }
            },
            required: ["blocks", "globalCss"]
          }
        }
      });

      return JSON.parse(response.text || '{"blocks": [], "globalCss": ""}');
    } catch (e) {
      console.error("Gemini Build Error:", e);
      throw e;
    }
  }

  async generateAiImage(prompt: string): Promise<string> {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: IMAGE_MODEL,
        contents: {
          parts: [{ text: `${prompt}, 8k, professional photography, cinematic lighting, ultra-detailed` }]
        },
        config: {
          imageConfig: {
            aspectRatio: "16:9",
            imageSize: "1K"
          }
        }
      });

      const candidate = response.candidates?.[0];
      if (!candidate) throw new Error("Image Generation Failed");

      for (const part of candidate.content.parts) {
        if (part.inlineData) {
          return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
      throw new Error("No image data");
    } catch (e) {
      throw e;
    }
  }
}

