import React, { useState, useMemo, useEffect, useRef } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, LogEntry, DesignTone, Snapshot } from './types';
import { 
  Sparkles, Zap, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, 
  Smartphone, Tablet as TabletIcon, Monitor, Trash2, 
  Save, RefreshCw, X, Layout, Palette, 
  ShieldCheck, DownloadCloud, Key, Terminal as TerminalIcon, 
  Trash, ExternalLink, Eraser, ChevronUp, ChevronDown, Edit3, Type,
  Upload, Image as ImageIcon, Plus, FileCode, Wand2, History, RotateCcw
} from 'lucide-react';

const STORAGE_KEY = 'omni_gen_v3_state_pro_v2';

const getInitialState = (): OmniState => ({
  projectName: "Untitled Project",
  metaTitle: "Omni Gen Website",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#6366f1",
  fontFamily: "Inter",
  designTone: 'professional',
  borderRadius: '0.75rem',
  logs: [],
  snapshots: []
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [activeTab, setActiveTab] = useState<'blocks' | 'history'>('blocks');

  const addLog = (type: LogEntry['type'], message: string, details?: string) => {
    const newLog: LogEntry = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      details
    };
    setState(prev => ({
      ...prev,
      logs: [newLog, ...prev.logs].slice(0, 100)
    }));
  };

  useEffect(() => {
    const handleIframeMessage = (event: MessageEvent) => {
      if (event.data?.type === 'UPDATE_BLOCK_HTML') {
        const { blockId, newHtml } = event.data;
        setState(prev => ({
          ...prev,
          blocks: prev.blocks.map(b => b.id === blockId ? { ...b, html: newHtml } : b)
        }));
        addLog('success', 'Đã cập nhật module từ Preview Annotate.');
      }
    };
    window.addEventListener('message', handleIframeMessage);
    return () => window.removeEventListener('message', handleIframeMessage);
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setState({ ...parsed, logs: [] });
      } catch (e) {
        addLog('error', 'Lỗi khôi phục dữ liệu.');
      }
    }

    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        // @ts-ignore
        await window.aistudio.openSelectKey();
      }
    };
    checkKey();
  }, []);

  // Auto-save current state
  useEffect(() => {
    if (state.blocks.length === 0 && state.projectName === "Untitled Project") return;
    const timer = setTimeout(() => {
      const { logs, ...rest } = state;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
      setIsSaved(true);
    }, 1500);
    setIsSaved(false);
    return () => clearTimeout(timer);
  }, [state.blocks, state.globalCss, state.accentColor, state.fontFamily, state.projectName, state.designTone, state.borderRadius, state.snapshots]);

  const handleNewProject = () => {
    if (window.confirm("Bắt đầu dự án mới? Hành động này sẽ xóa các thay đổi chưa được lưu vào History.")) {
      const fresh = getInitialState();
      setState({
        ...fresh,
        snapshots: state.snapshots, // Keep history across projects if desired, or clear it
        logs: [{
          id: 'init-' + Date.now(),
          timestamp: new Date().toLocaleTimeString(),
          type: 'info',
          message: 'Dự án mới đã được tạo.'
        }]
      });
      setInputSource('');
      setViewMode('edit');
      setPreviewKey(k => k + 1);
      addLog('success', 'Reset workspace thành công.');
    }
  };

  const createSnapshot = () => {
    const { logs, snapshots, ...rest } = state;
    const newSnapshot: Snapshot = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleString(),
      name: `${state.projectName} (v${state.snapshots.length + 1})`,
      state: JSON.parse(JSON.stringify(rest))
    };
    setState(prev => ({
      ...prev,
      snapshots: [newSnapshot, ...prev.snapshots].slice(0, 20)
    }));
    addLog('success', 'Đã lưu một bản chụp (Snapshot) vào lịch sử.');
  };

  const restoreSnapshot = (snapshot: Snapshot) => {
    if (window.confirm(`Khôi phục phiên bản "${snapshot.name}"? Dữ liệu hiện tại sẽ bị ghi đè.`)) {
      setState(prev => ({
        ...prev,
        ...snapshot.state,
        logs: [{
          id: 'restore-' + Date.now(),
          timestamp: new Date().toLocaleTimeString(),
          type: 'info',
          message: `Đã khôi phục từ: ${snapshot.name}`
        }]
      }));
      setViewMode('preview');
      addLog('success', 'Khôi phục thành công.');
    }
  };

  const deleteSnapshot = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    setState(prev => ({
      ...prev,
      snapshots: prev.snapshots.filter(s => s.id !== id)
    }));
  };

  const generateWebsiteHtml = (isInternal: boolean = false) => {
    const content = state.blocks.map(b => 
      isInternal 
        ? `<div data-block-id="${b.id}" class="omni-block-wrapper relative">${b.html}</div>`
        : b.html
    ).join('\n');

    const annotateScript = isInternal ? `
      <script>
        (function() {
          const style = document.createElement('style');
          style.innerHTML = \`
            .omni-img-overlay {
              position: absolute; top: 8px; right: 8px; background: #6366f1; color: white;
              padding: 6px 12px; border-radius: 8px; font-family: sans-serif; font-size: 10px;
              font-weight: 800; cursor: pointer; display: none; z-index: 10000;
              box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.3); border: 1px solid rgba(255,255,255,0.2);
            }
            .omni-img-target { outline: 3px solid #6366f1 !important; outline-offset: -3px; cursor: pointer; }
          \`;
          document.head.appendChild(style);
          const overlay = document.createElement('div');
          overlay.className = 'omni-img-overlay';
          overlay.innerHTML = 'CHANGE IMAGE';
          document.body.appendChild(overlay);
          let currentTargetImg = null;
          document.addEventListener('mouseover', (e) => {
            const img = e.target.closest('img');
            if (img) {
              currentTargetImg = img;
              img.classList.add('omni-img-target');
              const rect = img.getBoundingClientRect();
              overlay.style.display = 'block';
              overlay.style.top = (window.scrollY + rect.top + 8) + 'px';
              overlay.style.left = (window.scrollX + rect.right - 100) + 'px';
            }
          });
          overlay.addEventListener('click', () => {
            const input = document.createElement('input');
            input.type = 'file'; input.accept = 'image/*';
            input.onchange = (e) => {
              const file = e.target.files[0];
              const reader = new FileReader();
              reader.onload = (re) => {
                if (currentTargetImg) {
                  currentTargetImg.src = re.target.result;
                  const wrapper = currentTargetImg.closest('[data-block-id]');
                  if (wrapper) {
                    window.parent.postMessage({
                      type: 'UPDATE_BLOCK_HTML',
                      blockId: wrapper.getAttribute('data-block-id'),
                      newHtml: wrapper.innerHTML
                    }, '*');
                  }
                }
              };
              reader.readAsDataURL(file);
            };
            input.click();
          });
        })();
      </script>
    ` : '';

    return `
      <!DOCTYPE html>
      <html lang="en">
      <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          :root { --accent: ${state.accentColor}; --radius: ${state.borderRadius}; }
          body { font-family: '${state.fontFamily}', sans-serif; scroll-behavior: smooth; }
          ${state.globalCss}
        </style>
      </head>
      <body>
        ${content || '<div class="h-screen flex items-center justify-center bg-slate-900 text-slate-500 font-bold uppercase tracking-widest">Architecture Not Found</div>'}
        ${annotateScript}
      </body>
      </html>
    `;
  };

  const internalHtml = useMemo(() => generateWebsiteHtml(true), [state.blocks, state.accentColor, state.fontFamily, state.globalCss, state.borderRadius, state.projectName, previewKey]);

  const processBlockImages = async (targetBlocks?: Block[]) => {
    const blocksToProcess = targetBlocks || state.blocks;
    for (const block of blocksToProcess) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgTags = Array.from(doc.querySelectorAll('img[data-ai-prompt]'));
      if (imgTags.length === 0) continue;

      setSyncingBlocks(prev => new Set(prev).add(block.id));
      for (const img of imgTags) {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) {
          try {
            const base64Image = await geminiService.generateAiImage(prompt);
            img.setAttribute('src', base64Image);
            img.removeAttribute('data-ai-prompt');
            const updatedHtml = doc.body.innerHTML;
            setState(prev => ({
              ...prev,
              blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: updatedHtml } : b)
            }));
            setPreviewKey(k => k + 1);
          } catch (err: any) {
            addLog('error', `Lỗi tạo ảnh AI cho ${block.name}`);
          }
        }
      }
      setSyncingBlocks(prev => {
        const next = new Set(prev);
        next.delete(block.id);
        return next;
      });
    }
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    addLog('info', `Gemini Engine đang khởi tạo giao thức...`);
    try {
      const isUpgrade = inputSource.includes('<') && inputSource.includes('>');
      const result = await geminiService.parseToBlocks(inputSource, state.designTone, isUpgrade ? inputSource : undefined);

      setState(prev => ({
        ...prev,
        blocks: result.blocks,
        globalCss: result.globalCss,
        selectedBlockId: result.blocks[0]?.id || null
      }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);
      addLog('success', isUpgrade ? 'Đã nâng cấp mã nguồn.' : 'Đã khởi tạo Layout.');
      setTimeout(() => processBlockImages(result.blocks), 500);
    } catch (e: any) {
      addLog('error', 'Thao tác thất bại', e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const moveBlock = (index: number, direction: 'up' | 'down') => {
    const newBlocks = [...state.blocks];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newBlocks.length) return;
    [newBlocks[index], newBlocks[targetIndex]] = [newBlocks[targetIndex], newBlocks[index]];
    setState(prev => ({ ...prev, blocks: newBlocks }));
  };

  const handleExport = () => {
    const prodHtml = generateWebsiteHtml(false);
    const blob = new Blob([prodHtml], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; 
    a.download = `${state.projectName.toLowerCase().replace(/\s+/g, '-')}.html`; 
    a.click();
    addLog('success', 'Website exported successfully.');
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/95 backdrop-blur-xl px-6 flex items-center justify-between z-50">
        <div className="flex items-center gap-5">
          <div className="p-2.5 bg-indigo-600 rounded-2xl shadow-lg shadow-indigo-600/30 font-black flex items-center justify-center">
            <Infinity className="w-5 h-5 text-white" />
          </div>
          <div className="flex flex-col">
            <div className="flex items-center gap-3 group">
              {isEditingTitle ? (
                <input
                  autoFocus
                  className="bg-slate-900 border border-indigo-500/50 text-white text-sm font-black tracking-tighter uppercase px-2 py-0.5 rounded outline-none"
                  value={state.projectName}
                  onChange={(e) => setState(prev => ({ ...prev, projectName: e.target.value }))}
                  onBlur={() => setIsEditingTitle(false)}
                  onKeyDown={(e) => e.key === 'Enter' && setIsEditingTitle(false)}
                />
              ) : (
                <h1 
                  onClick={() => setIsEditingTitle(true)}
                  className="text-sm font-black text-white tracking-tighter uppercase cursor-text hover:text-indigo-400 transition-colors flex items-center gap-2"
                >
                  {state.projectName}
                  <Edit3 className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                </h1>
              )}
              {isSaved ? (
                <div className="text-[7px] text-emerald-500 font-bold bg-emerald-500/10 px-1.5 py-0.5 rounded border border-emerald-500/20">SYNCED</div>
              ) : (
                <div className="text-[7px] text-amber-500 font-bold bg-amber-500/10 px-1.5 py-0.5 rounded border border-amber-500/20 animate-pulse">SAVING...</div>
              )}
            </div>
          </div>

          <div className="h-6 w-px bg-white/10 mx-1"></div>

          <button 
            onClick={handleNewProject}
            className="flex items-center gap-2 px-3 py-1.5 bg-indigo-600/10 hover:bg-indigo-600/20 text-indigo-400 rounded-lg font-black text-[10px] transition-all border border-indigo-500/20 uppercase tracking-widest"
          >
            <Plus className="w-3.5 h-3.5" /> NEW
          </button>
        </div>

        <div className="flex items-center gap-3">
          <button onClick={createSnapshot} className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-full font-black text-[10px] border border-white/5 transition-all">
            <Save className="w-3.5 h-3.5 text-emerald-500" /> SNAPSHOT
          </button>

          <button onClick={() => setShowTerminal(!showTerminal)} className={`p-2.5 rounded-full border ${showTerminal ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-800 border-white/5 text-slate-400 hover:bg-slate-700'}`}>
            <TerminalIcon className="w-4 h-4" />
          </button>

          <div className="h-6 w-px bg-white/5 mx-1"></div>

          <button onClick={() => setViewMode(viewMode === 'edit' ? 'preview' : 'edit')} className="flex items-center gap-2 px-5 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-full font-black text-xs border border-white/5">
            {viewMode === 'edit' ? <Eye className="w-3.5 h-3.5 text-indigo-400" /> : <Code2 className="w-3.5 h-3.5 text-indigo-400" />}
            {viewMode === 'edit' ? 'PREVIEW' : 'EDITOR'}
          </button>

          <button onClick={handleExport} className="flex items-center gap-2 px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full font-black text-xs transition-all shadow-xl shadow-indigo-600/30 border border-indigo-400/20">
            <DownloadCloud className="w-3.5 h-3.5" /> EXPORT
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden">
        {/* Left Sidebar */}
        <aside className="w-64 bg-[#0b0f1a] border-r border-white/5 flex flex-col shrink-0 overflow-hidden">
          <div className="flex border-b border-white/5">
            <button 
              onClick={() => setActiveTab('blocks')}
              className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'blocks' ? 'text-indigo-400 border-b-2 border-indigo-500 bg-indigo-500/5' : 'text-slate-500 hover:text-slate-300'}`}
            >
              <Layout className="w-3.5 h-3.5 inline mr-2" /> Blocks
            </button>
            <button 
              onClick={() => setActiveTab('history')}
              className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest transition-all ${activeTab === 'history' ? 'text-indigo-400 border-b-2 border-indigo-500 bg-indigo-500/5' : 'text-slate-500 hover:text-slate-300'}`}
            >
              <History className="w-3.5 h-3.5 inline mr-2" /> History
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
            {activeTab === 'blocks' ? (
              <div className="space-y-2">
                {state.blocks.map((block, idx) => (
                  <div 
                    key={block.id} 
                    onClick={() => { setState(prev => ({ ...prev, selectedBlockId: block.id })); setViewMode('edit'); }}
                    className={`group p-3 rounded-xl cursor-pointer transition-all border ${state.selectedBlockId === block.id ? 'bg-indigo-600/10 border-indigo-500/30 text-white' : 'bg-transparent border-transparent hover:bg-white/5 text-slate-500'}`}
                  >
                    <div className="flex items-center justify-between">
                      <span className="text-[10px] font-black uppercase truncate">{block.name}</span>
                      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={(e) => { e.stopPropagation(); moveBlock(idx, 'up'); }} disabled={idx === 0} className="p-0.5 hover:text-white disabled:opacity-20"><ChevronUp className="w-3 h-3" /></button>
                        <button onClick={(e) => { e.stopPropagation(); moveBlock(idx, 'down'); }} disabled={idx === state.blocks.length - 1} className="p-0.5 hover:text-white disabled:opacity-20"><ChevronDown className="w-3 h-3" /></button>
                      </div>
                    </div>
                  </div>
                ))}
                {state.blocks.length === 0 && <div className="text-[9px] text-slate-600 italic px-2">No blocks yet.</div>}
              </div>
            ) : (
              <div className="space-y-3">
                {state.snapshots.map((snapshot) => (
                  <div 
                    key={snapshot.id}
                    onClick={() => restoreSnapshot(snapshot)}
                    className="group p-3 rounded-xl bg-white/5 border border-white/5 hover:border-indigo-500/30 cursor-pointer transition-all relative"
                  >
                    <div className="text-[10px] font-black text-white uppercase truncate pr-4">{snapshot.name}</div>
                    <div className="text-[8px] text-slate-500 mt-1 font-mono">{snapshot.timestamp}</div>
                    <button 
                      onClick={(e) => deleteSnapshot(e, snapshot.id)}
                      className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 text-slate-500 hover:text-red-400 transition-all"
                    >
                      <Trash2 className="w-3 h-3" />
                    </button>
                  </div>
                ))}
                {state.snapshots.length === 0 && <div className="text-[9px] text-slate-600 italic px-2">No history snapshots.</div>}
              </div>
            )}
          </div>

          <div className="p-4 border-t border-white/5 bg-slate-950/50 space-y-4">
            <div className="space-y-2">
              <label className="text-[9px] font-bold text-slate-500 uppercase">Design Tone</label>
              <select 
                value={state.designTone} 
                onChange={(e) => setState(prev => ({ ...prev, designTone: e.target.value as DesignTone }))}
                className="w-full bg-slate-900 border border-white/10 rounded-lg p-2 text-[10px] font-black text-indigo-400 outline-none"
              >
                <option value="professional">Professional</option>
                <option value="minimalist">Minimalist</option>
                <option value="cyberpunk">Cyberpunk</option>
                <option value="playful">Playful</option>
                <option value="brutalist">Brutalist</option>
              </select>
            </div>
          </div>
        </aside>

        {/* Workspace */}
        <section className="flex-1 flex flex-col overflow-hidden">
          {viewMode === 'edit' ? (
            <div className="flex-1 flex flex-col p-6 overflow-hidden">
               {state.blocks.length > 0 ? (
                  <div className="flex-1 bg-[#0b0f1a] rounded-3xl border border-white/5 shadow-2xl flex flex-col overflow-hidden animate-in fade-in zoom-in duration-300">
                    <div className="p-3 bg-[#131929] border-b border-white/5 px-6 flex justify-between items-center">
                       <span className="text-[10px] font-black text-white uppercase tracking-widest">{state.blocks.find(b => b.id === state.selectedBlockId)?.name}</span>
                       <div className="flex items-center gap-4">
                          <span className="text-[9px] text-slate-500 font-mono tracking-tighter uppercase">Semantic Module v2.0</span>
                          <button onClick={() => setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== state.selectedBlockId), selectedBlockId: prev.blocks.find(b => b.id !== state.selectedBlockId)?.id || null }))} className="text-slate-600 hover:text-red-400 transition-colors"><Trash2 className="w-3.5 h-3.5" /></button>
                       </div>
                    </div>
                    <textarea
                      value={state.blocks.find(b => b.id === state.selectedBlockId)?.html || ''}
                      onChange={(e) => setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === state.selectedBlockId ? { ...b, html: e.target.value } : b) }))}
                      className="flex-1 p-8 bg-transparent text-slate-300 code-font text-sm outline-none resize-none custom-scrollbar leading-relaxed"
                    />
                  </div>
               ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-center max-w-xl mx-auto animate-in slide-in-from-bottom duration-500">
                    <div className="w-20 h-20 bg-indigo-600/10 rounded-[2rem] flex items-center justify-center mb-8 relative">
                      <Wand2 className="w-10 h-10 text-indigo-500" />
                      <div className="absolute inset-0 border border-indigo-500/20 rounded-[2rem] animate-ping opacity-20"></div>
                    </div>
                    <h2 className="text-4xl font-black text-white mb-2 uppercase tracking-tighter italic">HTML Forge 2025</h2>
                    <p className="text-slate-500 text-xs mb-10 uppercase tracking-[0.3em] font-bold">The ultimate semantic architecture engine</p>
                    <textarea 
                      value={inputSource}
                      onChange={(e) => setInputSource(e.target.value)}
                      placeholder="Mô tả ý tưởng hoặc dán mã HTML cần nâng cấp..."
                      className="w-full h-44 bg-slate-900 border border-white/10 rounded-2xl p-6 text-sm outline-none focus:border-indigo-500 mb-6 text-white shadow-2xl resize-none transition-all placeholder:text-slate-700"
                    />
                    <button onClick={handleBuild} disabled={isProcessing} className="w-full py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-[0.2em] hover:scale-[1.02] active:scale-95 transition-all shadow-2xl shadow-indigo-600/40 disabled:opacity-50 flex items-center justify-center gap-3">
                      {isProcessing ? <><Loader2 className="w-5 h-5 animate-spin" /> CRAFTING ENGINE...</> : inputSource.includes('<') ? 'UPGRADE ARCHITECTURE' : 'INITIALIZE BUILD'}
                    </button>
                  </div>
               )}
            </div>
          ) : (
            <div className="flex-1 flex flex-col overflow-hidden relative">
              <div className="h-12 border-b border-white/5 bg-[#0b0f1a] flex items-center justify-center gap-6 shrink-0">
                <button onClick={() => setPreviewDevice('mobile')} className={`p-2 rounded-lg transition-all ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}><Smartphone className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('tablet')} className={`p-2 rounded-lg transition-all ${previewDevice === 'tablet' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}><TabletIcon className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('desktop')} className={`p-2 rounded-lg transition-all ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}><Monitor className="w-4 h-4" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-12 bg-[#020617] flex justify-center items-start custom-scrollbar">
                <div key={previewKey} className={`flex-shrink-0 bg-white shadow-[0_0_100px_rgba(0,0,0,0.5)] transition-all duration-700 ease-in-out overflow-hidden border border-white/10 ${previewDevice === 'desktop' ? 'w-[1200px]' : previewDevice === 'tablet' ? 'w-[768px]' : 'w-[375px]'}`}>
                  <iframe srcDoc={internalHtml} className="w-full h-[2500px] border-none" sandbox="allow-scripts allow-same-origin" />
                </div>
              </div>

              {showTerminal && (
                <div className="absolute bottom-0 left-0 right-0 h-64 bg-[#0b0f1a] border-t border-white/10 z-[60] flex flex-col shadow-[0_-20px_50px_rgba(0,0,0,0.5)] animate-in slide-in-from-bottom duration-300">
                  <div className="h-10 bg-[#131929] border-b border-white/5 flex items-center justify-between px-6 text-[10px] font-black uppercase tracking-widest">
                    <div className="text-indigo-400 flex items-center gap-2"><TerminalIcon className="w-3.5 h-3.5" /> Engine Protocol Active</div>
                    <button onClick={() => setShowTerminal(false)} className="hover:text-white transition-colors"><X className="w-3.5 h-3.5" /></button>
                  </div>
                  <div className="flex-1 overflow-y-auto p-4 space-y-1 code-font text-[10px] bg-slate-950">
                    {state.logs.map(log => (
                      <div key={log.id} className="flex gap-3 text-slate-400 hover:bg-white/5 py-0.5 px-2 rounded">
                        <span className="text-slate-600">[{log.timestamp}]</span>
                        <span className={`${log.type === 'error' ? 'text-red-500' : log.type === 'success' ? 'text-emerald-500' : 'text-indigo-400'} font-bold uppercase w-16`}>{log.type}</span>
                        <span className="text-slate-300">{log.message}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </section>

        {/* Right Sidebar */}
        <aside className="w-64 bg-[#0b0f1a] border-l border-white/5 p-6 flex flex-col gap-6 shrink-0 overflow-y-auto custom-scrollbar">
           <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2"><Palette className="w-3.5 h-3.5 text-indigo-400" /> Visual Identity</h3>
           <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase">Accent Master</label>
                <div className="flex items-center gap-3 bg-slate-900 p-2 rounded-xl border border-white/10">
                  <input type="color" value={state.accentColor} onChange={(e) => setState(prev => ({ ...prev, accentColor: e.target.value }))} className="w-8 h-8 bg-transparent cursor-pointer rounded-lg border-none" />
                  <span className="text-[10px] font-mono text-white uppercase font-black">{state.accentColor}</span>
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase">Unit Curvature</label>
                <select value={state.borderRadius} onChange={(e) => setState(prev => ({ ...prev, borderRadius: e.target.value }))} className="w-full bg-slate-900 border border-white/10 rounded-xl p-3 text-[10px] font-black text-white focus:border-indigo-500 transition-all outline-none">
                  <option value="0px">SHARP [0px]</option>
                  <option value="0.75rem">MODERN [12px]</option>
                  <option value="1.5rem">SOFT [24px]</option>
                  <option value="999px">PILL</option>
                </select>
              </div>
              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase">Type Interface</label>
                <select value={state.fontFamily} onChange={(e) => setState(prev => ({ ...prev, fontFamily: e.target.value }))} className="w-full bg-slate-900 border border-white/10 rounded-xl p-3 text-[10px] font-black text-white focus:border-indigo-500 transition-all outline-none">
                  <option value="Inter">Inter (Global Standard)</option>
                  <option value="Fira Code">Fira Mono (Tech)</option>
                  <option value="Playfair Display">Playfair (Luxury)</option>
                  <option value="Montserrat">Montserrat (Geometric)</option>
                </select>
              </div>
           </div>

           <div className="mt-auto p-4 bg-indigo-600/5 border border-indigo-500/20 rounded-2xl space-y-3">
              <div className="flex items-center gap-2">
                 <ShieldCheck className="w-3.5 h-3.5 text-emerald-400" />
                 <span className="text-[9px] font-black uppercase text-white">Annotate Active</span>
              </div>
              <p className="text-[9px] text-slate-500 leading-relaxed italic">
                Rê chuột vào ảnh trong Preview để cập nhật nhanh. Bản Export sẽ tự động được làm sạch mã nguồn.
              </p>
           </div>
        </aside>
      </main>

      {isProcessing && (
        <div className="absolute inset-0 bg-slate-950/98 backdrop-blur-3xl z-[100] flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-500">
          <div className="relative mb-12">
            <div className="w-24 h-24 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <Zap className="absolute inset-0 m-auto w-8 h-8 text-indigo-500 animate-pulse" />
          </div>
          <h2 className="text-4xl font-black text-white mb-4 tracking-tighter uppercase italic">Engine Initializing...</h2>
          <div className="text-slate-500 text-[10px] font-black uppercase tracking-[0.5em] animate-pulse flex items-center gap-3">
            <Sparkles className="w-3.5 h-3.5 text-amber-500" /> 2025 Protocol Active <Sparkles className="w-3.5 h-3.5 text-amber-500" />
          </div>
        </div>
      )}
    </div>
  );
}

export interface Block {
  id: string;
  type: string;
  name: string;
  html: string;
  css?: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  type: 'info' | 'success' | 'error' | 'warning';
  message: string;
  details?: string;
}

export type DesignTone = 'professional' | 'minimalist' | 'cyberpunk' | 'playful' | 'brutalist';

export interface Snapshot {
  id: string;
  timestamp: string;
  name: string;
  state: Omit<OmniState, 'logs' | 'snapshots'>;
}

export interface OmniState {
  projectName: string;
  metaTitle: string;
  blocks: Block[];
  selectedBlockId: string | null;
  globalCss: string;
  accentColor: string;
  fontFamily: string;
  designTone: DesignTone;
  borderRadius: string;
  logs: LogEntry[];
  snapshots: Snapshot[];
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
}

export interface GeneratedImage {
  url: string;
  prompt: string;
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, LogEntry, DesignTone, Snapshot } from './types';
import { 
  Sparkles, Zap, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, 
  Smartphone, Tablet as TabletIcon, Monitor, Trash2, 
  Save, RefreshCw, X, Layout, Palette, 
  ShieldCheck, DownloadCloud, Key, Terminal as TerminalIcon, 
  Trash, ExternalLink, Eraser, ChevronUp, ChevronDown, Edit3, Type,
  Upload, Image as ImageIcon, Plus, FileCode, History, RotateCcw,
  Wand2
} from 'lucide-react';

const STORAGE_KEY = 'omni_gen_v3_state_pro_final';

const getInitialState = (): OmniState => ({
  projectName: "Untitled Project",
  metaTitle: "Omni Gen Website",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#6366f1",
  fontFamily: "Inter",
  designTone: 'professional',
  borderRadius: '0.75rem',
  logs: [],
  snapshots: []
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [sidebarTab, setSidebarTab] = useState<'blocks' | 'history'>('blocks');

  const previewRefs = {
    mobile: useRef<HTMLIFrameElement>(null),
    tablet: useRef<HTMLIFrameElement>(null),
    desktop: useRef<HTMLIFrameElement>(null)
  };

  const addLog = (type: LogEntry['type'], message: string, details?: string) => {
    const newLog: LogEntry = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      details
    };
    setState(prev => ({
      ...prev,
      logs: [newLog, ...prev.logs].slice(0, 100)
    }));
  };

  useEffect(() => {
    const handleIframeMessage = (event: MessageEvent) => {
      if (event.data?.type === 'UPDATE_BLOCK_HTML') {
        const { blockId, newHtml } = event.data;
        setState(prev => ({
          ...prev,
          blocks: prev.blocks.map(b => b.id === blockId ? { ...b, html: newHtml } : b)
        }));
        addLog('success', 'Đã cập nhật module từ Preview Annotate.');
      }
    };
    window.addEventListener('message', handleIframeMessage);
    return () => window.removeEventListener('message', handleIframeMessage);
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setState({ ...parsed, logs: [] });
      } catch (e) {
        addLog('error', 'Lỗi khôi phục dữ liệu.');
      }
    }

    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        addLog('warning', 'API Key chưa được chọn.');
        // @ts-ignore
        await window.aistudio.openSelectKey();
      }
    };
    checkKey();
  }, []);

  // Auto-save logic (local storage only)
  useEffect(() => {
    const timer = setTimeout(() => {
      const { logs, ...rest } = state;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
      setIsSaved(true);
    }, 2000);
    setIsSaved(false);
    return () => clearTimeout(timer);
  }, [state.blocks, state.globalCss, state.accentColor, state.fontFamily, state.projectName, state.designTone, state.borderRadius, state.snapshots]);

  const handleNewProject = () => {
    const shouldOpenNewTab = confirm("Bạn có muốn mở dự án mới trong tab mới không?\n(Chọn Cancel để reset project ngay tại tab này)");

    if (shouldOpenNewTab) {
      // Clear storage first so the new tab starts fresh
      localStorage.removeItem(STORAGE_KEY);
      window.open(window.location.href, '_blank');
      // Restore local storage if the user wants to keep the old tab's work
      const { logs, ...rest } = state;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
    } else {
      if (confirm("Reset dự án hiện tại? Dữ liệu chưa snapshot sẽ mất.")) {
        setState(getInitialState());
        setInputSource('');
        setViewMode('edit');
        addLog('success', 'Workspace đã được reset.');
      }
    }
  };

  const createSnapshot = () => {
    const { logs, snapshots, ...rest } = state;
    const newSnapshot: Snapshot = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleString(),
      name: `${state.projectName} (Backup ${state.snapshots.length + 1})`,
      state: JSON.parse(JSON.stringify(rest))
    };
    setState(prev => ({
      ...prev,
      snapshots: [newSnapshot, ...prev.snapshots].slice(0, 15)
    }));
    addLog('success', 'Đã lưu Snapshot thành công.');
  };

  const restoreSnapshot = (snapshot: Snapshot) => {
    if (confirm(`Khôi phục phiên bản "${snapshot.name}"? Dữ liệu hiện tại sẽ bị thay thế.`)) {
      setState(prev => ({
        ...prev,
        ...snapshot.state,
        logs: [{
          id: 'restore-' + Date.now(),
          timestamp: new Date().toLocaleTimeString(),
          type: 'info',
          message: `Đã khôi phục từ snapshot: ${snapshot.name}`
        }]
      }));
      setSidebarTab('blocks');
      addLog('success', 'Khôi phục hoàn tất.');
    }
  };

  const handleSaveProject = () => {
    createSnapshot();
    addLog('success', 'Đã lưu dự án vào Snapshot History.');
  };

  const generateWebsiteHtml = (isInternal: boolean = false) => {
    const content = state.blocks.map(b => 
      isInternal 
        ? `<div data-block-id="${b.id}" class="omni-block-wrapper relative">${b.html}</div>`
        : b.html
    ).join('\n');

    const annotateScript = isInternal ? `
      <script>
        (function() {
          const style = document.createElement('style');
          style.innerHTML = \`
            .omni-img-overlay {
              position: absolute; top: 8px; right: 8px; background: rgba(79, 70, 229, 0.95);
              color: white; padding: 6px 12px; border-radius: 8px; font-family: sans-serif;
              font-size: 10px; font-weight: 800; cursor: pointer; display: none; z-index: 10000;
              box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.3); border: 1px solid rgba(255,255,255,0.2);
            }
            .omni-img-target { outline: 3px solid #6366f1 !important; outline-offset: -3px; cursor: pointer; }
          \`;
          document.head.appendChild(style);
          const overlay = document.createElement('div');
          overlay.className = 'omni-img-overlay';
          overlay.innerHTML = 'CHANGE IMAGE';
          document.body.appendChild(overlay);
          let currentTargetImg = null;
          document.addEventListener('mouseover', (e) => {
            const img = e.target.closest('img');
            if (img) {
              currentTargetImg = img;
              img.classList.add('omni-img-target');
              const rect = img.getBoundingClientRect();
              overlay.style.display = 'block';
              overlay.style.top = (window.scrollY + rect.top + 8) + 'px';
              overlay.style.left = (window.scrollX + rect.right - 100) + 'px';
            }
          });
          overlay.addEventListener('click', () => {
            const input = document.createElement('input');
            input.type = 'file'; input.accept = 'image/*';
            input.onchange = (e) => {
              const file = e.target.files[0];
              const reader = new FileReader();
              reader.onload = (re) => {
                if (currentTargetImg) {
                  currentTargetImg.src = re.target.result;
                  const wrapper = currentTargetImg.closest('[data-block-id]');
                  if (wrapper) {
                    window.parent.postMessage({
                      type: 'UPDATE_BLOCK_HTML',
                      blockId: wrapper.getAttribute('data-block-id'),
                      newHtml: wrapper.innerHTML
                    }, '*');
                  }
                }
              };
              reader.readAsDataURL(file);
            };
            input.click();
          });
        })();
      </script>
    ` : '';

    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>${state.metaTitle || state.projectName}</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          body { font-family: '${state.fontFamily}', sans-serif; scroll-behavior: smooth; margin: 0; padding: 0; background-color: white; color: #1e293b; }
          :root { --accent: ${state.accentColor}; --radius: ${state.borderRadius}; }
          ${state.globalCss}
          img:not([src]), img[src=""] { background-color: #f1f5f9; min-height: 100px; display: block; }
        </style>
      </head>
      <body>
        ${content || '<div class="h-screen flex items-center justify-center text-slate-300 font-bold uppercase tracking-widest bg-slate-50">Empty Canvas</div>'}
        ${annotateScript}
      </body>
      </html>
    `;
  };

  const internalHtml = useMemo(() => generateWebsiteHtml(true), [state.blocks, state.accentColor, state.fontFamily, state.globalCss, state.borderRadius, state.metaTitle, state.projectName, previewKey]);

  const processBlockImages = async (targetBlocks?: Block[]) => {
    const blocksToProcess = targetBlocks || state.blocks;
    for (const block of blocksToProcess) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgTags = Array.from(doc.querySelectorAll('img[data-ai-prompt]'));
      if (imgTags.length === 0) continue;

      setSyncingBlocks(prev => new Set(prev).add(block.id));
      for (const img of imgTags) {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) {
          try {
            const base64Image = await geminiService.generateAiImage(prompt);
            img.setAttribute('src', base64Image);
            img.removeAttribute('data-ai-prompt');
            const updatedHtml = doc.body.innerHTML;
            setState(prev => ({
              ...prev,
              blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: updatedHtml } : b)
            }));
            setPreviewKey(k => k + 1);
          } catch (err: any) {
            addLog('error', `Lỗi AI Image: ${block.name}`);
          }
        }
      }
      setSyncingBlocks(prev => {
        const next = new Set(prev);
        next.delete(block.id);
        return next;
      });
    }
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    addLog('info', `Gemini đang khởi tạo cấu trúc...`);
    try {
      const isUpgrade = inputSource.includes('<') && inputSource.includes('>');
      const result = await geminiService.parseToBlocks(inputSource, state.designTone, isUpgrade ? inputSource : undefined);
      setState(prev => ({
        ...prev,
        blocks: result.blocks,
        globalCss: result.globalCss,
        selectedBlockId: result.blocks[0]?.id || null
      }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);
      addLog('success', isUpgrade ? 'Nâng cấp HTML hoàn tất.' : 'Dựng layout thành công.');
      setTimeout(() => processBlockImages(result.blocks), 500);
    } catch (e: any) {
      addLog('error', 'Xây dựng thất bại', e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const moveBlock = (index: number, direction: 'up' | 'down') => {
    const newBlocks = [...state.blocks];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newBlocks.length) return;
    [newBlocks[index], newBlocks[targetIndex]] = [newBlocks[targetIndex], newBlocks[index]];
    setState(prev => ({ ...prev, blocks: newBlocks }));
  };

  const handleExport = () => {
    const prodHtml = generateWebsiteHtml(false);
    const blob = new Blob([prodHtml], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; 
    a.download = `${state.projectName.toLowerCase().replace(/\s+/g, '-')}.html`; 
    a.click();
    addLog('success', 'Đã xuất file HTML.');
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/95 backdrop-blur-xl px-6 flex items-center justify-between z-50">
        <div className="flex items-center gap-5">
          <div className="p-2.5 bg-indigo-600 rounded-2xl shadow-lg shadow-indigo-600/30 font-black flex items-center justify-center">
            <Infinity className="w-5 h-5 text-white" />
          </div>
          <div className="flex flex-col">
            <div className="flex items-center gap-3 group">
              {isEditingTitle ? (
                <input
                  autoFocus
                  className="bg-slate-900 border border-indigo-500/50 text-white text-sm font-black tracking-tighter uppercase px-2 py-0.5 rounded outline-none"
                  value={state.projectName}
                  onChange={(e) => setState(prev => ({ ...prev, projectName: e.target.value }))}
                  onBlur={() => setIsEditingTitle(false)}
                  onKeyDown={(e) => e.key === 'Enter' && setIsEditingTitle(false)}
                />
              ) : (
                <h1 
                  onClick={() => setIsEditingTitle(true)}
                  className="text-sm font-black text-white tracking-tighter uppercase cursor-text hover:text-indigo-400 transition-colors flex items-center gap-2"
                >
                  {state.projectName}
                  <Edit3 className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                </h1>
              )}
              {isSaved ? (
                <div className="text-[7px] text-emerald-500 font-bold bg-emerald-500/10 px-1.5 py-0.5 rounded border border-emerald-500/20">SYNCED</div>
              ) : (
                <div className="text-[7px] text-amber-500 font-bold bg-amber-500/10 px-1.5 py-0.5 rounded border border-amber-500/20 animate-pulse">SAVING...</div>
              )}
            </div>
          </div>

          <div className="h-6 w-px bg-white/10 mx-1"></div>

          <button 
            onClick={handleNewProject}
            className="flex items-center gap-1.5 px-3 py-1.5 bg-indigo-600/10 hover:bg-indigo-600/20 text-indigo-400 rounded-lg font-black text-[9px] transition-all border border-indigo-500/20 uppercase tracking-widest"
          >
            <Plus className="w-3 h-3" /> New Project
          </button>
        </div>

        <div className="flex items-center gap-3">
          <button 
            onClick={handleSaveProject} 
            className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-full font-black text-xs transition-all border border-white/5"
          >
            <Save className="w-3.5 h-3.5 text-emerald-500" /> SNAPSHOT
          </button>

          <button onClick={() => setShowTerminal(!showTerminal)} className={`p-2.5 rounded-full transition-all border ${showTerminal ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-800 border-white/5 text-slate-400 hover:bg-slate-700'}`}>
            <TerminalIcon className="w-4 h-4" />
          </button>

          <div className="h-6 w-px bg-white/5 mx-1"></div>

          <button onClick={() => setViewMode(viewMode === 'edit' ? 'preview' : 'edit')} className="flex items-center gap-2 px-5 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-full font-black text-xs transition-all border border-white/5 shadow-inner">
            {viewMode === 'edit' ? <Eye className="w-3.5 h-3.5 text-indigo-400" /> : <Code2 className="w-3.5 h-3.5 text-indigo-400" />}
            {viewMode === 'edit' ? 'PREVIEW' : 'EDITOR'}
          </button>

          <button onClick={handleExport} className="flex items-center gap-2 px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full font-black text-xs transition-all shadow-xl shadow-indigo-600/30 active:scale-95 border border-indigo-400/20">
            <DownloadCloud className="w-3.5 h-3.5" /> EXPORT
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden">
        <aside className="w-64 bg-[#0b0f1a] border-r border-white/5 flex flex-col shrink-0">
          <div className="flex border-b border-white/5">
            <button 
              onClick={() => setSidebarTab('blocks')} 
              className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest transition-all ${sidebarTab === 'blocks' ? 'text-indigo-400 border-b-2 border-indigo-500 bg-indigo-500/5' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Modules
            </button>
            <button 
              onClick={() => setSidebarTab('history')} 
              className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest transition-all ${sidebarTab === 'history' ? 'text-indigo-400 border-b-2 border-indigo-500 bg-indigo-500/5' : 'text-slate-500 hover:text-slate-300'}`}
            >
              History
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
            {sidebarTab === 'blocks' ? (
              <div className="space-y-2">
                {state.blocks.map((block, idx) => (
                  <div 
                    key={block.id} 
                    onClick={() => { setState(prev => ({ ...prev, selectedBlockId: block.id })); setViewMode('edit'); }}
                    className={`group p-3 rounded-xl cursor-pointer transition-all border relative ${state.selectedBlockId === block.id ? 'bg-indigo-600/10 border-indigo-500/30 text-white' : 'bg-transparent border-transparent hover:bg-white/5 text-slate-500'}`}
                  >
                    <div className="flex items-center justify-between">
                      <span className="text-[10px] font-black uppercase truncate tracking-tight">{block.name}</span>
                      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={(e) => { e.stopPropagation(); moveBlock(idx, 'up'); }} disabled={idx === 0} className="p-0.5 hover:text-white disabled:opacity-20"><ChevronUp className="w-3 h-3" /></button>
                        <button onClick={(e) => { e.stopPropagation(); moveBlock(idx, 'down'); }} disabled={idx === state.blocks.length - 1} className="p-0.5 hover:text-white disabled:opacity-20"><ChevronDown className="w-3 h-3" /></button>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="space-y-3">
                {state.snapshots.map((snap) => (
                  <div 
                    key={snap.id} 
                    onClick={() => restoreSnapshot(snap)}
                    className="p-3 rounded-xl bg-slate-900/50 border border-white/5 hover:border-indigo-500/30 cursor-pointer transition-all group"
                  >
                    <div className="text-[10px] font-black text-white uppercase truncate mb-1">{snap.name}</div>
                    <div className="text-[8px] text-slate-500 font-mono">{snap.timestamp}</div>
                    <div className="mt-2 opacity-0 group-hover:opacity-100 transition-opacity flex justify-end">
                      <button className="text-[8px] font-black text-indigo-400 flex items-center gap-1"><RotateCcw className="w-2.5 h-2.5" /> RESTORE</button>
                    </div>
                  </div>
                ))}
                {state.snapshots.length === 0 && <div className="text-[9px] text-slate-600 italic text-center py-8">Chưa có bản lưu snapshot nào.</div>}
              </div>
            )}
          </div>

          <div className="p-4 border-t border-white/5 bg-slate-950/50">
             <div className="text-[9px] font-black text-slate-500 uppercase mb-3">Tone & Style</div>
             <select 
               value={state.designTone} 
               onChange={(e) => setState(prev => ({ ...prev, designTone: e.target.value as DesignTone }))}
               className="w-full bg-slate-900 border border-white/10 rounded-lg p-2 text-[10px] font-black text-indigo-400 outline-none uppercase"
             >
               <option value="professional">Professional</option>
               <option value="minimalist">Minimalist</option>
               <option value="cyberpunk">Cyberpunk</option>
               <option value="playful">Playful</option>
               <option value="brutalist">Brutalist</option>
             </select>
          </div>
        </aside>

        <section className="flex-1 flex flex-col overflow-hidden bg-[#020617]">
          {viewMode === 'edit' ? (
            <div className="flex-1 flex flex-col p-6 overflow-hidden">
               {state.blocks.length > 0 ? (
                  <div className="flex-1 bg-[#0b0f1a] rounded-3xl border border-white/5 shadow-2xl flex flex-col overflow-hidden">
                    <div className="p-3 bg-[#131929] border-b border-white/5 px-6 flex justify-between items-center">
                       <span className="text-[10px] font-black text-white uppercase tracking-widest">{state.blocks.find(b => b.id === state.selectedBlockId)?.name}</span>
                       <button onClick={() => setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== state.selectedBlockId), selectedBlockId: prev.blocks.find(b => b.id !== state.selectedBlockId)?.id || null }))} className="text-slate-600 hover:text-red-400"><Trash2 className="w-3.5 h-3.5" /></button>
                    </div>
                    <textarea
                      value={state.blocks.find(b => b.id === state.selectedBlockId)?.html || ''}
                      onChange={(e) => setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === state.selectedBlockId ? { ...b, html: e.target.value } : b) }))}
                      className="flex-1 p-8 bg-transparent text-slate-300 code-font text-sm outline-none resize-none custom-scrollbar"
                    />
                  </div>
               ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-center max-w-xl mx-auto">
                    <div className="w-16 h-16 bg-indigo-600/10 rounded-full flex items-center justify-center mb-8">
                      <Wand2 className="w-8 h-8 text-indigo-500 animate-pulse" />
                    </div>
                    <h2 className="text-3xl font-black text-white mb-2 uppercase tracking-tighter italic">HTML Forge 2025</h2>
                    <p className="text-slate-500 text-xs mb-8 uppercase tracking-widest font-bold">Xây dựng hoặc Nâng cấp HTML module lên tới 10,000 dòng</p>
                    <textarea 
                      value={inputSource}
                      onChange={(e) => setInputSource(e.target.value)}
                      placeholder="Mô tả ý tưởng của bạn hoặc dán code HTML cũ để nâng cấp..."
                      className="w-full h-40 bg-slate-900 border border-white/10 rounded-2xl p-6 text-sm outline-none focus:border-indigo-500 mb-6 text-white shadow-inner resize-none transition-all placeholder:text-slate-700"
                    />
                    <button onClick={handleBuild} disabled={isProcessing} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest hover:scale-[1.02] transition-all shadow-xl shadow-indigo-600/30 active:scale-95 disabled:opacity-50">
                      {isProcessing ? 'ENGINE ĐANG THI CÔNG...' : inputSource.includes('<') ? 'UPGRADE HTML CODE' : 'BẮT ĐẦU THIẾT KẾ'}
                    </button>
                  </div>
               )}
            </div>
          ) : (
            <div className="flex-1 flex flex-col overflow-hidden relative">
              <div className="h-12 border-b border-white/5 bg-[#0b0f1a] flex items-center justify-center gap-6 shrink-0">
                <button onClick={() => setPreviewDevice('mobile')} className={`p-2 rounded-lg transition-all ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}><Smartphone className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('tablet')} className={`p-2 rounded-lg transition-all ${previewDevice === 'tablet' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}><TabletIcon className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('desktop')} className={`p-2 rounded-lg transition-all ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500'}`}><Monitor className="w-4 h-4" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-12 bg-[#020617] flex justify-center items-start custom-scrollbar relative">
                <div key={previewKey} className={`flex-shrink-0 bg-white shadow-2xl transition-all duration-500 rounded-sm overflow-hidden border border-white/10 ${previewDevice === 'desktop' ? 'w-[1200px]' : previewDevice === 'tablet' ? 'w-[768px]' : 'w-[375px]'}`}>
                  <iframe srcDoc={internalHtml} className="w-full h-[2000px] border-none" sandbox="allow-scripts allow-same-origin" />
                </div>
              </div>

              {showTerminal && (
                <div className="absolute bottom-0 left-0 right-0 h-64 bg-[#0b0f1a] border-t border-white/10 z-[60] flex flex-col shadow-2xl">
                  <div className="h-10 bg-[#131929] border-b border-white/5 flex items-center justify-between px-6 shrink-0 text-[10px] font-black uppercase">
                    <div className="flex items-center gap-2 text-indigo-400"><TerminalIcon className="w-3.5 h-3.5" /> Engine Protocol Output</div>
                    <button onClick={() => setShowTerminal(false)} className="hover:text-white transition-colors"><X className="w-3 h-3" /></button>
                  </div>
                  <div className="flex-1 overflow-y-auto p-4 space-y-1 code-font custom-scrollbar bg-slate-950 text-[10px]">
                    {state.logs.map(log => (
                      <div key={log.id} className="flex gap-3 text-slate-400 hover:bg-white/5 rounded px-1">
                        <span className="shrink-0 text-slate-600">[{log.timestamp}]</span>
                        <span className={`font-black w-12 ${log.type === 'error' ? 'text-red-500' : 'text-emerald-500'}`}>{log.type}</span>
                        <div className="flex-1">{log.message}</div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </section>

        <aside className="w-64 bg-[#0b0f1a] border-l border-white/5 p-6 flex flex-col gap-6 shrink-0">
           <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2 mb-1"><Palette className="w-3.5 h-3.5 text-indigo-400" /> Identity</h3>
           <div className="space-y-6">
              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-2">Accent Master</label>
                <div className="flex items-center gap-3 bg-slate-950 p-2 rounded-xl border border-white/10">
                  <input type="color" value={state.accentColor} onChange={(e) => setState(prev => ({ ...prev, accentColor: e.target.value }))} className="w-8 h-8 bg-transparent cursor-pointer border-none rounded" />
                  <span className="text-[10px] font-mono font-black text-white uppercase">{state.accentColor}</span>
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-2">Typography</label>
                <select value={state.fontFamily} onChange={(e) => setState(prev => ({ ...prev, fontFamily: e.target.value }))} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-[10px] font-black text-white outline-none">
                  <option value="Inter">Inter Sans</option>
                  <option value="Playfair Display">Elegant Serif</option>
                  <option value="Fira Code">Mono Tech</option>
                </select>
              </div>
           </div>
        </aside>
      </main>

      {isProcessing && (
        <div className="absolute inset-0 bg-slate-950/98 backdrop-blur-3xl z-[100] flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-700">
          <div className="relative mb-12">
            <div className="w-24 h-24 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <Zap className="absolute inset-0 m-auto w-8 h-8 text-indigo-500 animate-pulse" />
          </div>
          <h2 className="text-4xl font-black text-white mb-4 tracking-tighter uppercase italic">Engine Crafting...</h2>
          <div className="text-slate-500 text-[10px] font-black uppercase tracking-[0.5em] animate-pulse">2025 Protocol Active</div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, LogEntry, DesignTone, Snapshot } from './types';
import { 
  Sparkles, Zap, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, 
  Smartphone, Tablet as TabletIcon, Monitor, Trash2, 
  Save, RefreshCw, X, Layout, Palette, 
  ShieldCheck, DownloadCloud, Key, Terminal as TerminalIcon, 
  Trash, ExternalLink, Eraser, ChevronUp, ChevronDown, Edit3, Type,
  Upload, Image as ImageIcon, Plus, FileCode, History, RotateCcw,
  Wand2, Clock, Check
} from 'lucide-react';

const STORAGE_KEY = 'omni_gen_v3_state_pro_final';

const getInitialState = (): OmniState => ({
  projectName: "Untitled Project",
  metaTitle: "Omni Gen Website",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#6366f1",
  fontFamily: "Inter",
  designTone: 'professional',
  borderRadius: '0.75rem',
  logs: [],
  snapshots: []
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [sidebarTab, setSidebarTab] = useState<'blocks' | 'history'>('blocks');

  const addLog = (type: LogEntry['type'], message: string, details?: string) => {
    const newLog: LogEntry = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      details
    };
    setState(prev => ({
      ...prev,
      logs: [newLog, ...prev.logs].slice(0, 100)
    }));
  };

  useEffect(() => {
    const handleIframeMessage = (event: MessageEvent) => {
      if (event.data?.type === 'UPDATE_BLOCK_HTML') {
        const { blockId, newHtml } = event.data;
        setState(prev => ({
          ...prev,
          blocks: prev.blocks.map(b => b.id === blockId ? { ...b, html: newHtml } : b)
        }));
        addLog('success', 'Đã cập nhật module từ Preview Annotate.');
      }
    };
    window.addEventListener('message', handleIframeMessage);
    return () => window.removeEventListener('message', handleIframeMessage);
  }, []);

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const isFresh = urlParams.get('fresh') === '1';

    if (isFresh) {
      // If fresh flag is set, start with initial state and clear URL
      setState(getInitialState());
      window.history.replaceState({}, document.title, window.location.pathname);
      addLog('info', 'Đã khởi tạo không gian làm việc mới (Fresh Mode).');
    } else {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        try {
          const parsed = JSON.parse(saved);
          setState({ ...parsed, logs: [] });
        } catch (e) {
          addLog('error', 'Lỗi khôi phục dữ liệu.');
        }
      }
    }

    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        // @ts-ignore
        await window.aistudio.openSelectKey();
      }
    };
    checkKey();
  }, []);

  // Auto-save logic
  useEffect(() => {
    const timer = setTimeout(() => {
      const { logs, ...rest } = state;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
      setIsSaved(true);
    }, 2000);
    setIsSaved(false);
    return () => clearTimeout(timer);
  }, [state.blocks, state.globalCss, state.accentColor, state.fontFamily, state.projectName, state.designTone, state.borderRadius, state.snapshots]);

  const handleNewProject = () => {
    const shouldOpenNewTab = confirm("Mở dự án mới trong tab riêng biệt?\n(Chọn Cancel để xóa trắng và tiếp tục tại tab này)");

    if (shouldOpenNewTab) {
      // Open current location with fresh parameter
      const freshUrl = window.location.origin + window.location.pathname + '?fresh=1';
      window.open(freshUrl, '_blank');
      addLog('info', 'Đang mở tab dự án mới...');
    } else {
      if (confirm("Xóa dự án hiện tại? Các thay đổi chưa được Snapshot sẽ bị mất.")) {
        setState(getInitialState());
        setInputSource('');
        setViewMode('edit');
        addLog('success', 'Workspace đã được reset hoàn toàn.');
      }
    }
  };

  const createSnapshot = () => {
    const { logs, snapshots, ...rest } = state;
    const timestamp = new Date().toLocaleString();
    const newSnapshot: Snapshot = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp,
      name: `${state.projectName} (Backup - ${timestamp})`,
      state: JSON.parse(JSON.stringify(rest))
    };
    setState(prev => ({
      ...prev,
      snapshots: [newSnapshot, ...prev.snapshots].slice(0, 20)
    }));
    addLog('success', 'Đã lưu Snapshot vào lịch sử hệ thống.');
  };

  const restoreSnapshot = (snapshot: Snapshot) => {
    if (confirm(`Bạn có chắc muốn quay lại phiên bản "${snapshot.name}"?`)) {
      setState(prev => ({
        ...prev,
        ...snapshot.state,
        logs: [{
          id: 'restore-' + Date.now(),
          timestamp: new Date().toLocaleTimeString(),
          type: 'info',
          message: `Khôi phục thành công từ: ${snapshot.timestamp}`
        }]
      }));
      setSidebarTab('blocks');
      setViewMode('preview');
      addLog('success', 'Hệ thống đã được khôi phục.');
    }
  };

  const deleteSnapshot = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm("Xóa bản lưu này?")) {
      setState(prev => ({
        ...prev,
        snapshots: prev.snapshots.filter(s => s.id !== id)
      }));
      addLog('warning', 'Đã xóa một Snapshot.');
    }
  };

  const handleSaveProject = () => {
    createSnapshot();
  };

  const generateWebsiteHtml = (isInternal: boolean = false) => {
    const content = state.blocks.map(b => 
      isInternal 
        ? `<div data-block-id="${b.id}" class="omni-block-wrapper relative">${b.html}</div>`
        : b.html
    ).join('\n');

    const annotateScript = isInternal ? `
      <script>
        (function() {
          const style = document.createElement('style');
          style.innerHTML = \`
            .omni-img-overlay {
              position: absolute; top: 12px; right: 12px; background: rgba(99, 102, 241, 0.95);
              color: white; padding: 6px 14px; border-radius: 10px; font-family: 'Inter', sans-serif;
              font-size: 11px; font-weight: 700; cursor: pointer; display: none; z-index: 10000;
              box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.4); border: 1px solid rgba(255,255,255,0.2);
              backdrop-filter: blur(4px); transition: all 0.2s;
            }
            .omni-img-overlay:hover { transform: scale(1.05); background: #4f46e5; }
            .omni-img-target { outline: 4px solid #6366f1 !important; outline-offset: -4px; cursor: pointer; transition: outline 0.1s; }
          \`;
          document.head.appendChild(style);
          const overlay = document.createElement('div');
          overlay.className = 'omni-img-overlay';
          overlay.innerHTML = 'REPLACE IMAGE';
          document.body.appendChild(overlay);
          let currentTargetImg = null;
          document.addEventListener('mouseover', (e) => {
            const img = e.target.closest('img');
            if (img) {
              currentTargetImg = img;
              img.classList.add('omni-img-target');
              const rect = img.getBoundingClientRect();
              overlay.style.display = 'block';
              overlay.style.top = (window.scrollY + rect.top + 12) + 'px';
              overlay.style.left = (window.scrollX + rect.right - 120) + 'px';
            }
          });
          overlay.addEventListener('click', () => {
            const input = document.createElement('input');
            input.type = 'file'; input.accept = 'image/*';
            input.onchange = (e) => {
              const file = e.target.files[0];
              const reader = new FileReader();
              reader.onload = (re) => {
                if (currentTargetImg) {
                  currentTargetImg.src = re.target.result;
                  const wrapper = currentTargetImg.closest('[data-block-id]');
                  if (wrapper) {
                    window.parent.postMessage({
                      type: 'UPDATE_BLOCK_HTML',
                      blockId: wrapper.getAttribute('data-block-id'),
                      newHtml: wrapper.innerHTML
                    }, '*');
                  }
                }
              };
              reader.readAsDataURL(file);
            };
            input.click();
          });
          document.addEventListener('mouseout', (e) => {
             if (currentTargetImg && !e.relatedTarget?.closest('.omni-img-overlay')) {
               currentTargetImg.classList.remove('omni-img-target');
             }
          });
        })();
      </script>
    ` : '';

    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>${state.metaTitle || state.projectName}</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          body { font-family: '${state.fontFamily}', sans-serif; scroll-behavior: smooth; margin: 0; padding: 0; background-color: white; color: #1e293b; }
          :root { --accent: ${state.accentColor}; --radius: ${state.borderRadius}; }
          ${state.globalCss}
          img:not([src]), img[src=""] { background: #f8fafc; min-height: 120px; display: block; border: 1px dashed #e2e8f0; }
        </style>
      </head>
      <body>
        ${content || '<div class="h-screen flex items-center justify-center text-slate-300 font-black uppercase tracking-[0.4em] bg-slate-50">Empty Canvas</div>'}
        ${annotateScript}
      </body>
      </html>
    `;
  };

  const internalHtml = useMemo(() => generateWebsiteHtml(true), [state.blocks, state.accentColor, state.fontFamily, state.globalCss, state.borderRadius, state.metaTitle, state.projectName, previewKey]);

  const processBlockImages = async (targetBlocks?: Block[]) => {
    const blocksToProcess = targetBlocks || state.blocks;
    for (const block of blocksToProcess) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgTags = Array.from(doc.querySelectorAll('img[data-ai-prompt]'));
      if (imgTags.length === 0) continue;

      setSyncingBlocks(prev => new Set(prev).add(block.id));
      for (const img of imgTags) {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) {
          try {
            const base64Image = await geminiService.generateAiImage(prompt);
            img.setAttribute('src', base64Image);
            img.removeAttribute('data-ai-prompt');
            const updatedHtml = doc.body.innerHTML;
            setState(prev => ({
              ...prev,
              blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: updatedHtml } : b)
            }));
            setPreviewKey(k => k + 1);
          } catch (err: any) {
            addLog('error', `Lỗi AI Image: ${block.name}`);
          }
        }
      }
      setSyncingBlocks(prev => {
        const next = new Set(prev);
        next.delete(block.id);
        return next;
      });
    }
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    addLog('info', `Gemini Engine đang phân tích kiến trúc...`);
    try {
      const isUpgrade = inputSource.includes('<') && inputSource.includes('>');
      const result = await geminiService.parseToBlocks(inputSource, state.designTone, isUpgrade ? inputSource : undefined);
      setState(prev => ({
        ...prev,
        blocks: result.blocks,
        globalCss: result.globalCss,
        selectedBlockId: result.blocks[0]?.id || null
      }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);
      addLog('success', isUpgrade ? 'Nâng cấp HTML hoàn tất.' : 'Dựng Layout module thành công.');
      setTimeout(() => processBlockImages(result.blocks), 500);
    } catch (e: any) {
      addLog('error', 'Build lỗi', e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const moveBlock = (index: number, direction: 'up' | 'down') => {
    const newBlocks = [...state.blocks];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newBlocks.length) return;
    [newBlocks[index], newBlocks[targetIndex]] = [newBlocks[targetIndex], newBlocks[index]];
    setState(prev => ({ ...prev, blocks: newBlocks }));
  };

  const handleExport = () => {
    const prodHtml = generateWebsiteHtml(false);
    const blob = new Blob([prodHtml], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; 
    a.download = `${state.projectName.toLowerCase().replace(/\s+/g, '-')}.html`; 
    a.click();
    addLog('success', 'Xuất bản thành công file HTML chuẩn SEO.');
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/95 backdrop-blur-xl px-6 flex items-center justify-between z-50 shadow-2xl">
        <div className="flex items-center gap-5">
          <div className="p-2.5 bg-indigo-600 rounded-2xl shadow-lg shadow-indigo-600/30 font-black flex items-center justify-center cursor-pointer hover:scale-110 transition-transform">
            <Infinity className="w-5 h-5 text-white" />
          </div>
          <div className="flex flex-col">
            <div className="flex items-center gap-3 group">
              {isEditingTitle ? (
                <input
                  autoFocus
                  className="bg-slate-900 border border-indigo-500/50 text-white text-sm font-black tracking-tighter uppercase px-2 py-0.5 rounded outline-none w-48"
                  value={state.projectName}
                  onChange={(e) => setState(prev => ({ ...prev, projectName: e.target.value }))}
                  onBlur={() => setIsEditingTitle(false)}
                  onKeyDown={(e) => e.key === 'Enter' && setIsEditingTitle(false)}
                />
              ) : (
                <h1 
                  onClick={() => setIsEditingTitle(true)}
                  className="text-sm font-black text-white tracking-tighter uppercase cursor-text hover:text-indigo-400 transition-colors flex items-center gap-2"
                >
                  {state.projectName}
                  <Edit3 className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                </h1>
              )}
              {isSaved ? (
                <div className="flex items-center gap-1 text-[7px] text-emerald-500 font-bold bg-emerald-500/10 px-2 py-0.5 rounded border border-emerald-500/20 uppercase tracking-widest"><Check className="w-2 h-2" /> Synced</div>
              ) : (
                <div className="flex items-center gap-1 text-[7px] text-amber-500 font-bold bg-amber-500/10 px-2 py-0.5 rounded border border-amber-500/20 animate-pulse uppercase tracking-widest"><Clock className="w-2 h-2" /> Saving</div>
              )}
            </div>
          </div>

          <div className="h-6 w-px bg-white/10 mx-1"></div>

          <button 
            onClick={handleNewProject}
            className="group flex items-center gap-1.5 px-3 py-1.5 bg-indigo-600/10 hover:bg-indigo-600 text-indigo-400 hover:text-white rounded-xl font-black text-[10px] transition-all border border-indigo-500/20 uppercase tracking-widest shadow-lg active:scale-95"
          >
            <Plus className="w-3.5 h-3.5 group-hover:rotate-90 transition-transform" /> New Project
          </button>
        </div>

        <div className="flex items-center gap-3">
          <button 
            onClick={handleSaveProject} 
            className="flex items-center gap-2 px-4 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-full font-black text-[10px] transition-all border border-white/5 shadow-inner uppercase tracking-wider active:scale-95"
          >
            <Save className="w-3.5 h-3.5 text-emerald-500" /> SNAPSHOT
          </button>

          <button onClick={() => setShowTerminal(!showTerminal)} className={`p-2.5 rounded-full transition-all border ${showTerminal ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-slate-800 border-white/5 text-slate-400 hover:bg-slate-700'}`}>
            <TerminalIcon className="w-4 h-4" />
          </button>

          <div className="h-6 w-px bg-white/5 mx-1"></div>

          <button onClick={() => setViewMode(viewMode === 'edit' ? 'preview' : 'edit')} className="flex items-center gap-2 px-5 py-2 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-full font-black text-xs transition-all border border-white/5 shadow-inner uppercase active:scale-95">
            {viewMode === 'edit' ? <Eye className="w-3.5 h-3.5 text-indigo-400" /> : <Code2 className="w-3.5 h-3.5 text-indigo-400" />}
            {viewMode === 'edit' ? 'PREVIEW' : 'EDITOR'}
          </button>

          <button onClick={handleExport} className="flex items-center gap-2 px-6 py-2 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full font-black text-xs transition-all shadow-xl shadow-indigo-600/30 active:scale-95 border border-indigo-400/20 uppercase">
            <DownloadCloud className="w-3.5 h-3.5" /> EXPORT
          </button>
        </div>
      </header>

      <main className="flex-1 flex overflow-hidden">
        <aside className="w-64 bg-[#0b0f1a] border-r border-white/5 flex flex-col shrink-0 shadow-xl">
          <div className="flex border-b border-white/5">
            <button 
              onClick={() => setSidebarTab('blocks')} 
              className={`flex-1 py-4 text-[10px] font-black uppercase tracking-[0.2em] transition-all ${sidebarTab === 'blocks' ? 'text-indigo-400 border-b-2 border-indigo-500 bg-indigo-500/5' : 'text-slate-500 hover:text-slate-300'}`}
            >
              Modules
            </button>
            <button 
              onClick={() => setSidebarTab('history')} 
              className={`flex-1 py-4 text-[10px] font-black uppercase tracking-[0.2em] transition-all ${sidebarTab === 'history' ? 'text-indigo-400 border-b-2 border-indigo-500 bg-indigo-500/5' : 'text-slate-500 hover:text-slate-300'}`}
            >
              History
            </button>
          </div>

          <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
            {sidebarTab === 'blocks' ? (
              <div className="space-y-2">
                {state.blocks.map((block, idx) => (
                  <div 
                    key={block.id} 
                    onClick={() => { setState(prev => ({ ...prev, selectedBlockId: block.id })); setViewMode('edit'); }}
                    className={`group p-3 rounded-xl cursor-pointer transition-all border relative ${state.selectedBlockId === block.id ? 'bg-indigo-600/10 border-indigo-500/30 text-white' : 'bg-transparent border-transparent hover:bg-white/5 text-slate-500'}`}
                  >
                    <div className="flex items-center justify-between">
                      <span className="text-[10px] font-black uppercase truncate tracking-tight">{block.name}</span>
                      <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button onClick={(e) => { e.stopPropagation(); moveBlock(idx, 'up'); }} disabled={idx === 0} className="p-0.5 hover:text-white disabled:opacity-20"><ChevronUp className="w-3 h-3" /></button>
                        <button onClick={(e) => { e.stopPropagation(); moveBlock(idx, 'down'); }} disabled={idx === state.blocks.length - 1} className="p-0.5 hover:text-white disabled:opacity-20"><ChevronDown className="w-3 h-3" /></button>
                        <button onClick={(e) => { e.stopPropagation(); if(confirm('Xóa module?')) setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== block.id) })); }} className="p-0.5 hover:text-red-400"><Trash2 className="w-3 h-3" /></button>
                      </div>
                    </div>
                  </div>
                ))}
                {state.blocks.length === 0 && <div className="text-[9px] text-slate-600 italic text-center py-12 px-4 uppercase tracking-widest font-black opacity-40">No modules built.</div>}
              </div>
            ) : (
              <div className="space-y-4">
                {state.snapshots.map((snap) => (
                  <div 
                    key={snap.id} 
                    onClick={() => restoreSnapshot(snap)}
                    className="p-4 rounded-2xl bg-slate-900/50 border border-white/5 hover:border-indigo-500/40 cursor-pointer transition-all group relative overflow-hidden"
                  >
                    <div className="absolute inset-0 bg-indigo-500/5 opacity-0 group-hover:opacity-100 transition-opacity"></div>
                    <div className="text-[10px] font-black text-white uppercase truncate mb-1.5 relative z-10">{snap.name}</div>
                    <div className="flex items-center gap-2 text-[8px] text-slate-500 font-mono relative z-10">
                      <Clock className="w-2.5 h-2.5" /> {snap.timestamp}
                    </div>
                    <div className="mt-3 opacity-0 group-hover:opacity-100 transition-all transform translate-y-2 group-hover:translate-y-0 flex justify-between items-center relative z-10">
                      <button className="text-[9px] font-black text-indigo-400 flex items-center gap-1 hover:underline"><RotateCcw className="w-3 h-3" /> RESTORE</button>
                      <button 
                        onClick={(e) => deleteSnapshot(e, snap.id)}
                        className="text-slate-600 hover:text-red-400 p-1"
                      >
                        <Trash2 className="w-3 h-3" />
                      </button>
                    </div>
                  </div>
                ))}
                {state.snapshots.length === 0 && <div className="text-[9px] text-slate-600 italic text-center py-12 px-4 uppercase tracking-widest font-black opacity-40">Snapshot history empty.</div>}
              </div>
            )}
          </div>

          <div className="p-5 border-t border-white/5 bg-slate-950/80">
             <div className="text-[9px] font-black text-slate-500 uppercase mb-3 tracking-widest">Global Presets</div>
             <div className="space-y-3">
               <select 
                 value={state.designTone} 
                 onChange={(e) => setState(prev => ({ ...prev, designTone: e.target.value as DesignTone }))}
                 className="w-full bg-slate-900 border border-white/10 rounded-xl p-2.5 text-[10px] font-black text-indigo-400 outline-none uppercase shadow-inner"
               >
                 <option value="professional">Professional</option>
                 <option value="minimalist">Minimalist</option>
                 <option value="cyberpunk">Cyberpunk</option>
                 <option value="playful">Playful</option>
                 <option value="brutalist">Brutalist</option>
               </select>
             </div>
          </div>
        </aside>

        <section className="flex-1 flex flex-col overflow-hidden bg-[#020617] relative">
          {viewMode === 'edit' ? (
            <div className="flex-1 flex flex-col p-6 overflow-hidden">
               {state.blocks.length > 0 ? (
                  <div className="flex-1 bg-[#0b0f1a] rounded-[2rem] border border-white/5 shadow-2xl flex flex-col overflow-hidden animate-in fade-in duration-300">
                    <div className="p-4 bg-[#131929] border-b border-white/5 px-8 flex justify-between items-center">
                       <div className="flex items-center gap-3">
                          <Layout className="w-4 h-4 text-indigo-400" />
                          <span className="text-[11px] font-black text-white uppercase tracking-widest">{state.blocks.find(b => b.id === state.selectedBlockId)?.name}</span>
                       </div>
                       <div className="flex items-center gap-4">
                         <span className="text-[9px] text-slate-600 font-mono italic">Tailwind + Semantic Module</span>
                         <button onClick={() => setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== state.selectedBlockId), selectedBlockId: prev.blocks.find(b => b.id !== state.selectedBlockId)?.id || null }))} className="text-slate-600 hover:text-red-400 transition-colors"><Trash2 className="w-4 h-4" /></button>
                       </div>
                    </div>
                    <textarea
                      value={state.blocks.find(b => b.id === state.selectedBlockId)?.html || ''}
                      onChange={(e) => setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === state.selectedBlockId ? { ...b, html: e.target.value } : b) }))}
                      className="flex-1 p-10 bg-transparent text-slate-300 code-font text-sm outline-none resize-none custom-scrollbar leading-relaxed selection:bg-indigo-500/30"
                      spellCheck={false}
                    />
                  </div>
               ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-center max-w-xl mx-auto animate-in zoom-in duration-500">
                    <div className="w-20 h-20 bg-indigo-600/10 rounded-[2.5rem] flex items-center justify-center mb-10 relative">
                      <Wand2 className="w-10 h-10 text-indigo-500 animate-pulse" />
                      <div className="absolute inset-0 border-2 border-indigo-500/20 rounded-[2.5rem] animate-ping opacity-20"></div>
                    </div>
                    <h2 className="text-4xl font-black text-white mb-3 uppercase tracking-tighter italic">HTML Forge 2025</h2>
                    <p className="text-slate-500 text-[10px] mb-12 uppercase tracking-[0.4em] font-black opacity-60">Modular semantic architecture engine</p>
                    <textarea 
                      value={inputSource}
                      onChange={(e) => setInputSource(e.target.value)}
                      placeholder="Mô tả dự án hoặc dán mã nguồn cần nâng cấp (VD: Landing page đại lý bất động sản cao cấp)..."
                      className="w-full h-48 bg-slate-900 border border-white/10 rounded-3xl p-8 text-sm outline-none focus:border-indigo-500/50 mb-8 text-white shadow-2xl resize-none transition-all placeholder:text-slate-700 selection:bg-indigo-500/30"
                    />
                    <button onClick={handleBuild} disabled={isProcessing} className="w-full py-5 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-[0.25em] hover:scale-[1.02] active:scale-95 transition-all shadow-2xl shadow-indigo-600/40 disabled:opacity-50 flex items-center justify-center gap-4 text-xs">
                      {isProcessing ? <><Loader2 className="w-5 h-5 animate-spin" /> ENGINE PROCESSING...</> : inputSource.includes('<') ? 'UPGRADE ARCHITECTURE' : 'INITIALIZE BUILD'}
                    </button>
                  </div>
               )}
            </div>
          ) : (
            <div className="flex-1 flex flex-col overflow-hidden relative">
              <div className="h-12 border-b border-white/5 bg-[#0b0f1a] flex items-center justify-center gap-6 shrink-0 z-10">
                <button onClick={() => setPreviewDevice('mobile')} className={`p-2 rounded-xl transition-all ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}><Smartphone className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('tablet')} className={`p-2 rounded-xl transition-all ${previewDevice === 'tablet' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}><TabletIcon className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('desktop')} className={`p-2 rounded-xl transition-all ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white shadow-lg' : 'text-slate-500 hover:text-slate-300'}`}><Monitor className="w-4 h-4" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-12 bg-[#020617] flex justify-center items-start custom-scrollbar relative">
                <div key={previewKey} className={`flex-shrink-0 bg-white shadow-[0_0_100px_rgba(0,0,0,0.6)] transition-all duration-700 ease-in-out rounded-lg overflow-hidden border border-white/10 ${previewDevice === 'desktop' ? 'w-[1200px]' : previewDevice === 'tablet' ? 'w-[768px]' : 'w-[375px]'}`}>
                  <iframe srcDoc={internalHtml} className="w-full h-[3000px] border-none" sandbox="allow-scripts allow-same-origin" />
                </div>
              </div>

              {showTerminal && (
                <div className="absolute bottom-0 left-0 right-0 h-64 bg-[#0b0f1a] border-t border-white/10 z-[60] flex flex-col shadow-2xl animate-in slide-in-from-bottom duration-300">
                  <div className="h-10 bg-[#131929] border-b border-white/5 flex items-center justify-between px-8 shrink-0 text-[10px] font-black uppercase tracking-[0.2em]">
                    <div className="flex items-center gap-2 text-indigo-400"><TerminalIcon className="w-4 h-4" /> System Protocol Status</div>
                    <button onClick={() => setShowTerminal(false)} className="hover:text-white transition-colors"><X className="w-4 h-4" /></button>
                  </div>
                  <div className="flex-1 overflow-y-auto p-6 space-y-1 code-font custom-scrollbar bg-slate-950 text-[10px]">
                    {state.logs.map(log => (
                      <div key={log.id} className="flex gap-4 text-slate-400 hover:bg-white/5 rounded-md px-2 py-0.5">
                        <span className="shrink-0 text-slate-600 font-mono">[{log.timestamp}]</span>
                        <span className={`font-black w-20 uppercase ${log.type === 'error' ? 'text-red-500' : log.type === 'success' ? 'text-emerald-500' : 'text-indigo-400'}`}>{log.type}</span>
                        <div className="flex-1 text-slate-300">{log.message}</div>
                      </div>
                    ))}
                    {state.logs.length === 0 && <div className="text-slate-800 italic uppercase tracking-widest font-black opacity-50 py-10 text-center">No protocol traffic recorded.</div>}
                  </div>
                </div>
              )}
            </div>
          )}
        </section>

        <aside className="w-72 bg-[#0b0f1a] border-l border-white/5 p-8 flex flex-col gap-8 shrink-0 overflow-y-auto custom-scrollbar shadow-2xl">
           <div className="flex items-center gap-3">
              <Palette className="w-4 h-4 text-indigo-400" />
              <h3 className="text-[11px] font-black text-white uppercase tracking-[0.2em]">Identity Suite</h3>
           </div>

           <div className="space-y-8">
              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">Accent Master</label>
                <div className="flex items-center gap-4 bg-slate-900/50 p-3 rounded-2xl border border-white/10 shadow-inner group">
                  <input type="color" value={state.accentColor} onChange={(e) => setState(prev => ({ ...prev, accentColor: e.target.value }))} className="w-10 h-10 bg-transparent cursor-pointer border-none rounded-xl" />
                  <span className="text-[11px] font-mono font-black text-white uppercase tracking-tighter group-hover:text-indigo-400 transition-colors">{state.accentColor}</span>
                </div>
              </div>

              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">Typography interface</label>
                <select value={state.fontFamily} onChange={(e) => setState(prev => ({ ...prev, fontFamily: e.target.value }))} className="w-full bg-slate-900 border border-white/10 rounded-2xl p-3.5 text-[11px] font-black text-white outline-none focus:border-indigo-500/50 transition-all shadow-xl">
                  <option value="Inter">Inter (Global standard)</option>
                  <option value="Playfair Display">Playfair (High Luxury)</option>
                  <option value="Fira Code">Fira Code (Modern Tech)</option>
                  <option value="Montserrat">Montserrat (Geometric)</option>
                </select>
              </div>

              <div className="space-y-3">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">Geometric radius</label>
                <select value={state.borderRadius} onChange={(e) => setState(prev => ({ ...prev, borderRadius: e.target.value }))} className="w-full bg-slate-900 border border-white/10 rounded-2xl p-3.5 text-[11px] font-black text-white outline-none focus:border-indigo-500/50 transition-all shadow-xl">
                  <option value="0px">SHARP [0px]</option>
                  <option value="0.75rem">MODERN [12px]</option>
                  <option value="1.5rem">ROUNDED [24px]</option>
                  <option value="999px">PILL CURVE</option>
                </select>
              </div>
           </div>

           <div className="mt-auto p-5 bg-indigo-600/5 border border-indigo-500/20 rounded-3xl space-y-4">
              <div className="flex items-center gap-2">
                 <ShieldCheck className="w-4 h-4 text-emerald-400" />
                 <span className="text-[10px] font-black uppercase text-white tracking-widest">Annotate Engine</span>
              </div>
              <p className="text-[10px] text-slate-500 leading-relaxed italic opacity-80">
                Preview mode cho phép thay đổi hình ảnh trực tiếp qua AI Annotations. 
                Mã nguồn xuất ra sẽ tự động được làm sạch 100%.
              </p>
           </div>
        </aside>
      </main>

      {isProcessing && (
        <div className="absolute inset-0 bg-slate-950/98 backdrop-blur-3xl z-[100] flex flex-col items-center justify-center p-12 text-center animate-in fade-in duration-700">
          <div className="relative mb-12">
            <div className="w-28 h-28 border-2 border-indigo-500 border-t-transparent rounded-[2.5rem] animate-spin"></div>
            <Zap className="absolute inset-0 m-auto w-10 h-10 text-indigo-500 animate-pulse" />
          </div>
          <h2 className="text-5xl font-black text-white mb-6 tracking-tighter uppercase italic">Engine Crafting...</h2>
          <div className="text-slate-500 text-[11px] font-black uppercase tracking-[0.6em] animate-pulse flex items-center gap-4">
            <Sparkles className="w-4 h-4 text-amber-500" /> 2025 Protocol Active <Sparkles className="w-4 h-4 text-amber-500" />
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, LogEntry, DesignTone, Snapshot } from './types';
import { 
  Sparkles, Zap, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, 
  Smartphone, Tablet as TabletIcon, Monitor, Trash2, 
  Save, RefreshCw, X, Layout, Palette, 
  ShieldCheck, DownloadCloud, Key, Terminal as TerminalIcon, 
  Trash, ExternalLink, Eraser, ChevronUp, ChevronDown, Edit3, Type,
  Upload, Image as ImageIcon, Plus, FileCode, History, RotateCcw,
  Wand2, Clock, Check
} from 'lucide-react';

const STORAGE_KEY = 'omni_gen_v3_state_pro_final';

const getInitialState = (): OmniState => ({
  projectName: "Untitled Project",
  metaTitle: "Omni Gen Website",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#6366f1",
  fontFamily: "Inter",
  designTone: 'professional',
  borderRadius: '0.75rem',
  logs: [],
  snapshots: []
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [sidebarTab, setSidebarTab] = useState<'blocks' | 'history'>('blocks');

  const addLog = (type: LogEntry['type'], message: string, details?: string) => {
    const newLog: LogEntry = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      details
    };
    setState(prev => ({
      ...prev,
      logs: [newLog, ...prev.logs].slice(0, 100)
    }));
  };

  useEffect(() => {
    const handleIframeMessage = (event: MessageEvent) => {
      if (event.data?.type === 'UPDATE_BLOCK_HTML') {
        const { blockId, newHtml } = event.data;
        setState(prev => ({
          ...prev,
          blocks: prev.blocks.map(b => b.id === blockId ? { ...b, html: newHtml } : b)
        }));
        addLog('success', 'Đã cập nhật module từ Preview Annotate.');
      }
    };
    window.addEventListener('message', handleIframeMessage);
    return () => window.removeEventListener('message', handleIframeMessage);
  }, []);

  useEffect(() => {
    const url = new URL(window.location.href);
    const isFresh = url.searchParams.get('fresh') === '1';

    if (isFresh) {
      // Khởi tạo trạng thái mới nếu có flag fresh
      setState(getInitialState());
      // Xóa flag khỏi URL để tránh loop khi refresh
      url.searchParams.delete('fresh');
      window.history.replaceState({}, document.title, url.toString());
      addLog('info', 'Đã khởi tạo không gian làm việc mới (Fresh Mode).');
    } else {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved) {
        try {
          const parsed = JSON.parse(saved);
          setState({ ...parsed, logs: [] });
        } catch (e) {
          addLog('error', 'Lỗi khôi phục dữ liệu từ bộ nhớ trình duyệt.');
        }
      }
    }

    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        // @ts-ignore
        await window.aistudio.openSelectKey();
      }
    };
    checkKey();
  }, []);

  // Auto-save logic
  useEffect(() => {
    const timer = setTimeout(() => {
      const { logs, ...rest } = state;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
      setIsSaved(true);
    }, 2000);
    setIsSaved(false);
    return () => clearTimeout(timer);
  }, [state.blocks, state.globalCss, state.accentColor, state.fontFamily, state.projectName, state.designTone, state.borderRadius, state.snapshots]);

  const handleNewProject = () => {
    const currentUrl = new URL(window.location.href);
    currentUrl.searchParams.set('fresh', '1');

    // Thử mở tab mới
    const newTab = window.open(currentUrl.toString(), '_blank');

    if (newTab) {
      addLog('success', 'Đã mở dự án mới trong tab mới.');
    } else {
      // Fallback nếu trình duyệt chặn popup
      if (confirm("Trình duyệt đã chặn tab mới. Bạn có muốn reset dự án ngay tại tab này không?")) {
        setState(getInitialState());
        setInputSource('');
        setViewMode('edit');
        addLog('success', 'Workspace đã được làm mới.');
      }
    }
  };

  const createSnapshot = () => {
    const { logs, snapshots, ...rest } = state;
    const timestamp = new Date().toLocaleString();
    const newSnapshot: Snapshot = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp,
      name: `${state.projectName} (${timestamp})`,
      state: JSON.parse(JSON.stringify(rest))
    };
    setState(prev => ({
      ...prev,
      snapshots: [newSnapshot, ...prev.snapshots].slice(0, 20)
    }));
    addLog('success', 'Đã lưu Snapshot thành công.');
  };

  const restoreSnapshot = (snapshot: Snapshot) => {
    if (confirm(`Khôi phục phiên bản "${snapshot.name}"?`)) {
      setState(prev => ({
        ...prev,
        ...snapshot.state,
        logs: [{
          id: 'restore-' + Date.now(),
          timestamp: new Date().toLocaleTimeString(),
          type: 'info',
          message: `Đã khôi phục từ: ${snapshot.timestamp}`
        }]
      }));
      setSidebarTab('blocks');
      setViewMode('preview');
      addLog('success', 'Khôi phục hoàn tất.');
    }
  };

  const deleteSnapshot = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (confirm("Xóa bản lưu này?")) {
      setState(prev => ({
        ...prev,
        snapshots: prev.snapshots.filter(s => s.id !== id)
      }));
      addLog('warning', 'Đã xóa Snapshot.');
    }
  };

  const generateWebsiteHtml = (isInternal: boolean = false) => {
    const content = state.blocks.map(b => 
      isInternal 
        ? `<div data-block-id="${b.id}" class="omni-block-wrapper relative">${b.html}</div>`
        : b.html
    ).join('\n');

    const annotateScript = isInternal ? `
      <script>
        (function() {
          const style = document.createElement('style');
          style.innerHTML = \`
            .omni-img-overlay {
              position: absolute; top: 12px; right: 12px; background: #6366f1;
              color: white; padding: 6px 14px; border-radius: 10px; font-family: 'Inter', sans-serif;
              font-size: 11px; font-weight: 700; cursor: pointer; display: none; z-index: 10000;
              box-shadow: 0 10px 25px rgba(0, 0, 0, 0.4); border: 1px solid rgba(255,255,255,0.2);
              backdrop-filter: blur(8px);
            }
            .omni-img-target { outline: 4px solid #6366f1 !important; outline-offset: -4px; cursor: pointer; }
          \`;
          document.head.appendChild(style);
          const overlay = document.createElement('div');
          overlay.className = 'omni-img-overlay';
          overlay.innerHTML = 'REPLACE WITH AI';
          document.body.appendChild(overlay);
          let currentTargetImg = null;
          document.addEventListener('mouseover', (e) => {
            const img = e.target.closest('img');
            if (img) {
              currentTargetImg = img;
              img.classList.add('omni-img-target');
              const rect = img.getBoundingClientRect();
              overlay.style.display = 'block';
              overlay.style.top = (window.scrollY + rect.top + 12) + 'px';
              overlay.style.left = (window.scrollX + rect.right - 130) + 'px';
            }
          });
          overlay.addEventListener('click', () => {
            const input = document.createElement('input');
            input.type = 'file'; input.accept = 'image/*';
            input.onchange = (e) => {
              const file = e.target.files[0];
              const reader = new FileReader();
              reader.onload = (re) => {
                if (currentTargetImg) {
                  currentTargetImg.src = re.target.result;
                  const wrapper = currentTargetImg.closest('[data-block-id]');
                  if (wrapper) {
                    window.parent.postMessage({
                      type: 'UPDATE_BLOCK_HTML',
                      blockId: wrapper.getAttribute('data-block-id'),
                      newHtml: wrapper.innerHTML
                    }, '*');
                  }
                }
              };
              reader.readAsDataURL(file);
            };
            input.click();
          });
          document.addEventListener('mouseout', (e) => {
             if (currentTargetImg && !e.relatedTarget?.closest('.omni-img-overlay')) {
               currentTargetImg.classList.remove('omni-img-target');
             }
          });
        })();
      </script>
    ` : '';

    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>${state.metaTitle || state.projectName}</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          body { font-family: '${state.fontFamily}', sans-serif; scroll-behavior: smooth; margin: 0; padding: 0; }
          :root { --accent: ${state.accentColor}; --radius: ${state.borderRadius}; }
          ${state.globalCss}
          img:not([src]), img[src=""] { background: #f1f5f9; min-height: 150px; display: block; }
        </style>
      </head>
      <body>
        ${content || '<div class="h-screen flex items-center justify-center text-slate-300 font-black uppercase tracking-[0.5em] bg-slate-50">Studio Canvas</div>'}
        ${annotateScript}
      </body>
      </html>
    `;
  };

  const internalHtml = useMemo(() => generateWebsiteHtml(true), [state.blocks, state.accentColor, state.fontFamily, state.globalCss, state.borderRadius, state.metaTitle, state.projectName, previewKey]);

  const processBlockImages = async (targetBlocks?: Block[]) => {
    const blocksToProcess = targetBlocks || state.blocks;
    for (const block of blocksToProcess) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgTags = Array.from(doc.querySelectorAll('img[data-ai-prompt]'));
      if (imgTags.length === 0) continue;

      setSyncingBlocks(prev => new Set(prev).add(block.id));
      for (const img of imgTags) {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) {
          try {
            const base64Image = await geminiService.generateAiImage(prompt);
            img.setAttribute('src', base64Image);
            img.removeAttribute('data-ai-prompt');
            const updatedHtml = doc.body.innerHTML;
            setState(prev => ({
              ...prev,
              blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: updatedHtml } : b)
            }));
            setPreviewKey(k => k + 1);
          } catch (err: any) {
            addLog('error', `Lỗi tạo ảnh: ${block.name}`);
          }
        }
      }
      setSyncingBlocks(prev => {
        const next = new Set(prev);
        next.delete(block.id);
        return next;
      });
    }
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    addLog('info', `Gemini Engine đang thi công kiến trúc...`);
    try {
      const isUpgrade = inputSource.includes('<') && inputSource.includes('>');
      const result = await geminiService.parseToBlocks(inputSource, state.designTone, isUpgrade ? inputSource : undefined);
      setState(prev => ({
        ...prev,
        blocks: result.blocks,
        globalCss: result.globalCss,
        selectedBlockId: result.blocks[0]?.id || null
      }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);
      addLog('success', isUpgrade ? 'Nâng cấp mã nguồn thành công.' : 'Dựng layout module hoàn tất.');
      setTimeout(() => processBlockImages(result.blocks), 500);
    } catch (e: any) {
      addLog('error', 'Build thất bại', e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const moveBlock = (index: number, direction: 'up' | 'down') => {
    const newBlocks = [...state.blocks];
    const targetIndex = direction === 'up' ? index - 1 : index + 1;
    if (targetIndex < 0 || targetIndex >= newBlocks.length) return;
    [newBlocks[index], newBlocks[targetIndex]] = [newBlocks[targetIndex], newBlocks[index]];
    setState(prev => ({ ...prev, blocks: newBlocks }));
  };

  const handleExport = () => {
    const prodHtml = generateWebsiteHtml(false);
    const blob = new Blob([prodHtml], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; 
    a.download = `${state.projectName.toLowerCase().replace(/\s+/g, '-')}.html`; 
    a.click();
    addLog('success', 'Đã xuất file HTML thương mại.');
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <header className="h-16 border-b border-white/5 bg-[#0b0f1a]/95 backdrop-blur-xl px-6 flex items-center justify-between z-50 shadow-2xl">
        <div className="flex items-center gap-5">
          <div className="p-2.5 bg-indigo-600 rounded-2xl shadow-lg shadow-indigo-600/30 font-black flex items-center justify-center cursor-pointer hover:rotate-12 transition-transform">
            <Infinity className="w-5 h-5 text-white" />
          </div>
          <div className="flex flex-col">
            <div className="flex items-center gap-3 group">
              {isEditingTitle ? (
                <input
                  autoFocus
                  className="bg-slate-900 border border-indigo-500/50 text-white text-sm font-black tracking-tighter uppercase px-2 py-0.5 rounded outline-none w-48"
                  value={state.projectName}
                  onChange={(e) => setState(prev => ({ ...prev, projectName: e.target.value }))}
                  onBlur={() => setIsEditingTitle(false)}
                  onKeyDown={(e) => e.key === 'Enter' && setIsEditingTitle(false)}
                />
              ) : (
                <h1 
                  onClick={() => setIsEditingTitle(true)}
                  className="text-sm font-black text-white tracking-tighter uppercase cursor-text hover:text-indigo-400 transition-colors flex items-center gap-2"
                >
                  {state.projectName}
                  <Edit3 className="w-3 h-3 opacity-0 group-hover:opacity-100 transition-opacity" />
                </h1>
              )}
              {isSaved ? (
                <div className="flex items-center gap-1 text-[7px] text-emerald-500 font-bold bg-emerald-500/10 px-2 py-0.5 rounded border border-emerald-500/20 uppercase tracking-widest"><Check className="w-2 h-2" /> Synced</div>
              ) : (
                <div className="flex items-center gap-1 text-[7px] text-amber-500 font-bold bg-amber-500/10 px-2 py-0.5 rounded border border-amber-500/20 animate-pulse uppercase tracking-widest"><Clock className="w-2 h-2" /> Saving</div>
              )}
            </div>
          </div>

          <div className="h-6 w-px bg-white/10 mx-1"></div>

          <button 
