import { GoogleGenAI, Type } from "@google/genai";
import { Block, DesignTone } from "../types";

const TEXT_MODEL = 'gemini-3-pro-preview';
const IMAGE_MODEL = 'gemini-3-pro-image-preview';

export class GeminiService {
  private getAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private async handlePotentialKeyError(error: any): Promise<never> {
    if (error?.message?.includes("Requested entity was not found.") || error?.message?.includes("API_KEY_INVALID")) {
      // @ts-ignore
      if (window.aistudio) await window.aistudio.openSelectKey();
    }
    throw error;
  }

  async parseToBlocks(prompt: string, tone: DesignTone = 'professional', existingHtml?: string): Promise<{ blocks: Block[], globalCss: string }> {
    const ai = this.getAI();

    const toneGuidelines = {
      professional: "Clean, high-trust corporate aesthetic. Use generous whitespace and standard business typography.",
      minimalist: "Extreme focus on content. Stripped down elements, thin lines, and monochrome palette with one accent.",
      cyberpunk: "High contrast, dark theme, neon glowing accents, glitch effects, and futuristic decorative elements.",
      playful: "Rounded corners, vibrant pastel colors, friendly typography, and soft shadows.",
      brutalist: "Raw, unpolished look. Large bold text, thick borders, high-contrast black/white, and non-traditional layouts."
    };

    const systemInstruction = `
      You are the "Omni-Builder Architect" specializing in ${tone.toUpperCase()} design.
      Design Philosophy: ${toneGuidelines[tone]}

      Rules:
      1. Break into logical blocks using Tailwind CSS.
      2. For EVERY image location, use an <img> tag with a 'data-ai-prompt' attribute containing a highly detailed visual description in English.
      3. Match the visual description of images to the ${tone} style.
      4. Do NOT use external URLs. Leave 'src' empty.
      5. Return ONLY a JSON object with 'blocks' and 'globalCss'.
    `;

    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Input Request: ${prompt}\n\nExisting HTML: ${existingHtml || 'None'}`,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              blocks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    type: { type: Type.STRING },
                    name: { type: Type.STRING },
                    html: { type: Type.STRING }
                  },
                  required: ["id", "type", "name", "html"]
                }
              },
              globalCss: { type: Type.STRING }
            },
            required: ["blocks", "globalCss"]
          }
        }
      });

      return JSON.parse(response.text || '{"blocks": [], "globalCss": ""}');
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }

  async generateSingleBlock(prompt: string, tone: DesignTone, context: string): Promise<Block> {
    const ai = this.getAI();
    const systemInstruction = `
      You are an expert UI developer. Generate ONE single HTML block using Tailwind CSS.
      Style: ${tone.toUpperCase()}.
      Context of current page: ${context.substring(0, 1000)}...

      Rules:
      1. Return a single block as a JSON object.
      2. Use 'data-ai-prompt' for images.
      3. Ensure it blends perfectly with the existing page style.
      4. Output only JSON.
    `;

    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Request to add a new section: ${prompt}`,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              type: { type: Type.STRING },
              name: { type: Type.STRING },
              html: { type: Type.STRING }
            },
            required: ["id", "type", "name", "html"]
          }
        }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }

  async generateAiImage(prompt: string): Promise<string> {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: IMAGE_MODEL,
        contents: {
          parts: [{ text: `${prompt}, high resolution, commercial photography, 8k, highly detailed, professional lighting` }]
        },
        config: {
          imageConfig: {
            aspectRatio: "16:9",
            imageSize: "1K"
          }
        }
      });

      const candidate = response.candidates?.[0];
      if (!candidate) throw new Error("No image generated");

      for (const part of candidate.content.parts) {
        if (part.inlineData) {
          return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
        }
      }
      throw new Error("No image data found in response");
    } catch (e) {
      console.error("Gemini Image Generation Error:", e);
      return this.handlePotentialKeyError(e);
    }
  }
}

export const geminiService = new GeminiService();

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, LogEntry, DesignTone, Snapshot } from './types';
import { 
  Sparkles, Zap, Download, CheckCircle2, 
  Loader2, Eye, Code2, Infinity, 
  Smartphone, Tablet as TabletIcon, Monitor, Trash2, 
  Save, RefreshCw, X, Layout, Palette, 
  ShieldCheck, DownloadCloud, Key, Terminal as TerminalIcon, 
  Trash, ExternalLink, Eraser, ChevronUp, ChevronDown, Edit3, Type,
  Upload, Image as ImageIcon, FileCode, History, RotateCcw,
  Wand2, Plus
} from 'lucide-react';

const STORAGE_KEY = 'omni_gen_v3_state_pro_final';

const getInitialState = (): OmniState => ({
  projectName: "Untitled Project",
  metaTitle: "Omni Gen Website",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#6366f1",
  fontFamily: "Inter",
  designTone: 'professional',
  borderRadius: '0.75rem',
  logs: [],
  snapshots: []
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [isAddingModule, setIsAddingModule] = useState(false);
  const [newModuleQuery, setNewModuleQuery] = useState('');
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [sidebarTab, setSidebarTab] = useState<'blocks' | 'history'>('blocks');

  const addLog = (type: LogEntry['type'], message: string, details?: string) => {
    const newLog: LogEntry = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      details
    };
    setState(prev => ({
      ...prev,
      logs: [newLog, ...prev.logs].slice(0, 100)
    }));
  };

  useEffect(() => {
    const handleIframeMessage = (event: MessageEvent) => {
      if (event.data?.type === 'UPDATE_BLOCK_HTML') {
        const { blockId, newHtml } = event.data;
        setState(prev => ({
          ...prev,
          blocks: prev.blocks.map(b => b.id === blockId ? { ...b, html: newHtml } : b)
        }));
        addLog('success', 'Đã cập nhật module từ Preview Annotate.');
      }
    };
    window.addEventListener('message', handleIframeMessage);
    return () => window.removeEventListener('message', handleIframeMessage);
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setState({ ...parsed, logs: [] });
      } catch (e) {
        addLog('error', 'Lỗi khôi phục dữ liệu.');
      }
    }

    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        // @ts-ignore
        await window.aistudio.openSelectKey();
      }
    };
    checkKey();
  }, []);

  // Auto-save logic
  useEffect(() => {
    const timer = setTimeout(() => {
      const { logs, ...rest } = state;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
      setIsSaved(true);
    }, 2000);
    setIsSaved(false);
    return () => clearTimeout(timer);
  }, [state.blocks, state.globalCss, state.accentColor, state.fontFamily, state.projectName, state.designTone, state.borderRadius, state.snapshots]);

  const createSnapshot = () => {
    const { logs, snapshots, ...rest } = state;
    const newSnapshot: Snapshot = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleString(),
      name: `${state.projectName} (Backup ${state.snapshots.length + 1})`,
      state: JSON.parse(JSON.stringify(rest))
    };
    setState(prev => ({
      ...prev,
      snapshots: [newSnapshot, ...prev.snapshots].slice(0, 15)
    }));
    addLog('success', 'Đã lưu Snapshot thành công.');
  };

  const restoreSnapshot = (snapshot: Snapshot) => {
    if (confirm(`Khôi phục phiên bản "${snapshot.name}"? Dữ liệu hiện tại sẽ bị thay thế.`)) {
      setState(prev => ({
        ...prev,
        ...snapshot.state,
        logs: [{
          id: 'restore-' + Date.now(),
          timestamp: new Date().toLocaleTimeString(),
          type: 'info',
          message: `Đã khôi phục từ snapshot: ${snapshot.name}`
        }]
      }));
      setSidebarTab('blocks');
      addLog('success', 'Khôi phục hoàn tất.');
    }
  };

  const generateWebsiteHtml = (isInternal: boolean = false) => {
    const content = state.blocks.map(b => 
      isInternal 
        ? `<div data-block-id="${b.id}" class="omni-block-wrapper relative">${b.html}</div>`
        : b.html
    ).join('\n');

    const annotateScript = isInternal ? `
      <script>
        (function() {
          const style = document.createElement('style');
          style.innerHTML = \`
            .omni-img-overlay {
              position: absolute; top: 8px; right: 8px; background: rgba(79, 70, 229, 0.95);
              color: white; padding: 6px 12px; border-radius: 8px; font-family: sans-serif;
              font-size: 10px; font-weight: 800; cursor: pointer; display: none; z-index: 10000;
              box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.3); border: 1px solid rgba(255,255,255,0.2);
            }
            .omni-img-target { outline: 3px solid #6366f1 !important; outline-offset: -3px; cursor: pointer; }
          \`;
          document.head.appendChild(style);
          const overlay = document.createElement('div');
          overlay.className = 'omni-img-overlay';
          overlay.innerHTML = 'CHANGE IMAGE';
          document.body.appendChild(overlay);
          let currentTargetImg = null;
          document.addEventListener('mouseover', (e) => {
            const img = e.target.closest('img');
            if (img) {
              currentTargetImg = img;
              img.classList.add('omni-img-target');
              const rect = img.getBoundingClientRect();
              overlay.style.display = 'block';
              overlay.style.top = (window.scrollY + rect.top + 8) + 'px';
              overlay.style.left = (window.scrollX + rect.right - 100) + 'px';
            }
          });
          overlay.addEventListener('click', () => {
            const input = document.createElement('input');
            input.type = 'file'; input.accept = 'image/*';
            input.onchange = (e) => {
              const file = e.target.files[0];
              const reader = new FileReader();
              reader.onload = (re) => {
                if (currentTargetImg) {
                  currentTargetImg.src = re.target.result;
                  const wrapper = currentTargetImg.closest('[data-block-id]');
                  if (wrapper) {
                    window.parent.postMessage({
                      type: 'UPDATE_BLOCK_HTML',
                      blockId: wrapper.getAttribute('data-block-id'),
                      newHtml: wrapper.innerHTML
                    }, '*');
                  }
                }
              };
              reader.readAsDataURL(file);
            };
            input.click();
          });
        })();
      </script>
    ` : '';

    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>${state.metaTitle || state.projectName}</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          body { font-family: '${state.fontFamily}', sans-serif; scroll-behavior: smooth; margin: 0; padding: 0; background-color: white; color: #1e293b; }
          :root { --accent: ${state.accentColor}; --radius: ${state.borderRadius}; }
          ${state.globalCss}
          img:not([src]), img[src=""] { background-color: #f1f5f9; min-height: 100px; display: block; }
        </style>
      </head>
      <body>
        ${content || '<div class="h-screen flex items-center justify-center text-slate-300 font-bold uppercase tracking-widest bg-slate-50">Empty Canvas</div>'}
        ${annotateScript}
      </body>
      </html>
    `;
  };

  const internalHtml = useMemo(() => generateWebsiteHtml(true), [state.blocks, state.accentColor, state.fontFamily, state.globalCss, state.borderRadius, state.metaTitle, state.projectName, previewKey]);

  const processBlockImages = async (targetBlocks?: Block[]) => {
    const blocksToProcess = targetBlocks || state.blocks;
    for (const block of blocksToProcess) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgTags = Array.from(doc.querySelectorAll('img[data-ai-prompt]'));
      if (imgTags.length === 0) continue;

      setSyncingBlocks(prev => new Set(prev).add(block.id));
      for (const img of imgTags) {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) {
          try {
            const base64Image = await geminiService.generateAiImage(prompt);
            img.setAttribute('src', base64Image);
            img.removeAttribute('data-ai-prompt');
            const updatedHtml = doc.body.innerHTML;
            setState(prev => ({
              ...prev,
              blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: updatedHtml } : b)
            }));
            setPreviewKey(k => k + 1);
          } catch (err: any) {
            addLog('error', `Lỗi AI Image: ${block.name}`);
          }
        }
      }
      setSyncingBlocks(prev => {
        const next = new Set(prev);
        next.delete(block.id);
        return next;
      });
    }
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    addLog('info', `Gemini đang khởi tạo cấu trúc...`);
    try {
      const isUpgrade = inputSource.includes('<') && inputSource.includes('>');
      const result = await geminiService.parseToBlocks(inputSource, state.designTone, isUpgrade ? inputSource : undefined);
      setState(prev => ({
        ...prev,
        blocks: result.blocks,
        globalCss: result.globalCss,
        selectedBlockId: result.blocks[0]?.id || null
      }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);
      addLog('success', isUpgrade ? 'Nâng cấp HTML hoàn tất.' : 'Dựng layout thành công.');
      setTimeout(() => processBlockImages(result.blocks), 500);
    } catch (e: any) {
      addLog('error', 'Xây dựng thất bại', e.message);
    } finally {
      setIsProcessing(false);
    }
  };

  const handleAddModule = async () => {
    if (!newModuleQuery.trim()) return;
    setIsAddingModule(true);
    addLog('info', `Đang viết thêm module: ${newModuleQuery}`);
    try {
      const context = state.blocks.map(b => b.html).join(' ');
      const newBlock = await geminiService.generateSingleBlock(newModuleQuery, state.designTone, context);
      setState(prev => ({
        ...prev,
        blocks: [...prev.blocks, newBlock],
        selectedBlockId: newBlock.id
      }));
      setNewModuleQuery('');
      addLog('success', `Đã thêm module: ${newBlock.name}`);
      setTimeout(() => processBlockImages([newBlock]), 200);
    } catch (e: any) {
      addLog('error', 'Thêm module thất bại', e.message);
    } finally {
