        >
          Modules
        </button>
        <button 
          onClick={() => setSidebarTab('history')} 
          className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest transition-all ${sidebarTab === 'history' ? 'text-indigo-400 border-b-2 border-indigo-500 bg-indigo-500/5' : 'text-slate-500 hover:text-slate-300'}`}
        >
          History
        </button>
      </div>

      <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
        {sidebarTab === 'blocks' ? (
          <div className="space-y-4">
            <div className="space-y-2">
              {blocks.map((block, idx) => (
                <div 
                  key={block.id} 
                  onClick={() => { setSelectedBlockId(block.id); setViewMode('edit'); }}
                  className={`group p-3 rounded-xl cursor-pointer transition-all border relative ${selectedBlockId === block.id ? 'bg-indigo-600/10 border-indigo-500/30 text-white' : 'bg-transparent border-transparent hover:bg-white/5 text-slate-500'}`}
                >
                  <div className="flex items-center justify-between">
                    <span className="text-[10px] font-black uppercase truncate tracking-tight">{block.name}</span>
                    {syncingBlocks.has(block.id) && <Loader2 className="w-2.5 h-2.5 animate-spin text-indigo-400" />}
                    <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button onClick={(e) => { e.stopPropagation(); moveBlock(idx, 'up'); }} disabled={idx === 0} className="p-0.5 hover:text-white disabled:opacity-20"><ChevronUp className="w-3 h-3" /></button>
                      <button onClick={(e) => { e.stopPropagation(); moveBlock(idx, 'down'); }} disabled={idx === blocks.length - 1} className="p-0.5 hover:text-white disabled:opacity-20"><ChevronDown className="w-3 h-3" /></button>
                      <button onClick={(e) => { e.stopPropagation(); if (confirm('Xóa module này?')) deleteBlock(block.id); }} className="p-0.5 hover:text-red-400"><Trash2 className="w-3 h-3" /></button>
                    </div>
                  </div>
                </div>
              ))}
            </div>

            <div className="pt-4 border-t border-white/5 space-y-3">
               <div className="text-[9px] font-black text-slate-500 uppercase flex items-center gap-2"><Sparkles className="w-3 h-3 text-indigo-400" /> AI Generator</div>
               <textarea
                 value={newModuleQuery}
                 onChange={(e) => setNewModuleQuery(e.target.value)}
                 placeholder="Yêu cầu viết thêm module..."
                 className="w-full bg-slate-900 border border-white/10 rounded-xl p-3 text-[10px] font-medium text-white outline-none focus:border-indigo-500/40 resize-none h-20 placeholder:text-slate-600"
               />
               <button 
                 onClick={handleAddModule}
                 disabled={isAddingModule || !newModuleQuery.trim()}
                 className="w-full py-2 bg-indigo-600/10 hover:bg-indigo-600/20 text-indigo-400 border border-indigo-500/20 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all flex items-center justify-center gap-2 disabled:opacity-50"
               >
                 {isAddingModule ? <Loader2 className="w-3 h-3 animate-spin" /> : <Plus className="w-3 h-3" />}
                 Add AI Module
               </button>
            </div>
          </div>
        ) : (
          <div className="space-y-3">
            {snapshots.map((snap) => (
              <div 
                key={snap.id} 
                onClick={() => restoreSnapshot(snap)}
                className="p-3 rounded-xl bg-slate-900/50 border border-white/5 hover:border-indigo-500/30 cursor-pointer transition-all group"
              >
                <div className="text-[10px] font-black text-white uppercase truncate mb-1">{snap.name}</div>
                <div className="text-[8px] text-slate-500 font-mono">{snap.timestamp}</div>
                <div className="mt-2 opacity-0 group-hover:opacity-100 transition-opacity flex justify-between items-center">
                  <button className="text-[8px] font-black text-indigo-400 flex items-center gap-1"><RotateCcw className="w-2.5 h-2.5" /> RESTORE</button>
                  <button onClick={(e) => { e.stopPropagation(); if(confirm('Xóa bản lưu này?')) deleteSnapshot(snap.id); }} className="text-slate-600 hover:text-red-400"><Trash2 className="w-2.5 h-2.5" /></button>
                </div>
              </div>
            ))}
            {snapshots.length === 0 && <div className="text-[9px] text-slate-600 italic text-center py-8">Chưa có bản lưu snapshot nào.</div>}
          </div>
        )}
      </div>

      <div className="p-4 border-t border-white/5 bg-slate-950/50">
         <div className="text-[9px] font-black text-slate-500 uppercase mb-3">Tone & Style</div>
         <select 
           value={designTone} 
           onChange={(e) => setDesignTone(e.target.value as DesignTone)}
           className="w-full bg-slate-900 border border-white/10 rounded-lg p-2 text-[10px] font-black text-indigo-400 outline-none uppercase"
         >
           <option value="professional">Professional</option>
           <option value="minimalist">Minimalist</option>
           <option value="cyberpunk">Cyberpunk</option>
           <option value="playful">Playful</option>
           <option value="brutalist">Brutalist</option>
         </select>
      </div>
    </aside>
  );
};

