  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [sidebarTab, setSidebarTab] = useState<'blocks' | 'history'>('blocks');

  const addLog = (type: LogEntry['type'], message: string, details?: string) => {
    const newLog: LogEntry = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleTimeString(),
      type,
      message,
      details
    };
    setState(prev => ({
      ...prev,
      logs: [newLog, ...prev.logs].slice(0, 100)
    }));
  };

  useEffect(() => {
    const handleIframeMessage = (event: MessageEvent) => {
      if (event.data?.type === 'UPDATE_BLOCK_HTML') {
        const { blockId, newHtml } = event.data;
        setState(prev => ({
          ...prev,
          blocks: prev.blocks.map(b => b.id === blockId ? { ...b, html: newHtml } : b)
        }));
        addLog('success', 'Đã cập nhật module từ Preview Annotate.');
      }
    };
    window.addEventListener('message', handleIframeMessage);
    return () => window.removeEventListener('message', handleIframeMessage);
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setState({ ...parsed, logs: [] });
      } catch (e) {
        addLog('error', 'Lỗi khôi phục dữ liệu.');
      }
    }
    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        // @ts-ignore
        await window.aistudio.openSelectKey();
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      const { logs, ...rest } = state;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
      setIsSaved(true);
    }, 2000);
    setIsSaved(false);
    return () => clearTimeout(timer);
  }, [state.blocks, state.globalCss, state.accentColor, state.fontFamily, state.projectName, state.designTone, state.snapshots]);

  const generateWebsiteHtml = (isInternal: boolean = false) => {
    const content = state.blocks.map(b => 
      isInternal 
        ? `<div data-block-id="${b.id}" class="omni-block-wrapper relative group/block">${b.html}</div>`
        : b.html
    ).join('\n');

    const annotateScript = isInternal ? `
      <script>
        (function() {
          const style = document.createElement('style');
          style.innerHTML = \`
            .omni-img-overlay {
              position: absolute; top: 10px; right: 10px; background: #6366f1;
              color: white; padding: 6px 14px; border-radius: 99px; font-family: 'Inter', sans-serif;
              font-size: 11px; font-weight: 800; cursor: pointer; display: none; z-index: 99999;
              box-shadow: 0 10px 25px -5px rgba(99, 102, 241, 0.5); border: 2px solid rgba(255,255,255,0.4);
              text-transform: uppercase; letter-spacing: 0.5px; backdrop-filter: blur(4px);
            }
            .omni-img-target { outline: 4px solid #6366f1 !important; outline-offset: -4px; transition: all 0.2s ease; }
          \`;
          document.head.appendChild(style);
          const overlay = document.createElement('div');
          overlay.className = 'omni-img-overlay';
          overlay.innerHTML = '<span style="display:flex;align-items:center;gap:6px;"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M12 5v14M5 12h14"/></svg> CHỈNH SỬA ẢNH</span>';
          document.body.appendChild(overlay);
          let currentTargetImg = null;
          document.addEventListener('mouseover', (e) => {
            const img = e.target.closest('img');
            if (img) {
              currentTargetImg = img;
              img.classList.add('omni-img-target');
              const rect = img.getBoundingClientRect();
              overlay.style.display = 'block';
              overlay.style.top = (window.scrollY + rect.top + 10) + 'px';
              overlay.style.left = (window.scrollX + rect.right - 130) + 'px';
            } else if (!e.target.closest('.omni-img-overlay')) {
              if (currentTargetImg) { currentTargetImg.classList.remove('omni-img-target'); currentTargetImg = null; }
              overlay.style.display = 'none';
            }
          });
          overlay.addEventListener('click', () => {
            const input = document.createElement('input');
            input.type = 'file'; input.accept = 'image/*';
            input.onchange = (e) => {
              const file = e.target.files[0];
              if(!file) return;
              const reader = new FileReader();
              reader.onload = (re) => {
                if (currentTargetImg) {
                  currentTargetImg.src = re.target.result;
                  const wrapper = currentTargetImg.closest('[data-block-id]');
                  if (wrapper) { window.parent.postMessage({ type: 'UPDATE_BLOCK_HTML', blockId: wrapper.getAttribute('data-block-id'), newHtml: wrapper.innerHTML }, '*'); }
                }
              };
              reader.readAsDataURL(file);
            };
            input.click();
          });
        })();
      </script>
    ` : '';

    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>${state.metaTitle || state.projectName}</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;500;600;700&display=swap" rel="stylesheet">
        <style>
          body { font-family: '${state.fontFamily}', sans-serif; scroll-behavior: smooth; margin: 0; padding: 0; background-color: white; color: #1e293b; }
          :root { --accent: ${state.accentColor}; --radius: ${state.borderRadius}; }
          ${state.globalCss}
          img:not([src]), img[src=""] { background-color: #f1f5f9; min-height: 150px; display: block; background-image: url('data:image/svg+xml;charset=UTF-8,<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="%23cbd5e1" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2" ry="2"/><circle cx="8.5" cy="8.5" r="1.5"/><polyline points="21 15 16 10 5 21"/></svg>'); background-repeat: no-repeat; background-position: center; }
        </style>
      </head>
      <body>${content || '<div class="h-screen flex items-center justify-center text-slate-300 font-bold uppercase tracking-widest bg-slate-50">Empty Canvas</div>'}${annotateScript}</body>
      </html>
    `;
  };

  const internalHtml = useMemo(() => generateWebsiteHtml(true), [state.blocks, state.accentColor, state.fontFamily, state.globalCss, state.borderRadius, state.metaTitle, state.projectName, previewKey]);

  const processBlockImages = async (targetBlocks?: Block[]) => {
    const blocksToProcess = targetBlocks || state.blocks;
    for (const block of blocksToProcess) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgTags = Array.from(doc.querySelectorAll('img[data-ai-prompt]'));
      if (imgTags.length === 0) continue;
      setSyncingBlocks(prev => new Set(prev).add(block.id));
      let updatedHtml = block.html;
      for (const img of imgTags) {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) {
          try {
            const base64Image = await geminiService.generateAiImage(prompt);
            const imgInDoc = doc.querySelector(`img[data-ai-prompt="${prompt}"]`);
            if(imgInDoc) { imgInDoc.setAttribute('src', base64Image); imgInDoc.removeAttribute('data-ai-prompt'); }
            updatedHtml = doc.body.innerHTML;
            setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: updatedHtml } : b) }));
            setPreviewKey(k => k + 1);
          } catch (err: any) { addLog('error', `Lỗi AI Image: ${block.name}`); }
        }
      }
      setSyncingBlocks(prev => { const next = new Set(prev); next.delete(block.id); return next; });
    }
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    addLog('info', `Gemini đang khởi tạo cấu trúc...`);
    try {
      const isUpgrade = inputSource.includes('<') && inputSource.includes('>');
      const result = await geminiService.parseToBlocks(inputSource, state.designTone, isUpgrade ? inputSource : undefined);
      setState(prev => ({ ...prev, blocks: result.blocks, globalCss: result.globalCss, selectedBlockId: result.blocks[0]?.id || null }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);
      addLog('success', isUpgrade ? 'Nâng cấp HTML hoàn tất.' : 'Dựng layout thành công.');
      setTimeout(() => processBlockImages(result.blocks), 800);
    } catch (e: any) { addLog('error', 'Xây dựng thất bại', e.message); } finally { setIsProcessing(false); }
  };

  const handleAddModule = async () => {
    if (!newModuleQuery.trim()) return;
    setIsAddingModule(true);
    addLog('info', `Đang viết thêm module: ${newModuleQuery}`);
    try {
      const context = state.blocks.map(b => b.html).join(' ');
      const newBlock = await geminiService.generateSingleBlock(newModuleQuery, state.designTone, context);
      setState(prev => ({ ...prev, blocks: [...prev.blocks, newBlock], selectedBlockId: newBlock.id }));
      setNewModuleQuery('');
      addLog('success', `Đã thêm module: ${newBlock.name}`);
      setViewMode('preview');
      setPreviewKey(k => k + 1);
      setTimeout(() => processBlockImages([newBlock]), 800);
    } catch (e: any) { addLog('error', 'Thêm module thất bại', e.message); } finally { setIsAddingModule(false); }
  };

  const createSnapshot = () => {
    const { logs, snapshots, ...rest } = state;
    const newSnapshot: Snapshot = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleString(),
      name: `${state.projectName} (Backup ${state.snapshots.length + 1})`,
      state: JSON.parse(JSON.stringify(rest))
    };
    setState(prev => ({ ...prev, snapshots: [newSnapshot, ...prev.snapshots].slice(0, 15) }));
    addLog('success', 'Đã lưu Snapshot thành công.');
  };

  const restoreSnapshot = (snapshot: Snapshot) => {
    if (confirm(`Khôi phục phiên bản "${snapshot.name}"?`)) {
      setState(prev => ({ ...prev, ...snapshot.state, logs: [{ id: 'restore-' + Date.now(), timestamp: new Date().toLocaleTimeString(), type: 'info', message: `Đã khôi phục từ: ${snapshot.name}` }] }));
      setSidebarTab('blocks');
      addLog('success', 'Khôi phục hoàn tất.');
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <Header 
        projectName={state.projectName}
        isEditingTitle={isEditingTitle}
        setIsEditingTitle={setIsEditingTitle}
        setProjectName={(name) => setState(prev => ({ ...prev, projectName: name }))}
        isSaved={isSaved}
        createSnapshot={createSnapshot}
        showTerminal={showTerminal}
        setShowTerminal={setShowTerminal}
        viewMode={viewMode}
        setViewMode={setViewMode}
        handleExport={() => {
          const prodHtml = generateWebsiteHtml(false);
          const blob = new Blob([prodHtml], { type: 'text/html' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url; a.download = `${state.projectName.toLowerCase().replace(/\s+/g, '-')}.html`; a.click();
          addLog('success', 'Đã xuất file HTML.');
        }}
      />

      <main className="flex-1 flex overflow-hidden">
        <LeftSidebar 
          sidebarTab={sidebarTab}
          setSidebarTab={setSidebarTab}
          blocks={state.blocks}
          selectedBlockId={state.selectedBlockId}
          setSelectedBlockId={(id) => setState(prev => ({ ...prev, selectedBlockId: id }))}
          setViewMode={setViewMode}
          moveBlock={(idx, dir) => {
            const newBlocks = [...state.blocks];
            const target = dir === 'up' ? idx - 1 : idx + 1;
            if (target < 0 || target >= newBlocks.length) return;
            [newBlocks[idx], newBlocks[target]] = [newBlocks[target], newBlocks[idx]];
            setState(prev => ({ ...prev, blocks: newBlocks }));
          }}
          deleteBlock={(id) => setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== id), selectedBlockId: prev.blocks.find(b => b.id !== id)?.id || null }))}
          syncingBlocks={syncingBlocks}
          newModuleQuery={newModuleQuery}
          setNewModuleQuery={setNewModuleQuery}
          handleAddModule={handleAddModule}
          isAddingModule={isAddingModule}
          snapshots={state.snapshots}
          restoreSnapshot={restoreSnapshot}
          deleteSnapshot={(id) => setState(prev => ({ ...prev, snapshots: prev.snapshots.filter(s => s.id !== id) }))}
          designTone={state.designTone}
          setDesignTone={(tone) => setState(prev => ({ ...prev, designTone: tone }))}
        />

        <section className="flex-1 flex flex-col overflow-hidden bg-[#020617]">
          {viewMode === 'edit' ? (
            <div className="flex-1 flex flex-col p-6 overflow-hidden">
               {state.blocks.length > 0 ? (
                  <div className="flex-1 bg-[#0b0f1a] rounded-3xl border border-white/5 shadow-2xl flex flex-col overflow-hidden">
                    <div className="p-3 bg-[#131929] border-b border-white/5 px-6 flex justify-between items-center">
                       <span className="text-[10px] font-black text-white uppercase tracking-widest">{state.blocks.find(b => b.id === state.selectedBlockId)?.name}</span>
                       <button onClick={() => setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== state.selectedBlockId), selectedBlockId: prev.blocks.find(b => b.id !== state.selectedBlockId)?.id || null }))} className="text-slate-600 hover:text-red-400"><Trash2 className="w-3.5 h-3.5" /></button>
                    </div>
                    <textarea
                      value={state.blocks.find(b => b.id === state.selectedBlockId)?.html || ''}
                      onChange={(e) => setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === state.selectedBlockId ? { ...b, html: e.target.value } : b) }))}
                      className="flex-1 p-8 bg-transparent text-slate-300 code-font text-sm outline-none resize-none custom-scrollbar"
                    />
                  </div>
               ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-center max-w-xl mx-auto">
                    <div className="w-16 h-16 bg-indigo-600/10 rounded-full flex items-center justify-center mb-8"><Wand2 className="w-8 h-8 text-indigo-500 animate-pulse" /></div>
                    <h2 className="text-3xl font-black text-white mb-2 uppercase tracking-tighter italic">HTML Forge 2025</h2>
                    <p className="text-slate-500 text-xs mb-8 uppercase tracking-widest font-bold">Nâng cấp HTML module chuyên nghiệp</p>
                    <textarea 
                      value={inputSource} onChange={(e) => setInputSource(e.target.value)}
                      placeholder="Mô tả ý tưởng hoặc dán code HTML cũ..."
                      className="w-full h-40 bg-slate-900 border border-white/10 rounded-2xl p-6 text-sm outline-none focus:border-indigo-500 mb-6 text-white shadow-inner resize-none placeholder:text-slate-700"
                    />
                    <button onClick={handleBuild} disabled={isProcessing} className="w-full py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest hover:scale-[1.02] transition-all shadow-xl shadow-indigo-600/30 active:scale-95 disabled:opacity-50">
                      {isProcessing ? 'ENGINE ĐANG THI CÔNG...' : inputSource.includes('<') ? 'UPGRADE HTML CODE' : 'BẮT ĐẦU THIẾT KẾ'}
                    </button>
                  </div>
               )}
            </div>
          ) : (
            <div className="flex-1 flex flex-col overflow-hidden relative">
              <div className="h-12 border-b border-white/5 bg-[#0b0f1a] flex items-center justify-center gap-6 shrink-0">
                <button onClick={() => setPreviewDevice('mobile')} className={`p-2 rounded-lg ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Smartphone className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('tablet')} className={`p-2 rounded-lg ${previewDevice === 'tablet' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><TabletIcon className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('desktop')} className={`p-2 rounded-lg ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Monitor className="w-4 h-4" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-12 bg-[#020617] flex justify-center items-start custom-scrollbar relative">
                <div key={previewKey} className={`flex-shrink-0 bg-white shadow-2xl transition-all duration-500 rounded-sm overflow-hidden border border-white/10 ${previewDevice === 'desktop' ? 'w-[1200px]' : previewDevice === 'tablet' ? 'w-[768px]' : 'w-[375px]'}`}>
                  <iframe srcDoc={internalHtml} className="w-full h-[2000px] border-none" sandbox="allow-scripts allow-same-origin" />
                </div>
              </div>
              {showTerminal && <Terminal logs={state.logs} onClose={() => setShowTerminal(false)} />}
            </div>
          )}
        </section>

        <RightSidebar 
          accentColor={state.accentColor}
          setAccentColor={(val) => setState(prev => ({ ...prev, accentColor: val }))}
          fontFamily={state.fontFamily}
          setFontFamily={(val) => setState(prev => ({ ...prev, fontFamily: val }))}
          handleReset={() => { if(confirm('Reset toàn bộ dữ liệu?')) { setState(getInitialState()); setInputSource(''); addLog('info', 'Đã reset workspace.'); } }}
        />
      </main>

      {(isProcessing || isAddingModule) && (
        <div className="absolute inset-0 bg-slate-950/98 backdrop-blur-3xl z-[100] flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-700">
          <div className="relative mb-12">
            <div className="w-24 h-24 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <Zap className="absolute inset-0 m-auto w-8 h-8 text-indigo-500 animate-pulse" />
          </div>
          <h2 className="text-4xl font-black text-white mb-4 tracking-tighter uppercase italic">{isAddingModule ? 'Writing Module...' : 'Engine Crafting...'}</h2>
          <div className="text-slate-500 text-[10px] font-black uppercase tracking-[0.5em] animate-pulse">2025 Protocol Active</div>
        </div>
      )}
    </div>
  );
}

export interface Block {
  id: string;
  type: string;
  name: string;
  html: string;
  css?: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  type: 'info' | 'success' | 'error' | 'warning';
  message: string;
  details?: string;
}

export type DesignTone = 'professional' | 'minimalist' | 'cyberpunk' | 'playful' | 'brutalist';

export interface Snapshot {
  id: string;
  timestamp: string;
  name: string;
  state: Omit<OmniState, 'logs' | 'snapshots'>;
}

export interface OmniState {
  projectName: string;
  metaTitle: string;
  blocks: Block[];
  selectedBlockId: string | null;
  globalCss: string;
  accentColor: string;
  fontFamily: string;
  designTone: DesignTone;
  borderRadius: string;
  spacingScale: number; // New: 0.5 to 2.0
  shadowIntensity: number; // New: 0 to 1
  logs: LogEntry[];
  snapshots: Snapshot[];
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
}

export interface GeneratedImage {
  url: string;
  prompt: string;
}

import { GoogleGenAI, Type } from "@google/genai";
import { Block, DesignTone } from "../types";

const TEXT_MODEL = 'gemini-3-pro-preview';
const IMAGE_MODEL = 'gemini-3-pro-image-preview';

export class GeminiService {
  private getAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private async handlePotentialKeyError(error: any): Promise<never> {
    if (error?.message?.includes("Requested entity was not found.") || error?.message?.includes("API_KEY_INVALID")) {
      // @ts-ignore
      if (window.aistudio) await window.aistudio.openSelectKey();
    }
    throw error;
  }

  async parseToBlocks(prompt: string, tone: DesignTone = 'professional', existingHtml?: string): Promise<{ blocks: Block[], globalCss: string }> {
    const ai = this.getAI();
    const systemInstruction = `
      You are the "Omni-Builder Architect" specializing in ${tone.toUpperCase()} design.
      Rules:
      1. Break the website into logical blocks using Tailwind CSS.
      2. For EVERY <img>, use 'data-ai-prompt' with a descriptive English prompt.
      3. Return ONLY a JSON object with 'blocks' and 'globalCss'.
    `;

    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Input Request: ${prompt}\n\nExisting HTML: ${existingHtml || 'None'}`,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              blocks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    type: { type: Type.STRING },
                    name: { type: Type.STRING },
                    html: { type: Type.STRING }
                  },
                  required: ["id", "type", "name", "html"]
                }
              },
              globalCss: { type: Type.STRING }
            },
            required: ["blocks", "globalCss"]
          }
        }
      });
      return JSON.parse(response.text || '{"blocks": [], "globalCss": ""}');
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }

  async refineBlock(block: Block, instruction: string, tone: DesignTone): Promise<Block> {
    const ai = this.getAI();
    const systemInstruction = `
      You are a UI Expert. Modify the provided HTML block based on the instruction.
      Instruction: ${instruction}
      Current Style: ${tone}

      Rules:
      1. Keep the existing structure but update styles/content as requested.
      2. Always use Tailwind CSS.
      3. Return a single Block object in JSON.
    `;

    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Original HTML: ${block.html}\n\nInstruction: ${instruction}`,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              type: { type: Type.STRING },
              name: { type: Type.STRING },
              html: { type: Type.STRING }
            },
            required: ["id", "type", "name", "html"]
          }
        }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }

  async generateSingleBlock(prompt: string, tone: DesignTone, context: string): Promise<Block> {
    const ai = this.getAI();
    const systemInstruction = `
      You are an expert UI developer. Generate ONE single HTML module using Tailwind CSS.
      Style: ${tone.toUpperCase()}.
      Rules:
      1. Every <img> MUST have a 'data-ai-prompt'.
      2. Return a single JSON object.
    `;

    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `New section request: ${prompt}`,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              type: { type: Type.STRING },
              name: { type: Type.STRING },
              html: { type: Type.STRING }
            },
            required: ["id", "type", "name", "html"]
          }
        }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) {
      return this.handlePotentialKeyError(e);
    }
  }

  async generateAiImage(prompt: string): Promise<string> {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: IMAGE_MODEL,
        contents: { parts: [{ text: `${prompt}, realistic, 4k, professional` }] },
        config: { imageConfig: { aspectRatio: "16:9", imageSize: "1K" } }
      });
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData) return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
      throw new Error("No image generated");
    } catch (e) { return this.handlePotentialKeyError(e); }
  }
}

export const geminiService = new GeminiService();

