import React, { useState, useMemo, useEffect } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, LogEntry, DesignTone, Snapshot } from './types';
import { Smartphone, Tablet as TabletIcon, Monitor, Trash2, Wand2, Zap, Sparkles } from 'lucide-react';
import { Header } from './components/Header';
import { LeftSidebar } from './components/LeftSidebar';
import { RightSidebar } from './components/RightSidebar';
import { Terminal } from './components/Terminal';

const STORAGE_KEY = 'omni_gen_v3_state_pro_final';

const getInitialState = (): OmniState => ({
  projectName: "Untitled Project",
  metaTitle: "Omni Gen Website",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#6366f1",
  fontFamily: "Inter",
  designTone: 'professional',
  borderRadius: '0.75rem',
  spacingScale: 1.0,
  shadowIntensity: 0.3,
  logs: [],
  snapshots: []
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [isAddingModule, setIsAddingModule] = useState(false);
  const [isRefining, setIsRefining] = useState(false);
  const [newModuleQuery, setNewModuleQuery] = useState('');
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [sidebarTab, setSidebarTab] = useState<'blocks' | 'history'>('blocks');

  const addLog = (type: LogEntry['type'], message: string, details?: string) => {
    const newLog: LogEntry = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleTimeString(),
      type, message, details
    };
    setState(prev => ({ ...prev, logs: [newLog, ...prev.logs].slice(0, 100) }));
  };

  useEffect(() => {
    const handleIframeMessage = (event: MessageEvent) => {
      if (event.data?.type === 'UPDATE_BLOCK_HTML') {
        const { blockId, newHtml } = event.data;
        setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === blockId ? { ...b, html: newHtml } : b) }));
        addLog('success', 'Đã cập nhật module từ Preview.');
      }
    };
    window.addEventListener('message', handleIframeMessage);
    return () => window.removeEventListener('message', handleIframeMessage);
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try {
        const parsed = JSON.parse(saved);
        setState({ ...parsed, logs: [] });
      } catch (e) { addLog('error', 'Lỗi khôi phục dữ liệu.'); }
    }
    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        // @ts-ignore
        await window.aistudio.openSelectKey();
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      const { logs, ...rest } = state;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
      setIsSaved(true);
    }, 2000);
    setIsSaved(false);
    return () => clearTimeout(timer);
  }, [state.blocks, state.globalCss, state.accentColor, state.fontFamily, state.projectName, state.designTone, state.snapshots, state.spacingScale, state.shadowIntensity]);

  const generateWebsiteHtml = (isInternal: boolean = false) => {
    const content = state.blocks.map(b => 
      isInternal ? `<div data-block-id="${b.id}" class="omni-block-wrapper relative group/block">${b.html}</div>` : b.html
    ).join('\n');

    const designTokenCss = `
      :root {
        --accent: ${state.accentColor};
        --radius: ${state.borderRadius};
        --spacing-scale: ${state.spacingScale};
        --shadow-opacity: ${state.shadowIntensity};
      }
      .omni-block-wrapper { transition: all 0.3s ease; }
      [class*="p-"], [class*="m-"], [class*="gap-"] { 
        padding-top: calc(inherit * var(--spacing-scale)); 
      }
      /* Cải thiện bóng đổ dựa trên intensity */
      .shadow-md { shadow: 0 4px 6px -1px rgba(0,0,0, var(--shadow-opacity)); }
      .shadow-xl { shadow: 0 20px 25px -5px rgba(0,0,0, var(--shadow-opacity)); }
    `;

    const annotateScript = isInternal ? `
      <script>
        (function() {
          const style = document.createElement('style');
          style.innerHTML = \`
            .omni-img-overlay {
              position: absolute; top: 10px; right: 10px; background: #6366f1;
              color: white; padding: 6px 14px; border-radius: 99px; font-family: 'Inter', sans-serif;
              font-size: 11px; font-weight: 800; cursor: pointer; display: none; z-index: 99999;
              box-shadow: 0 10px 25px -5px rgba(99, 102, 241, 0.5); border: 2px solid rgba(255,255,255,0.4);
              text-transform: uppercase; letter-spacing: 0.5px;
            }
            .omni-img-target { outline: 4px solid #6366f1 !important; outline-offset: -4px; transition: all 0.2s ease; }
          \`;
          document.head.appendChild(style);
          const overlay = document.createElement('div');
          overlay.className = 'omni-img-overlay';
          overlay.innerHTML = 'EDIT IMAGE';
          document.body.appendChild(overlay);
          let currentImg = null;
          document.addEventListener('mouseover', (e) => {
            const img = e.target.closest('img');
            if (img) {
              currentImg = img; img.classList.add('omni-img-target');
              const rect = img.getBoundingClientRect();
              overlay.style.display = 'block';
              overlay.style.top = (window.scrollY + rect.top + 10) + 'px';
              overlay.style.left = (window.scrollX + rect.right - 100) + 'px';
            } else if (!e.target.closest('.omni-img-overlay')) {
              if (currentImg) { currentImg.classList.remove('omni-img-target'); currentImg = null; }
              overlay.style.display = 'none';
            }
          });
          overlay.addEventListener('click', () => {
            const input = document.createElement('input');
            input.type = 'file'; input.accept = 'image/*';
            input.onchange = (e) => {
              const file = e.target.files[0];
              if(!file) return;
              const reader = new FileReader();
              reader.onload = (re) => {
                if (currentImg) {
                  currentImg.src = re.target.result;
                  const wrapper = currentImg.closest('[data-block-id]');
                  if (wrapper) window.parent.postMessage({ type: 'UPDATE_BLOCK_HTML', blockId: wrapper.getAttribute('data-block-id'), newHtml: wrapper.innerHTML }, '*');
                }
              };
              reader.readAsDataURL(file);
            };
            input.click();
          });
        })();
      </script>
    ` : '';

    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title>${state.metaTitle || state.projectName}</title>
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          body { font-family: '${state.fontFamily}', sans-serif; scroll-behavior: smooth; margin: 0; padding: 0; }
          ${designTokenCss}
          ${state.globalCss}
        </style>
      </head>
      <body>${content || '<div class="h-screen flex items-center justify-center text-slate-300 font-bold uppercase tracking-widest bg-slate-50">Empty Canvas</div>'}${annotateScript}</body>
      </html>
    `;
  };

  const internalHtml = useMemo(() => generateWebsiteHtml(true), [state.blocks, state.accentColor, state.fontFamily, state.globalCss, state.spacingScale, state.shadowIntensity, previewKey]);

  const processBlockImages = async (targetBlocks?: Block[]) => {
    const blocksToProcess = targetBlocks || state.blocks;
    for (const block of blocksToProcess) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgTags = Array.from(doc.querySelectorAll('img[data-ai-prompt]'));
      if (imgTags.length === 0) continue;
      setSyncingBlocks(prev => new Set(prev).add(block.id));
      for (const img of imgTags) {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) {
          try {
            const base64Image = await geminiService.generateAiImage(prompt);
            img.setAttribute('src', base64Image); img.removeAttribute('data-ai-prompt');
            const updatedHtml = doc.body.innerHTML;
            setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: updatedHtml } : b) }));
            setPreviewKey(k => k + 1);
          } catch (err: any) { addLog('error', `Lỗi AI Image: ${block.name}`); }
        }
      }
      setSyncingBlocks(prev => { const next = new Set(prev); next.delete(block.id); return next; });
    }
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    addLog('info', `Gemini đang khởi tạo...`);
    try {
      const result = await geminiService.parseToBlocks(inputSource, state.designTone, inputSource.includes('<') ? inputSource : undefined);
      setState(prev => ({ ...prev, blocks: result.blocks, globalCss: result.globalCss, selectedBlockId: result.blocks[0]?.id || null }));
      setViewMode('preview'); setPreviewKey(k => k + 1);
      addLog('success', 'Layout hoàn tất.');
      setTimeout(() => processBlockImages(result.blocks), 800);
    } catch (e: any) { addLog('error', 'Xây dựng thất bại', e.message); } finally { setIsProcessing(false); }
  };

  const handleRefineBlock = async (block: Block) => {
    const instruction = prompt(`Nhập yêu cầu tinh chỉnh cho module "${block.name}":`, "Làm cho phần này trông hiện đại hơn với gradient");
    if (!instruction) return;
    setIsRefining(true);
    addLog('info', `Đang tinh chỉnh: ${block.name}`);
    try {
      const updatedBlock = await geminiService.refineBlock(block, instruction, state.designTone);
      setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === block.id ? updatedBlock : b) }));
      addLog('success', `Đã tinh chỉnh module: ${block.name}`);
      setPreviewKey(k => k + 1);
    } catch (e: any) { addLog('error', 'Tinh chỉnh thất bại', e.message); } finally { setIsRefining(true); setIsRefining(false); }
  };

  const createSnapshot = () => {
    const { logs, snapshots, ...rest } = state;
    const newSnapshot: Snapshot = {
      id: Math.random().toString(36).substr(2, 9),
      timestamp: new Date().toLocaleString(),
      name: `${state.projectName} (v${state.snapshots.length + 1})`,
      state: JSON.parse(JSON.stringify(rest))
    };
    setState(prev => ({ ...prev, snapshots: [newSnapshot, ...prev.snapshots].slice(0, 15) }));
    addLog('success', 'Đã lưu Snapshot.');
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <Header 
        projectName={state.projectName} isEditingTitle={isEditingTitle} setIsEditingTitle={setIsEditingTitle}
        setProjectName={(name) => setState(prev => ({ ...prev, projectName: name }))}
        isSaved={isSaved} createSnapshot={createSnapshot} showTerminal={showTerminal}
        setShowTerminal={setShowTerminal} viewMode={viewMode} setViewMode={setViewMode}
        handleExport={() => {
          const blob = new Blob([generateWebsiteHtml(false)], { type: 'text/html' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a'); a.href = url; a.download = `${state.projectName}.html`; a.click();
        }}
      />

      <main className="flex-1 flex overflow-hidden">
        <aside className="w-64 bg-[#0b0f1a] border-r border-white/5 flex flex-col shrink-0">
          <div className="flex border-b border-white/5">
            <button onClick={() => setSidebarTab('blocks')} className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest ${sidebarTab === 'blocks' ? 'text-indigo-400 border-b-2 border-indigo-500' : 'text-slate-500'}`}>Modules</button>
            <button onClick={() => setSidebarTab('history')} className={`flex-1 py-3 text-[10px] font-black uppercase tracking-widest ${sidebarTab === 'history' ? 'text-indigo-400 border-b-2 border-indigo-500' : 'text-slate-500'}`}>History</button>
          </div>
          <div className="flex-1 overflow-y-auto p-4 custom-scrollbar">
            {sidebarTab === 'blocks' ? (
              <div className="space-y-4">
                <div className="space-y-2">
                  {state.blocks.map((block, idx) => (
                    <div key={block.id} className={`group p-3 rounded-xl border relative ${state.selectedBlockId === block.id ? 'bg-indigo-500/10 border-indigo-500' : 'border-transparent hover:bg-white/5'}`}>
                      <div className="flex items-center justify-between" onClick={() => setState(prev => ({ ...prev, selectedBlockId: block.id }))}>
                        <span className="text-[10px] font-black uppercase truncate">{block.name}</span>
                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100">
                          <button onClick={() => handleRefineBlock(block)} title="Refine with AI" className="p-1 hover:text-indigo-400"><Sparkles className="w-3 h-3" /></button>
                          <button onClick={() => setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== block.id) }))} className="p-1 hover:text-red-400"><Trash2 className="w-3 h-3" /></button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
                <div className="pt-4 border-t border-white/5">
                  <textarea value={newModuleQuery} onChange={(e) => setNewModuleQuery(e.target.value)} placeholder="Yêu cầu module mới..." className="w-full bg-slate-900 border border-white/10 rounded-xl p-3 text-[10px] text-white h-20 outline-none" />
                  <button onClick={async () => {
                    if (!newModuleQuery.trim()) return;
                    setIsAddingModule(true);
                    try {
                      const newBlock = await geminiService.generateSingleBlock(newModuleQuery, state.designTone, "");
                      setState(prev => ({ ...prev, blocks: [...prev.blocks, newBlock], selectedBlockId: newBlock.id }));
                      setNewModuleQuery(''); setTimeout(() => processBlockImages([newBlock]), 800);
                    } finally { setIsAddingModule(false); }
                  }} disabled={isAddingModule} className="w-full mt-2 py-2 bg-indigo-600 rounded-xl text-[9px] font-black uppercase tracking-widest">ADD MODULE</button>
                </div>
              </div>
            ) : (
              <div className="space-y-3">
                {state.snapshots.map((snap) => (
                  <div key={snap.id} onClick={() => { if(confirm(`Restore ${snap.name}?`)) setState(prev => ({ ...prev, ...snap.state })); }} className="p-3 rounded-xl bg-slate-900 border border-white/5 cursor-pointer">
                    <div className="text-[10px] font-black text-white">{snap.name}</div>
                    <div className="text-[8px] text-slate-500">{snap.timestamp}</div>
                  </div>
                ))}
              </div>
            )}
          </div>
          <div className="p-4 border-t border-white/5">
            <select value={state.designTone} onChange={(e) => setState(prev => ({ ...prev, designTone: e.target.value as DesignTone }))} className="w-full bg-slate-900 border border-white/10 rounded-lg p-2 text-[10px] text-indigo-400 outline-none">
              <option value="professional">Professional</option><option value="cyberpunk">Cyberpunk</option><option value="minimalist">Minimalist</option>
            </select>
          </div>
        </aside>

        <section className="flex-1 flex flex-col overflow-hidden">
          {viewMode === 'edit' ? (
            <div className="flex-1 flex flex-col p-6 overflow-hidden">
               {state.blocks.length > 0 ? (
                  <div className="flex-1 bg-[#0b0f1a] rounded-3xl border border-white/5 shadow-2xl flex flex-col overflow-hidden">
                    <div className="p-3 bg-[#131929] border-b border-white/5 px-6 flex justify-between items-center text-[10px] font-black">
                       <span>{state.blocks.find(b => b.id === state.selectedBlockId)?.name}</span>
                    </div>
                    <textarea value={state.blocks.find(b => b.id === state.selectedBlockId)?.html || ''} onChange={(e) => setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === state.selectedBlockId ? { ...b, html: e.target.value } : b) }))} className="flex-1 p-8 bg-transparent text-slate-300 code-font text-sm outline-none resize-none custom-scrollbar" />
                  </div>
               ) : (
                  <div className="flex-1 flex flex-col items-center justify-center text-center max-w-xl mx-auto">
                    <div className="w-16 h-16 bg-indigo-600/10 rounded-full flex items-center justify-center mb-8"><Wand2 className="w-8 h-8 text-indigo-500 animate-pulse" /></div>
                    <h2 className="text-3xl font-black text-white mb-2 uppercase italic">HTML Forge 2025</h2>
                    <p className="text-slate-500 text-xs mb-8 uppercase tracking-widest font-bold">Nâng cấp HTML module chuyên nghiệp</p>
                    <textarea value={inputSource} onChange={(e) => setInputSource(e.target.value)} placeholder="Mô tả ý tưởng hoặc dán code HTML cũ..." className="w-full h-40 bg-slate-900 border border-white/10 rounded-2xl p-6 text-sm outline-none text-white resize-none" />
                    <button onClick={handleBuild} disabled={isProcessing} className="w-full mt-6 py-4 bg-indigo-600 text-white rounded-2xl font-black uppercase tracking-widest">BUILD START</button>
                  </div>
               )}
            </div>
          ) : (
            <div className="flex-1 flex flex-col overflow-hidden relative">
              <div className="h-12 border-b border-white/5 bg-[#0b0f1a] flex items-center justify-center gap-6 shrink-0">
                <button onClick={() => setPreviewDevice('mobile')} className={`p-2 rounded-lg ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Smartphone className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('tablet')} className={`p-2 rounded-lg ${previewDevice === 'tablet' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><TabletIcon className="w-4 h-4" /></button>
                <button onClick={() => setPreviewDevice('desktop')} className={`p-2 rounded-lg ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Monitor className="w-4 h-4" /></button>
              </div>
              <div className="flex-1 overflow-y-auto p-12 bg-[#020617] flex justify-center items-start custom-scrollbar">
                <div key={previewKey} className={`flex-shrink-0 bg-white shadow-2xl transition-all rounded-sm overflow-hidden border border-white/10 ${previewDevice === 'desktop' ? 'w-[1200px]' : previewDevice === 'tablet' ? 'w-[768px]' : 'w-[375px]'}`}>
                  <iframe srcDoc={internalHtml} className="w-full h-[2000px] border-none" sandbox="allow-scripts allow-same-origin" />
                </div>
              </div>
            </div>
          )}
        </section>

        <RightSidebar 
          accentColor={state.accentColor} setAccentColor={(val) => setState(prev => ({ ...prev, accentColor: val }))}
          fontFamily={state.fontFamily} setFontFamily={(val) => setState(prev => ({ ...prev, fontFamily: val }))}
          spacingScale={state.spacingScale} setSpacingScale={(val) => setState(prev => ({ ...prev, spacingScale: val }))}
          shadowIntensity={state.shadowIntensity} setShadowIntensity={(val) => setState(prev => ({ ...prev, shadowIntensity: val }))}
          handleReset={() => { if(confirm('Reset?')) setState(getInitialState()); }}
        />
      </main>

      {(isProcessing || isAddingModule || isRefining) && (
        <div className="absolute inset-0 bg-slate-950/98 backdrop-blur-3xl z-[100] flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-700">
          <div className="relative mb-12">
            <div className="w-24 h-24 border-2 border-indigo-500 border-t-transparent rounded-full animate-spin"></div>
            <Zap className="absolute inset-0 m-auto w-8 h-8 text-indigo-500 animate-pulse" />
          </div>
          <h2 className="text-4xl font-black text-white mb-4 italic uppercase tracking-tighter">
            {isRefining ? 'AI REFINING...' : isAddingModule ? 'WRITING CODE...' : 'CRAFTING INTERFACE...'}
          </h2>
        </div>
      )}
    </div>
  );
}

import { GoogleGenAI, Type } from "@google/genai";
import { Block, DesignTone } from "../types";

const TEXT_MODEL = 'gemini-3-pro-preview';
const IMAGE_MODEL = 'gemini-3-pro-image-preview';

export class GeminiService {
  private getAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private async handlePotentialKeyError(error: any): Promise<never> {
    if (error?.message?.includes("Requested entity was not found.") || error?.message?.includes("API_KEY_INVALID")) {
      // @ts-ignore
      if (window.aistudio) await window.aistudio.openSelectKey();
    }
    throw error;
  }

  async parseToBlocks(prompt: string, tone: DesignTone = 'professional', existingHtml?: string): Promise<{ blocks: Block[], globalCss: string }> {
    const ai = this.getAI();
    const systemInstruction = `
      You are the "Omni-Builder Architect".
      Rules:
      1. Break the website into logical blocks using Tailwind CSS.
      2. For EVERY <img>, use 'data-ai-prompt' with a descriptive English prompt.
      3. Return ONLY a JSON object with 'blocks' and 'globalCss'.
    `;
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Request: ${prompt}\n\nExisting: ${existingHtml || 'None'}`,
        config: { systemInstruction, responseMimeType: "application/json" }
      });
      return JSON.parse(response.text || '{"blocks": [], "globalCss": ""}');
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async analyzeSEO(html: string): Promise<{ score: number, suggestions: string[], metaTags: { title: string, description: string } }> {
    const ai = this.getAI();
    const systemInstruction = `
      Analyze the provided HTML for SEO best practices. 
      Check for: Missing H1, meta description length, alt attributes, and content hierarchy.
      Return a JSON object with a score (0-100), a list of improvement suggestions, and recommended meta tags.
    `;
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Full Website HTML: ${html}`,
        config: { systemInstruction, responseMimeType: "application/json" }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async refineBlock(block: Block, instruction: string, tone: DesignTone): Promise<Block> {
    const ai = this.getAI();
    const systemInstruction = `You are a UI Expert. Modify the provided HTML block. Instruction: ${instruction}. Style: ${tone}. Return JSON.`;
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `HTML: ${block.html}\nInstruction: ${instruction}`,
        config: { systemInstruction, responseMimeType: "application/json" }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async generateSingleBlock(prompt: string, tone: DesignTone, context: string): Promise<Block> {
    const ai = this.getAI();
    const systemInstruction = `Generate ONE single HTML module using Tailwind. Style: ${tone}. Return JSON.`;
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `New section: ${prompt}`,
        config: { systemInstruction, responseMimeType: "application/json" }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async generateAiImage(prompt: string): Promise<string> {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: IMAGE_MODEL,
        contents: { parts: [{ text: prompt }] },
        config: { imageConfig: { aspectRatio: "16:9", imageSize: "1K" } }
      });
      return `data:image/png;base64,${response.candidates[0].content.parts.find(p => p.inlineData)?.inlineData?.data}`;
    } catch (e) { return this.handlePotentialKeyError(e); }
  }
}
export const geminiService = new GeminiService();

import React, { useState, useMemo, useEffect } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, LogEntry, DesignTone, Snapshot } from './types';
import { Smartphone, Tablet as TabletIcon, Monitor, Trash2, Wand2, Zap, Sparkles, ShieldCheck, X, CheckCircle } from 'lucide-react';
import { Header } from './components/Header';
import { LeftSidebar } from './components/LeftSidebar';
import { RightSidebar } from './components/RightSidebar';
import { Terminal } from './components/Terminal';

const STORAGE_KEY = 'omni_gen_v3_state_pro_final';

const getInitialState = (): OmniState => ({
  projectName: "Untitled Project",
  metaTitle: "Omni Gen Website",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#6366f1",
  fontFamily: "Inter",
  designTone: 'professional',
  borderRadius: '0.75rem',
  spacingScale: 1.0,
  shadowIntensity: 0.3,
  logs: [],
  snapshots: []
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [isAddingModule, setIsAddingModule] = useState(false);
  const [isRefining, setIsRefining] = useState(false);
  const [seoResult, setSeoResult] = useState<any>(null);
  const [newModuleQuery, setNewModuleQuery] = useState('');
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [sidebarTab, setSidebarTab] = useState<'blocks' | 'history'>('blocks');

  const addLog = (type: LogEntry['type'], message: string) => {
    const newLog: LogEntry = { id: Math.random().toString(36).substr(2, 9), timestamp: new Date().toLocaleTimeString(), type, message };
    setState(prev => ({ ...prev, logs: [newLog, ...prev.logs].slice(0, 100) }));
  };

  useEffect(() => {
    const handleIframeMessage = (event: MessageEvent) => {
      if (event.data?.type === 'UPDATE_BLOCK_HTML') {
        const { blockId, newHtml } = event.data;
        setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === blockId ? { ...b, html: newHtml } : b) }));
      }
    };
    window.addEventListener('message', handleIframeMessage);
    return () => window.removeEventListener('message', handleIframeMessage);
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try { setState({ ...JSON.parse(saved), logs: [] }); } catch (e) { addLog('error', 'Lỗi khôi phục dữ liệu.'); }
    }
    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        // @ts-ignore
        await window.aistudio.openSelectKey();
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      const { logs, ...rest } = state;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
      setIsSaved(true);
    }, 2000);
    setIsSaved(false);
    return () => clearTimeout(timer);
  }, [state.blocks, state.globalCss, state.accentColor, state.fontFamily, state.projectName, state.designTone, state.spacingScale, state.shadowIntensity]);

  const generateWebsiteHtml = (isInternal: boolean = false) => {
    const content = state.blocks.map(b => 
      isInternal ? `<div data-block-id="${b.id}" class="omni-block-wrapper relative group/block">${b.html}</div>` : b.html
    ).join('\n');

    const annotateScript = isInternal ? `
      <script>
        (function() {
          const style = document.createElement('style');
          style.innerHTML = \`
            .omni-img-overlay {
              position: absolute; top: 10px; right: 10px; background: #6366f1;
              color: white; padding: 6px 14px; border-radius: 99px; font-family: 'Inter', sans-serif;
              font-size: 11px; font-weight: 800; cursor: pointer; display: none; z-index: 99999;
              box-shadow: 0 10px 25px -5px rgba(99, 102, 241, 0.5); border: 2px solid rgba(255,255,255,0.4);
              text-transform: uppercase;
            }
            .omni-img-target { outline: 4px solid #6366f1 !important; outline-offset: -4px; }
            [contenteditable="true"]:focus { outline: 2px dashed #6366f1; outline-offset: 4px; border-radius: 4px; }
          \`;
          document.head.appendChild(style);

          // Xử lý chỉnh sửa văn bản trực tiếp
          document.querySelectorAll('p, h1, h2, h3, h4, span, a, li, button').forEach(el => {
            if (el.children.length === 0 || (el.children.length > 0 && el.innerText.trim().length > 0)) {
              el.setAttribute('contenteditable', 'true');
              el.addEventListener('blur', () => {
                const wrapper = el.closest('[data-block-id]');
                if (wrapper) {
                  window.parent.postMessage({
                    type: 'UPDATE_BLOCK_HTML',
                    blockId: wrapper.getAttribute('data-block-id'),
                    newHtml: wrapper.innerHTML
                  }, '*');
                }
              });
            }
          });

          // Xử lý sửa ảnh
          const overlay = document.createElement('div');
          overlay.className = 'omni-img-overlay';
          overlay.innerHTML = 'EDIT IMAGE';
          document.body.appendChild(overlay);
          let currentImg = null;
          document.addEventListener('mouseover', (e) => {
            const img = e.target.closest('img');
            if (img) {
              currentImg = img; img.classList.add('omni-img-target');
              const rect = img.getBoundingClientRect();
              overlay.style.display = 'block';
              overlay.style.top = (window.scrollY + rect.top + 10) + 'px';
              overlay.style.left = (window.scrollX + rect.right - 100) + 'px';
            } else if (!e.target.closest('.omni-img-overlay')) {
              if (currentImg) { currentImg.classList.remove('omni-img-target'); currentImg = null; }
              overlay.style.display = 'none';
            }
          });
          overlay.addEventListener('click', () => {
            const input = document.createElement('input');
            input.type = 'file'; input.accept = 'image/*';
            input.onchange = (e) => {
              const file = e.target.files[0];
              const reader = new FileReader();
              reader.onload = (re) => {
                if (currentImg) {
                  currentImg.src = re.target.result;
                  const wrapper = currentImg.closest('[data-block-id]');
                  if (wrapper) window.parent.postMessage({ type: 'UPDATE_BLOCK_HTML', blockId: wrapper.getAttribute('data-block-id'), newHtml: wrapper.innerHTML }, '*');
                }
              };
              reader.readAsDataURL(file);
            };
            input.click();
          });
        })();
      </script>
    ` : '';

    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <script src="https://cdn.tailwindcss.com"></script>
        <style>
          :root { --accent: ${state.accentColor}; --spacing-scale: ${state.spacingScale}; }
          body { font-family: '${state.fontFamily}', sans-serif; }
          ${state.globalCss}
        </style>
      </head>
      <body>${content}${annotateScript}</body>
      </html>
    `;
  };

  const handleBuild = async () => {
    setIsProcessing(true);
    addLog('info', `Gemini đang khởi tạo giao diện...`);
    try {
      const result = await geminiService.parseToBlocks(inputSource, state.designTone);
      setState(prev => ({ ...prev, blocks: result.blocks, globalCss: result.globalCss }));
      setViewMode('preview');
      setTimeout(() => processBlockImages(result.blocks), 800);
    } catch (e: any) { addLog('error', 'Xây dựng thất bại'); } finally { setIsProcessing(false); }
  };

  const processBlockImages = async (targetBlocks: Block[]) => {
    for (const block of targetBlocks) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgTags = Array.from(doc.querySelectorAll('img[data-ai-prompt]'));
      if (imgTags.length === 0) continue;
      setSyncingBlocks(prev => new Set(prev).add(block.id));
      for (const img of imgTags) {
        const promptText = img.getAttribute('data-ai-prompt');
        if (promptText) {
          try {
            const base64 = await geminiService.generateAiImage(promptText);
            img.setAttribute('src', base64);
            img.removeAttribute('data-ai-prompt');
            setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: doc.body.innerHTML } : b) }));
            setPreviewKey(k => k + 1);
          } catch (e) { addLog('error', 'Lỗi sinh ảnh AI'); }
        }
      }
      setSyncingBlocks(prev => { const n = new Set(prev); n.delete(block.id); return n; });
    }
  };

  const runSeoAudit = async () => {
    setIsProcessing(true);
    addLog('info', 'AI đang thực hiện SEO Audit...');
    try {
      const result = await geminiService.analyzeSEO(generateWebsiteHtml(false));
      setSeoResult(result);
