import { GoogleGenAI, Type } from "@google/genai";
import { Block, DesignTone } from "../types";

const TEXT_MODEL = 'gemini-3-pro-preview';
const IMAGE_MODEL = 'gemini-3-pro-image-preview';

export class GeminiService {
  private getAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private async handlePotentialKeyError(error: any): Promise<never> {
    if (error?.message?.includes("Requested entity was not found.") || error?.message?.includes("API_KEY_INVALID")) {
      // @ts-ignore
      if (window.aistudio) await window.aistudio.openSelectKey();
    }
    throw error;
  }

  async parseToBlocks(prompt: string, tone: DesignTone = 'professional', existingHtml?: string): Promise<{ blocks: Block[], globalCss: string }> {
    const ai = this.getAI();
    const systemInstruction = `
      You are the "Omni-Builder Architect". 
      Your goal is to build a high-conversion landing page.

      CRITICAL RULES:
      1. Use Tailwind CSS for everything.
      2. ICON SYSTEM: Use Lucide Icons. Represent them as <i data-lucide="icon-name"></i> tags. Choose relevant icons (e.g., 'shield', 'zap', 'trending-up').
      3. IMAGES: Every <img> must have 'data-ai-prompt' with a high-quality photography prompt.
      4. MODULARITY: Break into Hero, Features, Social Proof, CTA, and Footer.
      5. TONE: Adhere strictly to the ${tone} aesthetic.

      Return ONLY a JSON object: { "blocks": [{id, type, name, html}], "globalCss": "string" }.
    `;
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `User Prompt: ${prompt}\n\nExisting Code to Upgrade: ${existingHtml || 'None'}`,
        config: { systemInstruction, responseMimeType: "application/json" }
      });
      return JSON.parse(response.text || '{"blocks": [], "globalCss": ""}');
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async analyzeSEO(html: string): Promise<{ score: number, suggestions: string[], metaTags: { title: string, description: string }, criticalFix: string }> {
    const ai = this.getAI();
    const systemInstruction = `
      Perform a professional SEO and Accessibility Audit.
      Return JSON: { "score": number, "suggestions": string[], "metaTags": { "title", "description" }, "criticalFix": "Advice on the single most important change" }.
    `;
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Website HTML: ${html}`,
        config: { systemInstruction, responseMimeType: "application/json" }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async refineBlock(block: Block, instruction: string, tone: DesignTone): Promise<Block> {
    const ai = this.getAI();
    const systemInstruction = `
      Update the following HTML block. 
      Instruction: ${instruction}
      Current Tone: ${tone}
      Maintain Tailwind classes and Lucide icon patterns (<i data-lucide="..."></i>).
      Return JSON block object.
    `;
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Current HTML: ${block.html}`,
        config: { systemInstruction, responseMimeType: "application/json" }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async generateAiImage(prompt: string, styleModifier: string = ""): Promise<string> {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: IMAGE_MODEL,
        contents: { parts: [{ text: `${prompt}. ${styleModifier}. Professional lighting, 8k resolution, cinematic composition.` }] },
        config: { imageConfig: { aspectRatio: "16:9", imageSize: "1K" } }
      });
      const data = response.candidates[0].content.parts.find(p => p.inlineData)?.inlineData?.data;
      if (!data) throw new Error("Image generation failed");
      return `data:image/png;base64,${data}`;
    } catch (e) { return this.handlePotentialKeyError(e); }
  }
}
export const geminiService = new GeminiService();

import React, { useState, useMemo, useEffect } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, LogEntry, DesignTone, Snapshot } from './types';
import { 
  Smartphone, Tablet as TabletIcon, Monitor, Trash2, Wand2, 
  Zap, Sparkles, ShieldCheck, X, CheckCircle, Search, 
  ChevronRight, RefreshCw, Layers, Edit2
} from 'lucide-react';
import { Header } from './components/Header';
import { LeftSidebar } from './components/LeftSidebar';
import { RightSidebar } from './components/RightSidebar';
import { Terminal } from './components/Terminal';

const STORAGE_KEY = 'omni_gen_v3_state_pro_final';

const getInitialState = (): OmniState => ({
  projectName: "New Forge Project",
  metaTitle: "Omni Gen Website",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#6366f1",
  fontFamily: "Inter",
  designTone: 'professional',
  borderRadius: '0.75rem',
  spacingScale: 1.0,
  shadowIntensity: 0.3,
  logs: [],
  snapshots: []
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [isAddingModule, setIsAddingModule] = useState(false);
  const [isRefining, setIsRefining] = useState(false);
  const [refineQuery, setRefineQuery] = useState('');
  const [showRefineInput, setShowRefineInput] = useState(false);
  const [seoResult, setSeoResult] = useState<any>(null);
  const [newModuleQuery, setNewModuleQuery] = useState('');
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [sidebarTab, setSidebarTab] = useState<'blocks' | 'history'>('blocks');

  const addLog = (type: LogEntry['type'], message: string) => {
    const newLog: LogEntry = { id: Math.random().toString(36).substr(2, 9), timestamp: new Date().toLocaleTimeString(), type, message };
    setState(prev => ({ ...prev, logs: [newLog, ...prev.logs].slice(0, 100) }));
  };

  useEffect(() => {
    const handleIframeMessage = (event: MessageEvent) => {
      if (event.data?.type === 'UPDATE_BLOCK_HTML') {
        const { blockId, newHtml } = event.data;
        setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === blockId ? { ...b, html: newHtml } : b) }));
      }
    };
    window.addEventListener('message', handleIframeMessage);
    return () => window.removeEventListener('message', handleIframeMessage);
  }, []);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try { setState({ ...JSON.parse(saved), logs: [] }); } catch (e) { addLog('error', 'Lỗi khôi phục dữ liệu.'); }
    }
    const checkKey = async () => {
      // @ts-ignore
      if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
        // @ts-ignore
        await window.aistudio.openSelectKey();
      }
    };
    checkKey();
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      const { logs, ...rest } = state;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
      setIsSaved(true);
    }, 2000);
    setIsSaved(false);
    return () => clearTimeout(timer);
  }, [state.blocks, state.globalCss, state.accentColor, state.fontFamily, state.projectName, state.designTone, state.spacingScale, state.shadowIntensity]);

  const generateWebsiteHtml = (isInternal: boolean = false) => {
    const content = state.blocks.map(b => 
      isInternal ? `<div data-block-id="${b.id}" class="omni-block-wrapper relative group/block">${b.html}</div>` : b.html
    ).join('\n');

    const annotateScript = isInternal ? `
      <script src="https://unpkg.com/lucide@latest"></script>
      <script>
        (function() {
          lucide.createIcons();
          const style = document.createElement('style');
          style.innerHTML = \`
            .omni-img-overlay {
              position: absolute; top: 10px; right: 10px; background: #6366f1;
              color: white; padding: 6px 14px; border-radius: 99px; font-family: 'Inter', sans-serif;
              font-size: 11px; font-weight: 800; cursor: pointer; display: none; z-index: 99999;
              box-shadow: 0 10px 25px -5px rgba(99, 102, 241, 0.5); border: 2px solid rgba(255,255,255,0.4);
            }
            .omni-img-target { outline: 4px solid #6366f1 !important; outline-offset: -4px; }
            [contenteditable="true"]:focus { outline: 2px dashed #6366f1; outline-offset: 4px; }
          \`;
          document.head.appendChild(style);

          document.querySelectorAll('p, h1, h2, h3, h4, span, a, li, button').forEach(el => {
            if (el.innerText.trim().length > 0) {
              el.setAttribute('contenteditable', 'true');
              el.addEventListener('blur', () => {
                const wrapper = el.closest('[data-block-id]');
                if (wrapper) window.parent.postMessage({ type: 'UPDATE_BLOCK_HTML', blockId: wrapper.getAttribute('data-block-id'), newHtml: wrapper.innerHTML }, '*');
              });
            }
          });

          const overlay = document.createElement('div');
          overlay.className = 'omni-img-overlay';
          overlay.innerHTML = 'EDIT IMAGE';
          document.body.appendChild(overlay);
          let currentImg = null;
          document.addEventListener('mouseover', (e) => {
            const img = e.target.closest('img');
            if (img) {
              currentImg = img; img.classList.add('omni-img-target');
              const rect = img.getBoundingClientRect();
              overlay.style.display = 'block';
              overlay.style.top = (window.scrollY + rect.top + 10) + 'px';
              overlay.style.left = (window.scrollX + rect.right - 100) + 'px';
            } else if (!e.target.closest('.omni-img-overlay')) {
              if (currentImg) { currentImg.classList.remove('omni-img-target'); currentImg = null; }
              overlay.style.display = 'none';
            }
          });
          overlay.addEventListener('click', () => {
            const input = document.createElement('input');
            input.type = 'file'; input.accept = 'image/*';
            input.onchange = (e) => {
              const file = e.target.files[0];
              const reader = new FileReader();
              reader.onload = (re) => {
                if (currentImg) {
                  currentImg.src = re.target.result;
                  const wrapper = currentImg.closest('[data-block-id]');
                  if (wrapper) window.parent.postMessage({ type: 'UPDATE_BLOCK_HTML', blockId: wrapper.getAttribute('data-block-id'), newHtml: wrapper.innerHTML }, '*');
                }
              };
              reader.readAsDataURL(file);
            };
            input.click();
          });
        })();
      </script>
    ` : '';

    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8">
        <script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          :root { --accent: ${state.accentColor}; --spacing-scale: ${state.spacingScale}; --shadow-op: ${state.shadowIntensity}; }
          body { font-family: '${state.fontFamily}', sans-serif; background: #fff; }
          .omni-block-wrapper { transition: opacity 0.3s ease; }
          ${state.globalCss}
        </style>
      </head>
      <body>${content}${annotateScript}</body>
      </html>
    `;
  };

  const handleBuild = async () => {
    setIsProcessing(true);
    addLog('info', `AI Agent đang kiến tạo cấu trúc...`);
    try {
      const result = await geminiService.parseToBlocks(inputSource, state.designTone);
      setState(prev => ({ ...prev, blocks: result.blocks, globalCss: result.globalCss, selectedBlockId: result.blocks[0]?.id || null }));
      setViewMode('preview');
      setTimeout(() => processBlockImages(result.blocks), 800);
    } catch (e: any) { addLog('error', 'Cấu trúc thất bại'); } finally { setIsProcessing(false); }
  };

  const processBlockImages = async (targetBlocks: Block[]) => {
    for (const block of targetBlocks) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgTags = Array.from(doc.querySelectorAll('img[data-ai-prompt]'));
      if (imgTags.length === 0) continue;
      setSyncingBlocks(prev => new Set(prev).add(block.id));
      for (const img of imgTags) {
        const promptText = img.getAttribute('data-ai-prompt');
        if (promptText) {
          try {
            const base64 = await geminiService.generateAiImage(promptText);
            img.setAttribute('src', base64);
            img.removeAttribute('data-ai-prompt');
            setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === block.id ? { ...b, html: doc.body.innerHTML } : b) }));
            setPreviewKey(k => k + 1);
          } catch (e) { addLog('error', 'Lỗi sinh ảnh AI'); }
        }
      }
      setSyncingBlocks(prev => { const n = new Set(prev); n.delete(block.id); return n; });
    }
  };

  const handleRefine = async () => {
    if (!refineQuery.trim() || !state.selectedBlockId) return;
    setIsRefining(true);
    const targetBlock = state.blocks.find(b => b.id === state.selectedBlockId)!;
    addLog('info', `Đang tinh chỉnh Module: ${targetBlock.name}`);
    try {
      const updated = await geminiService.refineBlock(targetBlock, refineQuery, state.designTone);
      setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === state.selectedBlockId ? updated : b) }));
      setRefineQuery('');
      setShowRefineInput(false);
      setPreviewKey(k => k + 1);
      addLog('success', 'Đã cập nhật Module.');
    } catch (e) { addLog('error', 'Tinh chỉnh thất bại.'); } finally { setIsRefining(false); }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <Header 
        projectName={state.projectName} isEditingTitle={isEditingTitle} setIsEditingTitle={setIsEditingTitle}
        setProjectName={(name) => setState(prev => ({ ...prev, projectName: name }))}
        isSaved={isSaved} createSnapshot={() => {}} showTerminal={showTerminal}
        setShowTerminal={setShowTerminal} viewMode={viewMode} setViewMode={setViewMode}
        handleExport={() => {}}
      />

      <main className="flex-1 flex overflow-hidden">
        <LeftSidebar 
          sidebarTab={sidebarTab} setSidebarTab={setSidebarTab}
          blocks={state.blocks} selectedBlockId={state.selectedBlockId}
          setSelectedBlockId={(id) => setState(prev => ({ ...prev, selectedBlockId: id }))}
          setViewMode={setViewMode} moveBlock={() => {}} deleteBlock={() => {}}
          syncingBlocks={syncingBlocks} newModuleQuery={newModuleQuery}
          setNewModuleQuery={setNewModuleQuery} handleAddModule={() => {}}
          isAddingModule={isAddingModule} snapshots={state.snapshots}
          restoreSnapshot={() => {}} deleteSnapshot={() => {}}
          designTone={state.designTone} setDesignTone={(t) => setState(prev => ({ ...prev, designTone: t }))}
        />

        <section className="flex-1 flex flex-col overflow-hidden bg-[#020617] relative">
          <div className="absolute top-6 left-1/2 -translate-x-1/2 z-[80] flex gap-2">
            {state.blocks.length > 0 && !showRefineInput && (
              <button 
                onClick={() => setShowRefineInput(true)}
                className="px-6 py-2.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-full font-black text-xs shadow-2xl shadow-indigo-600/40 flex items-center gap-2 border border-indigo-400/30 animate-in zoom-in"
              >
                <Sparkles className="w-3.5 h-3.5" /> REFINE MODULE
              </button>
            )}
            {showRefineInput && (
              <div className="flex items-center gap-2 bg-[#0b0f1a] p-1.5 rounded-full border border-indigo-500/30 shadow-2xl animate-in slide-in-from-top-4">
                <input 
                  autoFocus
                  value={refineQuery}
                  onChange={(e) => setRefineQuery(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleRefine()}
                  placeholder="Yêu cầu AI sửa Module này..."
                  className="bg-transparent border-none outline-none text-xs px-4 w-64 text-slate-200"
                />
                <button onClick={handleRefine} className="p-2 bg-indigo-600 rounded-full hover:bg-indigo-500"><ChevronRight className="w-4 h-4" /></button>
                <button onClick={() => setShowRefineInput(false)} className="p-2 text-slate-500 hover:text-white"><X className="w-4 h-4" /></button>
              </div>
            )}
          </div>

          {viewMode === 'edit' ? (
            <div className="flex-1 flex flex-col p-6 pt-20">
              {state.blocks.length > 0 ? (
                <div className="flex-1 flex flex-col bg-[#0b0f1a] rounded-3xl border border-white/5 overflow-hidden shadow-2xl">
                   <div className="h-10 border-b border-white/5 bg-slate-900/50 flex items-center px-6 text-[10px] font-black uppercase text-slate-500 gap-2">
                      <Layers className="w-3 h-3" /> {state.blocks.find(b => b.id === state.selectedBlockId)?.name} Editor
                   </div>
                   <textarea 
                    value={state.blocks.find(b => b.id === state.selectedBlockId)?.html || ''}
                    onChange={(e) => setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === state.selectedBlockId ? { ...b, html: e.target.value } : b) }))}
                    className="flex-1 p-8 bg-transparent text-slate-300 code-font text-sm outline-none resize-none custom-scrollbar"
                  />
                </div>
              ) : (
                <div className="flex-1 flex flex-col items-center justify-center text-center max-w-xl mx-auto">
                  <div className="w-20 h-20 bg-indigo-600/10 rounded-3xl flex items-center justify-center mb-8 border border-indigo-500/20"><Wand2 className="w-10 h-10 text-indigo-500 animate-pulse" /></div>
                  <h2 className="text-4xl font-black text-white mb-2 italic uppercase tracking-tighter">Forge Agent</h2>
                  <p className="text-slate-500 text-xs mb-10 uppercase tracking-[0.3em] font-bold">2025 Intelligent UI Fabricator</p>
                  <div className="w-full relative group">
                    <textarea 
                      value={inputSource} onChange={(e) => setInputSource(e.target.value)}
                      placeholder="VD: Một trang Landing Page cho ứng dụng AI, tone màu Neon Cyberpunk..."
                      className="w-full h-44 bg-slate-900 border border-white/10 rounded-2xl p-6 text-sm text-white outline-none focus:border-indigo-500 transition-all placeholder:text-slate-700"
                    />
                    <div className="absolute inset-x-0 bottom-0 h-1/2 bg-gradient-to-t from-slate-950/20 to-transparent pointer-events-none rounded-2xl"></div>
                  </div>
                  <button onClick={handleBuild} className="w-full mt-8 py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-indigo-600/30 active:scale-95 transition-all">
                    INITIATE CRAFTING SEQUENCE
                  </button>
                </div>
              )}
            </div>
          ) : (
            <div className="flex-1 flex flex-col overflow-hidden pt-12">
              <div className="h-14 border-b border-white/5 bg-[#0b0f1a]/80 backdrop-blur flex items-center justify-between px-8">
                <div className="flex gap-4">
                  <button onClick={() => setPreviewDevice('mobile')} className={`p-2 rounded-xl transition-all ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}><Smartphone className="w-4 h-4" /></button>
                  <button onClick={() => setPreviewDevice('desktop')} className={`p-2 rounded-xl transition-all ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white' : 'text-slate-500 hover:text-slate-300'}`}><Monitor className="w-4 h-4" /></button>
                </div>
                <div className="flex items-center gap-3">
                  <button 
                    onClick={async () => {
                      setIsProcessing(true);
                      try {
                        const result = await geminiService.analyzeSEO(generateWebsiteHtml(false));
                        setSeoResult(result);
                      } finally { setIsProcessing(false); }
                    }} 
                    className="flex items-center gap-2 px-5 py-2 bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-500 rounded-full text-[10px] font-black border border-emerald-500/20 transition-all"
                  >
                    <ShieldCheck className="w-3.5 h-3.5" /> RUN SEO INTELLIGENCE
                  </button>
                </div>
              </div>
              <div className="flex-1 overflow-y-auto p-12 flex justify-center items-start bg-slate-950/50">
                <div key={previewKey} className={`bg-white shadow-[0_50px_100px_-20px_rgba(0,0,0,0.5)] transition-all duration-700 rounded-sm overflow-hidden ${previewDevice === 'desktop' ? 'w-[1280px]' : 'w-[375px]'}`}>
                  <iframe srcDoc={generateWebsiteHtml(true)} className="w-full h-[3000px] border-none" />
                </div>
              </div>
            </div>
          )}

          {seoResult && (
            <div className="absolute top-24 right-8 w-80 bg-[#0b0f1a]/95 backdrop-blur-2xl border border-indigo-500/30 rounded-3xl shadow-2xl z-[90] p-6 animate-in slide-in-from-right-8 border-t-indigo-500">
              <div className="flex items-center justify-between mb-6">
                <div className="text-[10px] font-black uppercase text-indigo-400 tracking-widest flex items-center gap-2"><Search className="w-3.5 h-3.5" /> SEO Audit</div>
                <button onClick={() => setSeoResult(null)} className="p-1 hover:bg-white/5 rounded-full"><X className="w-4 h-4 text-slate-500" /></button>
              </div>
              <div className="flex items-center gap-5 mb-8">
                <div className="relative w-20 h-20 flex items-center justify-center">
                  <svg className="w-full h-full transform -rotate-90">
                    <circle cx="40" cy="40" r="34" stroke="currentColor" strokeWidth="6" fill="transparent" className="text-slate-800" />
                    <circle cx="40" cy="40" r="34" stroke="currentColor" strokeWidth="6" fill="transparent" strokeDasharray={213.6} strokeDashoffset={213.6 - (213.6 * seoResult.score) / 100} className="text-indigo-500 transition-all duration-1000" />
                  </svg>
                  <span className="absolute text-xl font-black text-white">{seoResult.score}</span>
                </div>
                <div className="flex-1">
                  <div className="text-[10px] text-slate-500 font-bold uppercase mb-1">Visibility Health</div>
                  <div className="text-sm font-black text-white">{seoResult.score > 80 ? 'EXCELLENT' : 'NEEDS FIXES'}</div>
                </div>
              </div>
              <div className="space-y-4 mb-8">
                {seoResult.suggestions.map((s: string, i: number) => (
                  <div key={i} className="flex gap-3 text-[10px] text-slate-400 leading-relaxed bg-white/5 p-2 rounded-lg border border-white/5">
                    <CheckCircle className="w-3.5 h-3.5 text-emerald-500 shrink-0 mt-0.5" /> {s}
                  </div>
                ))}
              </div>
              <div className="p-4 bg-indigo-600/10 rounded-2xl border border-indigo-500/20">
                <div className="text-[9px] font-black text-indigo-400 uppercase mb-2">Critical Recommendation</div>
                <div className="text-[11px] text-slate-200 font-medium italic">"{seoResult.criticalFix}"</div>
              </div>
            </div>
          )}

          {showTerminal && <Terminal logs={state.logs} onClose={() => setShowTerminal(false)} />}
        </section>

        <RightSidebar 
          accentColor={state.accentColor} setAccentColor={(v) => setState(prev => ({ ...prev, accentColor: v }))}
          fontFamily={state.fontFamily} setFontFamily={(v) => setState(prev => ({ ...prev, fontFamily: v }))}
          spacingScale={state.spacingScale} setSpacingScale={(v) => setState(prev => ({ ...prev, spacingScale: v }))}
          shadowIntensity={state.shadowIntensity} setShadowIntensity={(v) => setState(prev => ({ ...prev, shadowIntensity: v }))}
          handleReset={() => setState(getInitialState())}
        />
      </main>

      {(isProcessing || isAddingModule || isRefining) && (
        <div className="absolute inset-0 bg-slate-950/95 backdrop-blur-3xl z-[150] flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-500">
           <div className="relative mb-12">
              <div className="w-28 h-28 border-[3px] border-indigo-500/20 border-t-indigo-500 rounded-full animate-spin"></div>
              <Zap className="absolute inset-0 m-auto w-10 h-10 text-indigo-500 animate-pulse" />
           </div>
           <h2 className="text-5xl font-black text-white italic uppercase tracking-tighter mb-4">{isRefining ? 'REFRACTING...' : isAddingModule ? 'GENERATING...' : 'CRAFTING...'}</h2>
           <p className="text-indigo-400 text-xs font-black uppercase tracking-[0.5em] animate-pulse">Neural Engine Protocol Active</p>
        </div>
      )}
    </div>
  );
}

export interface Block {
  id: string;
  type: string;
  name: string;
  html: string;
  css?: string;
}

export interface LogEntry {
  id: string;
  timestamp: string;
  type: 'info' | 'success' | 'error' | 'warning';
  message: string;
  details?: string;
}

export type DesignTone = 'professional' | 'minimalist' | 'cyberpunk' | 'playful' | 'brutalist';

export interface Snapshot {
  id: string;
  timestamp: string;
  name: string;
  state: Omit<OmniState, 'logs' | 'snapshots'>;
}

export interface OmniState {
  projectName: string;
  metaTitle: string;
  blocks: Block[];
  selectedBlockId: string | null;
  globalCss: string;
  accentColor: string;
  fontFamily: string;
  designTone: DesignTone;
  borderRadius: string;
  spacingScale: number;
  shadowIntensity: number;
  logs: LogEntry[];
  snapshots: Snapshot[];
  isAudioPlaying: boolean; // New
}

export interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
}

export interface GeneratedImage {
  url: string;
  prompt: string;
}

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Block, DesignTone } from "../types";

const TEXT_MODEL = 'gemini-3-pro-preview';
const IMAGE_MODEL = 'gemini-3-pro-image-preview';
const TTS_MODEL = 'gemini-2.5-flash-preview-tts';

export class GeminiService {
  private getAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private async handlePotentialKeyError(error: any): Promise<never> {
    if (error?.message?.includes("Requested entity was not found.") || error?.message?.includes("API_KEY_INVALID")) {
      // @ts-ignore
      if (window.aistudio) await window.aistudio.openSelectKey();
    }
    throw error;
  }

  async globalRemix(blocks: Block[], newTone: DesignTone): Promise<{ blocks: Block[], globalCss: string }> {
    const ai = this.getAI();
    const systemInstruction = `
      You are a World-Class Creative Director.
      Task: Transform the entire website's aesthetic to ${newTone.toUpperCase()} style.

      Rules:
      1. Rewrite Tailwind classes for ALL blocks to match the new style.
      2. Keep the content (text) exactly as is.
      3. Provide a new matching globalCss (fonts, animations, variables).
      4. Use Lucide icons consistently.

      Return JSON: { "blocks": [...], "globalCss": "string" }.
    `;
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Current Blocks: ${JSON.stringify(blocks)}`,
        config: { systemInstruction, responseMimeType: "application/json" }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async generateSpeech(text: string): Promise<ArrayBuffer> {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: TTS_MODEL,
        contents: [{ parts: [{ text: `Say this professionally and persuasively: ${text}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
        },
      });
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) throw new Error("No audio data");

      const binaryString = atob(base64Audio);
      const bytes = new Uint8Array(binaryString.length);
      for (let i = 0; i < binaryString.length; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      return bytes.buffer;
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async parseToBlocks(prompt: string, tone: DesignTone = 'professional'): Promise<{ blocks: Block[], globalCss: string }> {
    const ai = this.getAI();
    const systemInstruction = `Architect a landing page. Tone: ${tone}. Use Tailwind + Lucide Icons. Return JSON.`;
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async analyzeSEO(html: string): Promise<any> {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Audit this: ${html}`,
        config: { 
            systemInstruction: "SEO Expert Audit. Return JSON with score, suggestions, metaTags, criticalFix.",
            responseMimeType: "application/json" 
        }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async refineBlock(block: Block, instruction: string, tone: DesignTone): Promise<Block> {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Block: ${block.html}\nInstruct: ${instruction}`,
        config: { 
            systemInstruction: "UI Refiner. Return JSON block object.",
            responseMimeType: "application/json" 
        }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async generateAiImage(prompt: string): Promise<string> {
    const ai = this.getAI();
    const response = await ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: { parts: [{ text: prompt }] },
      config: { imageConfig: { aspectRatio: "16:9", imageSize: "1K" } }
    });
    const part = response.candidates[0].content.parts.find(p => p.inlineData);
    return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
  }
}
