    return () => clearTimeout(timer);
  }, [state.blocks, state.globalCss, state.accentColor, state.fontFamily, state.designTone, state.spacingScale, state.shadowIntensity]);

  const handleGlobalRemix = async (targetTone: DesignTone) => {
    if (state.blocks.length === 0) return;
    setIsProcessing(true);
    addLog('info', `Đang Remix lại toàn bộ giao diện sang phong cách ${targetTone.toUpperCase()}...`);
