  const playNarration = async () => {
    if (state.blocks.length === 0) return;
    setState(prev => ({ ...prev, isAudioPlaying: true }));
    addLog('info', 'AI đang soạn kịch bản thuyết minh...');
    try {
      const allText = state.blocks.map(b => b.html.replace(/<[^>]*>/g, '')).join(' ').slice(0, 500);
      const audioBuffer = await geminiService.generateSpeech(allText);

      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = ctx;

      const decodeAudioData = async (data: ArrayBuffer, ctx: AudioContext, sampleRate: number, numChannels: number): Promise<AudioBuffer> => {
        const dataInt16 = new Int16Array(data);
        const frameCount = dataInt16.length / numChannels;
        const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);
        for (let channel = 0; channel < numChannels; channel++) {
          const channelData = buffer.getChannelData(channel);
          for (let i = 0; i < frameCount; i++) {
            channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
          }
        }
        return buffer;
      };

      const buffer = await decodeAudioData(audioBuffer, ctx, 24000, 1);
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => setState(prev => ({ ...prev, isAudioPlaying: false }));
      source.start();
      addLog('success', 'Đang phát thuyết minh AI...');
