  borderRadius: '0.75rem',
  spacingScale: 1.0,
  shadowIntensity: 0.3,
  logs: [],
  snapshots: [],
  isAudioPlaying: false,
  features: {
    enableVoice: true,
    enableRemix: true,
    enableLiveEdit: true
  }
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [isAddingModule, setIsAddingModule] = useState(false);
  const [isRefining, setIsRefining] = useState(false);
  const [refineQuery, setRefineQuery] = useState('');
  const [showRefineInput, setShowRefineInput] = useState(false);
  const [seoResult, setSeoResult] = useState<any>(null);
  const [newModuleQuery, setNewModuleQuery] = useState('');
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [sidebarTab, setSidebarTab] = useState<'blocks' | 'history'>('blocks');

  const audioContextRef = useRef<AudioContext | null>(null);

  const addLog = (type: LogEntry['type'], message: string) => {
    const newLog: LogEntry = { id: Math.random().toString(36).substr(2, 9), timestamp: new Date().toLocaleTimeString(), type, message };
    setState(prev => ({ ...prev, logs: [newLog, ...prev.logs].slice(0, 100) }));
  };

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try { 
        const parsed = JSON.parse(saved);
        setState({ ...parsed, logs: [], isAudioPlaying: false, features: parsed.features || getInitialState().features }); 
      } catch (e) { }
    }
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      const { logs, snapshots, isAudioPlaying, ...rest } = state;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
      setIsSaved(true);
    }, 2000);
    setIsSaved(false);
    return () => clearTimeout(timer);
  }, [state.blocks, state.globalCss, state.accentColor, state.fontFamily, state.designTone, state.spacingScale, state.shadowIntensity, state.features]);

  const toggleFeature = (feature: keyof typeof state.features) => {
    setState(prev => ({
      ...prev,
      features: { ...prev.features, [feature]: !prev.features[feature] }
    }));
    addLog('info', `Đã ${!state.features[feature] ? 'bật' : 'tắt'} tính năng: ${feature}`);
  };

  const handleGlobalRemix = async (targetTone: DesignTone) => {
    if (!state.features.enableRemix) {
      setState(prev => ({ ...prev, designTone: targetTone }));
      return;
    }
    if (state.blocks.length === 0) return;
    setIsProcessing(true);
    addLog('info', `AI đang Remix website sang tone ${targetTone.toUpperCase()}...`);
    try {
      const result = await geminiService.globalRemix(state.blocks, targetTone);
      setState(prev => ({ ...prev, blocks: result.blocks, globalCss: result.globalCss, designTone: targetTone }));
      setPreviewKey(k => k + 1);
      addLog('success', 'Remix thành công!');
    } catch (e) { addLog('error', 'Remix lỗi.'); } finally { setIsProcessing(false); }
  };

  const playNarration = async () => {
    if (!state.features.enableVoice || state.blocks.length === 0) return;
    setState(prev => ({ ...prev, isAudioPlaying: true }));
    addLog('info', 'Đang tạo kịch bản âm thanh...');
    try {
      const text = state.blocks.map(b => b.html.replace(/<[^>]*>/g, '')).join(' ').slice(0, 400);
      const audioBuffer = await geminiService.generateSpeech(text);
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = ctx;

      const decode = async (data: ArrayBuffer, ctx: AudioContext): Promise<AudioBuffer> => {
        const dataInt16 = new Int16Array(data);
        const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
        const channelData = buffer.getChannelData(0);
        for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
        return buffer;
      };

      const buffer = await decode(audioBuffer, ctx);
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => setState(prev => ({ ...prev, isAudioPlaying: false }));
      source.start();
    } catch (e) { 
      setState(prev => ({ ...prev, isAudioPlaying: false }));
      addLog('error', 'Âm thanh lỗi.');
    }
  };

  const generateWebsiteHtml = (isInternal: boolean = false) => {
    const content = state.blocks.map(b => isInternal ? `<div data-block-id="${b.id}" class="omni-block-wrapper">${b.html}</div>` : b.html).join('\n');

    // Chỉ chèn script sửa text nếu tính năng enableLiveEdit được bật
    const liveEditScript = (isInternal && state.features.enableLiveEdit) ? `
      <script>
        document.querySelectorAll('p, h1, h2, h3, h4, span, button').forEach(el => {
          if(el.innerText.trim().length > 0) el.contentEditable = 'true';
        });
      </script>
    ` : '';

    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8"><script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          :root { --accent: ${state.accentColor}; }
          body { font-family: '${state.fontFamily}', sans-serif; }
          ${state.globalCss}
        </style>
      </head>
      <body>${content}${liveEditScript}</body>
      </html>
    `;
  };

  const handleBuild = async () => {
    setIsProcessing(true);
    try {
      const result = await geminiService.parseToBlocks(inputSource, state.designTone);
      setState(prev => ({ ...prev, blocks: result.blocks, globalCss: result.globalCss, selectedBlockId: result.blocks[0]?.id || null }));
      setViewMode('preview');
      addLog('success', 'Khởi tạo thành công.');
    } catch (e) { addLog('error', 'Lỗi.'); } finally { setIsProcessing(false); }
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <div className="absolute top-0 left-1/4 w-96 h-96 bg-indigo-600/5 blur-[120px] pointer-events-none"></div>

      <Header 
        projectName={state.projectName} isEditingTitle={isEditingTitle} setIsEditingTitle={setIsEditingTitle}
        setProjectName={(name) => setState(prev => ({ ...prev, projectName: name }))}
        isSaved={isSaved} createSnapshot={() => {}} showTerminal={showTerminal}
        setShowTerminal={setShowTerminal} viewMode={viewMode} setViewMode={setViewMode}
        handleExport={() => {
            const blob = new Blob([generateWebsiteHtml(false)], { type: 'text/html' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a'); a.href = url; a.download = `${state.projectName}.html`; a.click();
        }}
      />

      <main className="flex-1 flex overflow-hidden">
        <LeftSidebar 
          sidebarTab={sidebarTab} setSidebarTab={setSidebarTab}
          blocks={state.blocks} selectedBlockId={state.selectedBlockId}
          setSelectedBlockId={(id) => setState(prev => ({ ...prev, selectedBlockId: id }))}
          setViewMode={setViewMode} moveBlock={() => {}} deleteBlock={() => {}}
          syncingBlocks={syncingBlocks} newModuleQuery={newModuleQuery}
          setNewModuleQuery={setNewModuleQuery} handleAddModule={() => {}}
          isAddingModule={isAddingModule} snapshots={state.snapshots}
          restoreSnapshot={() => {}} deleteSnapshot={() => {}}
          designTone={state.designTone} setDesignTone={handleGlobalRemix}
        />

        <section className="flex-1 flex flex-col overflow-hidden relative">
          {/* Floating Magic Bar - Căn cứ vào tính năng bật/tắt */}
          {(state.features.enableVoice || state.features.enableRemix) && state.blocks.length > 0 && (
            <div className="absolute top-6 left-1/2 -translate-x-1/2 z-[80] flex gap-3 p-1.5 bg-[#0b0f1a]/80 backdrop-blur-2xl rounded-2xl border border-white/5 shadow-2xl animate-in fade-in slide-in-from-top-4">
              {state.features.enableRemix && (
                <button 
                  onClick={() => setShowRefineInput(!showRefineInput)}
                  className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${showRefineInput ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'}`}
                >
                  <Sparkles className="w-3.5 h-3.5" /> AI Remix
                </button>
              )}
              {state.features.enableVoice && (
                <button 
                  onClick={playNarration}
                  disabled={state.isAudioPlaying}
                  className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${state.isAudioPlaying ? 'text-indigo-400' : 'text-slate-400 hover:text-white'}`}
                >
                  {state.isAudioPlaying ? <Volume2 className="w-3.5 h-3.5 animate-bounce" /> : <Play className="w-3.5 h-3.5" />}
                  Audio Pitch
                </button>
              )}
            </div>
          )}

          {showRefineInput && (
            <div className="absolute top-20 left-1/2 -translate-x-1/2 z-[80] w-96 p-4 bg-[#0b0f1a] border border-indigo-500/30 rounded-2xl shadow-2xl animate-in zoom-in">
              <textarea 
                autoFocus value={refineQuery} onChange={(e) => setRefineQuery(e.target.value)}
                placeholder="Yêu cầu AI sửa module này..."
                className="w-full bg-slate-900 border border-white/10 rounded-xl p-3 text-xs text-white outline-none h-20 mb-3"
              />
              <div className="flex justify-end gap-2">
                <button onClick={() => setShowRefineInput(false)} className="px-3 py-1.5 text-[10px] font-black text-slate-500">HỦY</button>
                <button 
                  onClick={async () => {
                    setIsRefining(true);
                    try {
                      const updated = await geminiService.refineBlock(state.blocks.find(b => b.id === state.selectedBlockId)!, refineQuery, state.designTone);
                      setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === state.selectedBlockId ? updated : b) }));
                      setRefineQuery(''); setShowRefineInput(false); setPreviewKey(k => k + 1);
                    } finally { setIsRefining(false); }
                  }}
                  className="px-4 py-1.5 bg-indigo-600 text-white text-[10px] font-black rounded-lg"
                >ÁP DỤNG</button>
              </div>
            </div>
          )}

          {viewMode === 'edit' ? (
            <div className="flex-1 flex flex-col p-6 pt-24">
              {state.blocks.length > 0 ? (
                <div className="flex-1 flex flex-col bg-[#0b0f1a] rounded-3xl border border-white/5 overflow-hidden">
                   <div className="h-10 border-b border-white/5 bg-slate-900/50 flex items-center px-6 text-[10px] font-black uppercase text-slate-500 gap-2">
                      <Layers className="w-3 h-3" /> {state.blocks.find(b => b.id === state.selectedBlockId)?.name}
                   </div>
                   <textarea 
                    value={state.blocks.find(b => b.id === state.selectedBlockId)?.html || ''}
                    onChange={(e) => setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === state.selectedBlockId ? { ...b, html: e.target.value } : b) }))}
                    className="flex-1 p-8 bg-transparent text-slate-300 code-font text-sm outline-none resize-none"
                  />
                </div>
              ) : (
                <div className="flex-1 flex flex-col items-center justify-center text-center max-w-xl mx-auto">
                   <Wand2 className="w-16 h-16 text-indigo-500 mb-8 animate-pulse" />
                   <h2 className="text-5xl font-black text-white mb-2 italic uppercase">HTML Forge 3.0</h2>
                   <p className="text-slate-600 text-[10px] uppercase tracking-[0.4em] mb-10 font-bold">Neural Design Architecture</p>
                   <textarea 
                    value={inputSource} onChange={(e) => setInputSource(e.target.value)}
                    placeholder="Mô tả website của bạn..."
                    className="w-full h-44 bg-slate-900/50 border border-white/10 rounded-2xl p-6 text-sm text-white outline-none focus:border-indigo-500 transition-all shadow-inner"
                  />
                  <button onClick={handleBuild} className="w-full mt-8 py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black uppercase tracking-widest transition-all">
                    START BUILDING
                  </button>
                </div>
              )}
            </div>
          ) : (
            <div className="flex-1 flex flex-col overflow-hidden pt-20">
              <div className="h-14 border-b border-white/5 bg-[#0b0f1a]/50 backdrop-blur flex items-center justify-between px-8">
                <div className="flex gap-4">
                  <button onClick={() => setPreviewDevice('mobile')} className={`p-2 rounded-xl ${previewDevice === 'mobile' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Smartphone className="w-4 h-4" /></button>
                  <button onClick={() => setPreviewDevice('desktop')} className={`p-2 rounded-xl ${previewDevice === 'desktop' ? 'bg-indigo-600 text-white' : 'text-slate-500'}`}><Monitor className="w-4 h-4" /></button>
                </div>
              </div>
              <div className="flex-1 overflow-y-auto p-12 flex justify-center items-start bg-slate-950/20">
                <div key={previewKey} className={`bg-white shadow-2xl transition-all duration-700 rounded-lg overflow-hidden ${previewDevice === 'desktop' ? 'w-[1200px]' : 'w-[375px]'}`}>
                  <iframe srcDoc={generateWebsiteHtml(true)} className="w-full h-[3000px] border-none" />
                </div>
              </div>
            </div>
          )}

          {showTerminal && <Terminal logs={state.logs} onClose={() => setShowTerminal(false)} />}
        </section>

        <RightSidebar 
          accentColor={state.accentColor} setAccentColor={(v) => setState(prev => ({ ...prev, accentColor: v }))}
          fontFamily={state.fontFamily} setFontFamily={(v) => setState(prev => ({ ...prev, fontFamily: v }))}
          spacingScale={state.spacingScale} setSpacingScale={(v) => setState(prev => ({ ...prev, spacingScale: v }))}
          shadowIntensity={state.shadowIntensity} setShadowIntensity={(v) => setState(prev => ({ ...prev, shadowIntensity: v }))}
          handleReset={() => setState(getInitialState())}
          features={state.features} toggleFeature={toggleFeature} // New: Toggles
        />
      </main>

      {(isProcessing || isAddingModule || isRefining) && (
        <div className="absolute inset-0 bg-slate-950/98 backdrop-blur-[100px] z-[150] flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-500">
           <Music className="w-12 h-12 text-indigo-500 animate-bounce mb-8" />
           <h2 className="text-4xl font-black text-white italic uppercase tracking-tighter mb-2">NEURAL ENGINE ACTIVE</h2>
           <p className="text-indigo-400 text-[10px] font-black uppercase tracking-[0.5em] opacity-60">Synchronizing Design Patterns</p>
        </div>
      )}
    </div>
  );
}

import React from 'react';
import { Palette, Box, Layers, Settings2, Zap, Volume2, Edit3 } from 'lucide-react';
import { OmniFeatures } from '../types';

interface RightSidebarProps {
  accentColor: string;
  setAccentColor: (val: string) => void;
  fontFamily: string;
  setFontFamily: (val: string) => void;
  spacingScale: number;
  setSpacingScale: (val: number) => void;
  shadowIntensity: number;
  setShadowIntensity: (val: number) => void;
  handleReset: () => void;
  features: OmniFeatures;
  toggleFeature: (feature: keyof OmniFeatures) => void;
}

export const RightSidebar: React.FC<RightSidebarProps> = ({
  accentColor, setAccentColor, fontFamily, setFontFamily, 
  spacingScale, setSpacingScale, shadowIntensity, setShadowIntensity, 
  handleReset, features, toggleFeature
}) => {
  return (
    <aside className="w-64 bg-[#0b0f1a] border-l border-white/5 p-6 flex flex-col gap-8 shrink-0 overflow-y-auto custom-scrollbar">
      <div className="space-y-6">
        <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
          <Settings2 className="w-3.5 h-3.5 text-indigo-400" /> Power Features
        </h3>

        <div className="space-y-3">
          <FeatureToggle 
            label="AI Voice Narration" 
            icon={<Volume2 className="w-3 h-3" />} 
            active={features.enableVoice} 
            onClick={() => toggleFeature('enableVoice')} 
          />
          <FeatureToggle 
            label="Global AI Remix" 
            icon={<Zap className="w-3 h-3" />} 
            active={features.enableRemix} 
            onClick={() => toggleFeature('enableRemix')} 
          />
          <FeatureToggle 
            label="Live Content Edit" 
            icon={<Edit3 className="w-3 h-3" />} 
            active={features.enableLiveEdit} 
            onClick={() => toggleFeature('enableLiveEdit')} 
          />
        </div>
      </div>

      <div className="h-px bg-white/5"></div>

      <div className="space-y-6">
        <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
          <Palette className="w-3.5 h-3.5 text-indigo-400" /> Visual Identity
        </h3>

        <div className="space-y-4">
          <div className="space-y-2">
            <label className="text-[9px] font-bold text-slate-500 uppercase">Accent Master</label>
            <div className="flex items-center gap-3 bg-slate-950 p-2 rounded-xl border border-white/10">
              <input type="color" value={accentColor} onChange={(e) => setAccentColor(e.target.value)} className="w-8 h-8 bg-transparent cursor-pointer border-none rounded" />
              <span className="text-[10px] font-mono font-black text-white uppercase">{accentColor}</span>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[9px] font-bold text-slate-500 uppercase">Typography</label>
            <select value={fontFamily} onChange={(e) => setFontFamily(e.target.value)} className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-[10px] font-black text-white outline-none">
              <option value="Inter">Inter Sans</option>
              <option value="Playfair Display">Elegant Serif</option>
              <option value="Fira Code">Mono Tech</option>
            </select>
          </div>
        </div>

        <div className="space-y-4">
          <div className="space-y-3">
            <div className="flex justify-between items-center">
              <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-2">
                <Box className="w-3 h-3" /> Spacing
              </label>
              <span className="text-[10px] text-indigo-400 font-bold">{spacingScale}x</span>
            </div>
            <input 
              type="range" min="0.5" max="2" step="0.1" 
              value={spacingScale} onChange={(e) => setSpacingScale(parseFloat(e.target.value))}
              className="w-full accent-indigo-500"
            />
          </div>

          <div className="space-y-3">
            <div className="flex justify-between items-center">
              <label className="text-[9px] font-bold text-slate-500 uppercase flex items-center gap-2">
                <Layers className="w-3 h-3" /> Shadows
              </label>
              <span className="text-[10px] text-indigo-400 font-bold">{Math.round(shadowIntensity * 100)}%</span>
            </div>
            <input 
              type="range" min="0" max="1" step="0.05" 
              value={shadowIntensity} onChange={(e) => setShadowIntensity(parseFloat(e.target.value))}
              className="w-full accent-indigo-500"
            />
          </div>
        </div>
      </div>

      <div className="mt-auto pt-6 border-t border-white/5">
        <button 
          onClick={handleReset} 
          className="w-full py-2 bg-red-500/10 hover:bg-red-500/20 text-red-500 border border-red-500/20 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all"
        >
          Reset Studio
        </button>
      </div>
    </aside>
  );
};

const FeatureToggle: React.FC<{ label: string, icon: React.ReactNode, active: boolean, onClick: () => void }> = ({ label, icon, active, onClick }) => (
  <button 
    onClick={onClick}
    className={`w-full flex items-center justify-between p-2.5 rounded-xl border transition-all ${active ? 'bg-indigo-600/10 border-indigo-500/30 text-indigo-400' : 'bg-slate-900/50 border-white/5 text-slate-500'}`}
  >
    <div className="flex items-center gap-2">
      {icon}
      <span className="text-[9px] font-black uppercase tracking-tighter">{label}</span>
    </div>
    <div className={`w-6 h-3 rounded-full relative transition-colors ${active ? 'bg-indigo-500' : 'bg-slate-700'}`}>
      <div className={`absolute top-0.5 w-2 h-2 rounded-full bg-white transition-all ${active ? 'left-3.5' : 'left-0.5'}`}></div>
    </div>
  </button>
);

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, LogEntry, DesignTone } from './types';
import { 
  Smartphone, Monitor, Trash2, Wand2, 
  Zap, Sparkles, ShieldCheck, X, CheckCircle, Search, 
  ChevronRight, Layers, Play, Volume2, Music, Palette, Settings2
} from 'lucide-react';
import { Header } from './components/Header';
import { LeftSidebar } from './components/LeftSidebar';
import { RightSidebar } from './components/RightSidebar';
import { Terminal } from './components/Terminal';

const STORAGE_KEY = 'omni_gen_v3_state_pro_final';

const getInitialState = (): OmniState => ({
  projectName: "Omni Project 3.0",
  metaTitle: "Landing Page AI",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#6366f1",
  fontFamily: "Inter",
  designTone: 'professional',
  borderRadius: '0.75rem',
  spacingScale: 1.0,
  shadowIntensity: 0.3,
  logs: [],
  snapshots: [],
  isAudioPlaying: false,
  features: {
    enableVoice: true,
    enableRemix: true,
    enableLiveEdit: true
  }
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [isAddingModule, setIsAddingModule] = useState(false);
  const [isRefining, setIsRefining] = useState(false);
  const [refineQuery, setRefineQuery] = useState('');
  const [showRefineInput, setShowRefineInput] = useState(false);
  const [seoResult, setSeoResult] = useState<any>(null);
  const [newModuleQuery, setNewModuleQuery] = useState('');
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [sidebarTab, setSidebarTab] = useState<'blocks' | 'history'>('blocks');

  const audioContextRef = useRef<AudioContext | null>(null);

  const addLog = (type: LogEntry['type'], message: string) => {
    const newLog: LogEntry = { id: Math.random().toString(36).substr(2, 9), timestamp: new Date().toLocaleTimeString(), type, message };
    setState(prev => ({ ...prev, logs: [newLog, ...prev.logs].slice(0, 100) }));
  };

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try { 
        const parsed = JSON.parse(saved);
        setState({ ...parsed, logs: [], isAudioPlaying: false, features: parsed.features || getInitialState().features }); 
      } catch (e) { }
    }
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      const { logs, snapshots, isAudioPlaying, ...rest } = state;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
      setIsSaved(true);
    }, 2000);
    setIsSaved(false);
    return () => clearTimeout(timer);
  }, [state.blocks, state.globalCss, state.accentColor, state.fontFamily, state.designTone, state.spacingScale, state.shadowIntensity, state.features]);

  // Fix implicit symbol to string conversion by wrapping feature in String()
  const toggleFeature = (feature: keyof typeof state.features) => {
    setState(prev => ({
      ...prev,
      features: { ...prev.features, [feature]: !prev.features[feature] }
    }));
    addLog('info', `Đã ${!state.features[feature] ? 'bật' : 'tắt'} tính năng: ${String(feature)}`);
  };

  const handleGlobalRemix = async (targetTone: DesignTone) => {
    if (!state.features.enableRemix) {
      setState(prev => ({ ...prev, designTone: targetTone }));
      return;
    }
    if (state.blocks.length === 0) return;
    setIsProcessing(true);
    addLog('info', `AI đang Remix website sang tone ${targetTone.toUpperCase()}...`);
    try {
      const result = await geminiService.globalRemix(state.blocks, targetTone);
      setState(prev => ({ ...prev, blocks: result.blocks, globalCss: result.globalCss, designTone: targetTone }));
      setPreviewKey(k => k + 1);
      addLog('success', 'Remix thành công!');
    } catch (e) { addLog('error', 'Remix lỗi.'); } finally { setIsProcessing(false); }
  };

  const playNarration = async () => {
    if (!state.features.enableVoice || state.blocks.length === 0) return;
    setState(prev => ({ ...prev, isAudioPlaying: true }));
    addLog('info', 'Đang tạo kịch bản âm thanh...');
    try {
      const text = state.blocks.map(b => b.html.replace(/<[^>]*>/g, '')).join(' ').slice(0, 400);
      const audioBuffer = await geminiService.generateSpeech(text);
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = ctx;

      const decode = async (data: ArrayBuffer, ctx: AudioContext): Promise<AudioBuffer> => {
        const dataInt16 = new Int16Array(data);
        const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
        const channelData = buffer.getChannelData(0);
        for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
        return buffer;
      };

      const buffer = await decode(audioBuffer, ctx);
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => setState(prev => ({ ...prev, isAudioPlaying: false }));
      source.start();
    } catch (e) { 
      setState(prev => ({ ...prev, isAudioPlaying: false }));
      addLog('error', 'Âm thanh lỗi.');
    }
  };

  const generateWebsiteHtml = (isInternal: boolean = false) => {
    const content = state.blocks.map(b => isInternal ? `<div data-block-id="${b.id}" class="omni-block-wrapper">${b.html}</div>` : b.html).join('\n');

    // Chỉ chèn script sửa text nếu tính năng enableLiveEdit được bật
    const liveEditScript = (isInternal && state.features.enableLiveEdit) ? `
      <script>
        document.querySelectorAll('p, h1, h2, h3, h4, span, button').forEach(el => {
          if(el.innerText.trim().length > 0) el.contentEditable = 'true';
        });
      </script>
    ` : '';

    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8"><script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          :root { --accent: ${state.accentColor}; }
          body { font-family: '${state.fontFamily}', sans-serif; }
          ${state.globalCss}
        </style>
      </head>
      <body>${content}${liveEditScript}</body>
      </html>
    `;
  };

  const handleBuild = async () => {
    setIsProcessing(true);
    try {
      const result = await geminiService.parseToBlocks(inputSource, state.designTone);
      setState(prev => ({ ...prev, blocks: result.blocks, globalCss: result.globalCss, selectedBlockId: result.blocks[0]?.id || null }));
      setViewMode('preview');
      addLog('success', 'Khởi tạo thành công.');
    } catch (e) { addLog('error', 'Lỗi.'); } finally { setIsProcessing(false); }
  };

  return (
