    enableRemix: true,
    enableLiveEdit: true
  },
  googleFormUrl: ""
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [isAddingModule, setIsAddingModule] = useState(false);
  const [isRefining, setIsRefining] = useState(false);
  const [refineQuery, setRefineQuery] = useState('');
  const [showRefineInput, setShowRefineInput] = useState(false);
  const [seoResult, setSeoResult] = useState<any>(null);
  const [newModuleQuery, setNewModuleQuery] = useState('');
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [sidebarTab, setSidebarTab] = useState<'blocks' | 'history'>('blocks');

  const audioContextRef = useRef<AudioContext | null>(null);

  const addLog = (type: LogEntry['type'], message: string) => {
    const newLog: LogEntry = { id: Math.random().toString(36).substr(2, 9), timestamp: new Date().toLocaleTimeString(), type, message };
    setState(prev => ({ ...prev, logs: [newLog, ...prev.logs].slice(0, 100) }));
  };

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try { 
        const parsed = JSON.parse(saved);
        setState({ 
          ...parsed, 
          logs: [], 
          isAudioPlaying: false, 
          features: parsed.features || getInitialState().features,
          googleFormUrl: parsed.googleFormUrl || ""
        }); 
      } catch (e) { }
    }
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      const { logs, snapshots, isAudioPlaying, ...rest } = state;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
      setIsSaved(true);
    }, 2000);
    setIsSaved(false);
    return () => clearTimeout(timer);
  }, [state.blocks, state.globalCss, state.accentColor, state.fontFamily, state.designTone, state.spacingScale, state.shadowIntensity, state.features, state.googleFormUrl]);

  const toggleFeature = (feature: keyof typeof state.features) => {
    setState(prev => ({
      ...prev,
      features: { ...prev.features, [feature]: !prev.features[feature] }
    }));
    addLog('info', `Đã ${!state.features[feature] ? 'bật' : 'tắt'} tính năng: ${String(feature)}`);
  };

  const deployFormBlock = () => {
    if (!state.googleFormUrl) {
      addLog('warning', 'Vui lòng nhập link Google Form trước.');
      return;
    }

    let embedUrl = state.googleFormUrl;
    if (!embedUrl.includes('embedded=true')) {
      embedUrl += (embedUrl.includes('?') ? '&' : '?') + 'embedded=true';
    }

    const newBlock: Block = {
      id: Math.random().toString(36).substr(2, 9),
      type: 'form',
      name: 'Google Form Section',
      html: `
        <section class="py-20 bg-slate-50 flex flex-col items-center">
          <div class="max-w-4xl w-full px-6 text-center mb-10">
            <h2 class="text-3xl font-black text-slate-900 uppercase tracking-tight mb-4">Contact Us</h2>
            <p class="text-slate-600">Please fill out the form below and we'll get back to you shortly.</p>
          </div>
          <div class="w-full max-w-2xl bg-white rounded-3xl overflow-hidden shadow-2xl border border-slate-200">
            <iframe 
              src="${embedUrl}" 
              width="100%" 
              height="800" 
              frameborder="0" 
              marginheight="0" 
              marginwidth="0"
              style="border: none;"
            >Loading…</iframe>
          </div>
        </section>
      `
    };

    setState(prev => ({
      ...prev,
      blocks: [...prev.blocks, newBlock],
      selectedBlockId: newBlock.id
    }));
    setViewMode('preview');
    addLog('success', 'Đã tích hợp Google Form vào trang web.');
  };

  const handleGlobalRemix = async (targetTone: DesignTone) => {
    if (!state.features.enableRemix) {
      setState(prev => ({ ...prev, designTone: targetTone }));
      return;
    }
    if (state.blocks.length === 0) return;
    setIsProcessing(true);
    addLog('info', `AI đang Remix website sang tone ${targetTone.toUpperCase()}...`);
    try {
      const result = await geminiService.globalRemix(state.blocks, targetTone);
      setState(prev => ({ 
        ...prev, 
        blocks: result.blocks || [], 
        globalCss: result.globalCss || prev.globalCss, 
        designTone: targetTone 
      }));
      setPreviewKey(k => k + 1);
      addLog('success', 'Remix thành công!');
    } catch (e) { addLog('error', 'Remix lỗi.'); } finally { setIsProcessing(false); }
  };

  const playNarration = async () => {
    if (!state.features.enableVoice || state.blocks.length === 0) return;
    setState(prev => ({ ...prev, isAudioPlaying: true }));
    addLog('info', 'Đang tạo kịch bản âm thanh...');
    try {
      const text = state.blocks.map(b => b.html.replace(/<[^>]*>/g, '')).join(' ').slice(0, 400);
      const audioBuffer = await geminiService.generateSpeech(text);
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = ctx;

      const decode = async (data: ArrayBuffer, ctx: AudioContext): Promise<AudioBuffer> => {
        const dataInt16 = new Int16Array(data);
        const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
        const channelData = buffer.getChannelData(0);
        for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
        return buffer;
      };

      const buffer = await decode(audioBuffer, ctx);
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => setState(prev => ({ ...prev, isAudioPlaying: false }));
      source.start();
    } catch (e) { 
      setState(prev => ({ ...prev, isAudioPlaying: false }));
      addLog('error', 'Âm thanh lỗi.');
    }
  };

  const generateWebsiteHtml = (isInternal: boolean = false) => {
    const content = state.blocks.map(b => isInternal ? `<div data-block-id="${b.id}" class="omni-block-wrapper">${b.html}</div>` : b.html).join('\n');
    const liveEditScript = (isInternal && state.features.enableLiveEdit) ? `
      <script>
        document.querySelectorAll('p, h1, h2, h3, h4, span, button').forEach(el => {
          if(el.innerText.trim().length > 0) el.contentEditable = 'true';
        });
      </script>
    ` : '';

    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8"><script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          :root { --accent: ${state.accentColor}; }
          body { font-family: '${state.fontFamily}', sans-serif; }
          ${state.globalCss}
        </style>
      </head>
      <body>${content}${liveEditScript}</body>
      </html>
    `;
  };

  const handleBuild = async () => {
    setIsProcessing(true);
    try {
      const result = await geminiService.parseToBlocks(inputSource, state.designTone);
      const blocks = result.blocks || [];
      setState(prev => ({ 
        ...prev, 
        blocks: blocks, 
        globalCss: result.globalCss || prev.globalCss, 
        selectedBlockId: blocks[0]?.id || null 
      }));
      setViewMode('preview');
      addLog('success', 'Khởi tạo thành công.');
    } catch (e) { addLog('error', 'Lỗi.'); } finally { setIsProcessing(false); }
  };

  const currentBlock = useMemo(() => state.blocks.find(b => b.id === state.selectedBlockId), [state.blocks, state.selectedBlockId]);

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <div className="absolute top-0 left-1/4 w-96 h-96 bg-indigo-600/5 blur-[120px] pointer-events-none"></div>

      <Header 
        projectName={state.projectName} isEditingTitle={isEditingTitle} setIsEditingTitle={setIsEditingTitle}
        setProjectName={(name) => setState(prev => ({ ...prev, projectName: name }))}
        isSaved={isSaved} createSnapshot={() => {}} showTerminal={showTerminal}
        setShowTerminal={setShowTerminal} viewMode={viewMode} setViewMode={setViewMode}
        handleExport={() => {
            const blob = new Blob([generateWebsiteHtml(false)], { type: 'text/html' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a'); a.href = url; a.download = `${state.projectName}.html`; a.click();
        }}
      />

      <main className="flex-1 flex overflow-hidden">
        <LeftSidebar 
          sidebarTab={sidebarTab} setSidebarTab={setSidebarTab}
          blocks={state.blocks} selectedBlockId={state.selectedBlockId}
          setSelectedBlockId={(id) => setState(prev => ({ ...prev, selectedBlockId: id }))}
          setViewMode={setViewMode} moveBlock={() => {}} deleteBlock={() => {}}
          syncingBlocks={syncingBlocks} newModuleQuery={newModuleQuery}
          setNewModuleQuery={setNewModuleQuery} handleAddModule={() => {}}
          isAddingModule={isAddingModule} snapshots={state.snapshots}
          restoreSnapshot={() => {}} deleteSnapshot={() => {}}
          designTone={state.designTone} setDesignTone={handleGlobalRemix}
        />

        <section className="flex-1 flex flex-col overflow-hidden relative">
          {(state.features.enableVoice || state.features.enableRemix) && state.blocks.length > 0 && (
            <div className="absolute top-6 left-1/2 -translate-x-1/2 z-[80] flex gap-3 p-1.5 bg-[#0b0f1a]/80 backdrop-blur-2xl rounded-2xl border border-white/5 shadow-2xl animate-in fade-in slide-in-from-top-4">
              {state.features.enableRemix && (
                <button 
                  onClick={() => setShowRefineInput(!showRefineInput)}
                  className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${showRefineInput ? 'bg-indigo-600 text-white' : 'text-slate-400 hover:text-white'}`}
                >
                  <Sparkles className="w-3.5 h-3.5" /> AI Remix
                </button>
              )}
              {state.features.enableVoice && (
                <button 
                  onClick={playNarration}
                  disabled={state.isAudioPlaying}
                  className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase transition-all ${state.isAudioPlaying ? 'text-indigo-400' : 'text-slate-400 hover:text-white'}`}
                >
                  {state.isAudioPlaying ? <Volume2 className="w-3.5 h-3.5 animate-bounce" /> : <Play className="w-3.5 h-3.5" />}
                  Audio Pitch
                </button>
              )}
            </div>
          )}

          {showRefineInput && (
            <div className="absolute top-20 left-1/2 -translate-x-1/2 z-[80] w-96 p-4 bg-[#0b0f1a] border border-indigo-500/30 rounded-2xl shadow-2xl animate-in zoom-in">
              <textarea 
                autoFocus value={refineQuery} onChange={(e) => setRefineQuery(e.target.value)}
                placeholder="Yêu cầu AI sửa module này..."
                className="w-full bg-slate-900 border border-white/10 rounded-xl p-3 text-xs text-white outline-none h-20 mb-3"
              />
              <div className="flex justify-end gap-2">
                <button onClick={() => setShowRefineInput(false)} className="px-3 py-1.5 text-[10px] font-black text-slate-500">HỦY</button>
                <button 
                  onClick={async () => {
                    if (!currentBlock) return;
                    setIsRefining(true);
                    try {
                      const updated = await geminiService.refineBlock(currentBlock, refineQuery, state.designTone);
                      setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === state.selectedBlockId ? updated : b) }));
                      setRefineQuery(''); setShowRefineInput(false); setPreviewKey(k => k + 1);
                    } finally { setIsRefining(false); }
                  }}
                  className="px-4 py-1.5 bg-indigo-600 text-white text-[10px] font-black rounded-lg"
                >ÁP DỤNG</button>
              </div>
            </div>
          )}

          {viewMode === 'edit' ? (
            <div className="flex-1 flex flex-col p-6 pt-24">
              {state.blocks.length > 0 ? (
                <div className="flex-1 flex flex-col bg-[#0b0f1a] rounded-3xl border border-white/5 overflow-hidden">
                   <div className="h-10 border-b border-white/5 bg-slate-900/50 flex items-center px-6 text-[10px] font-black uppercase text-slate-500 gap-2">
                      <Layers className="w-3 h-3" /> {currentBlock?.name || "No Selection"}
                   </div>
                   <textarea 
                    value={currentBlock?.html || ''}
                    onChange={(e) => setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === state.selectedBlockId ? { ...b, html: e.target.value } : b) }))}
