        <RightSidebar 
          accentColor={state.accentColor} setAccentColor={(v) => setState(prev => ({ ...prev, accentColor: v }))}
          fontFamily={state.fontFamily} setFontFamily={(v) => setState(prev => ({ ...prev, fontFamily: v }))}
          spacingScale={state.spacingScale} setSpacingScale={(v) => setState(prev => ({ ...prev, spacingScale: v }))}
          shadowIntensity={state.shadowIntensity} setShadowIntensity={(v) => setState(prev => ({ ...prev, shadowIntensity: v }))}
          handleReset={() => setState(getInitialState())}
          features={state.features} toggleFeature={toggleFeature}
          googleFormUrl={state.googleFormUrl} setGoogleFormUrl={(v) => setState(prev => ({ ...prev, googleFormUrl: v }))}
          deployFormBlock={deployFormBlock}
        />
      </main>

      {(isProcessing || isAddingModule || isRefining) && (
        <div className="absolute inset-0 bg-slate-950/98 backdrop-blur-[100px] z-[150] flex flex-col items-center justify-center p-10 text-center animate-in fade-in duration-500">
           <Music className="w-12 h-12 text-indigo-500 animate-bounce mb-8" />
           <h2 className="text-4xl font-black text-white italic uppercase tracking-tighter mb-2">NEURAL ENGINE ACTIVE</h2>
           <p className="text-indigo-400 text-[10px] font-black uppercase tracking-[0.5em] opacity-60">Synchronizing Design Patterns</p>
        </div>
      )}
    </div>
  );
}

import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Block, DesignTone } from "../types";

const TEXT_MODEL = 'gemini-3-flash-preview'; // Nhanh hơn và ổn định hơn cho logic code
const IMAGE_MODEL = 'gemini-3-pro-image-preview';
const TTS_MODEL = 'gemini-2.5-flash-preview-tts';

export class GeminiService {
  private getAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private async handlePotentialKeyError(error: any): Promise<never> {
    if (error?.message?.includes("Requested entity was not found.") || error?.message?.includes("API_KEY_INVALID")) {
      // @ts-ignore
      if (window.aistudio) await window.aistudio.openSelectKey();
    }
    throw error;
  }

  async globalRemix(blocks: Block[], newTone: DesignTone): Promise<{ blocks: Block[], globalCss: string }> {
    const ai = this.getAI();
    const systemInstruction = `
      You are a World-Class Creative Director.
      Task: Transform the entire website's aesthetic to ${newTone.toUpperCase()} style.

      Rules:
      1. Rewrite Tailwind classes for ALL blocks to match the new style.
      2. Keep the content (text) exactly as is.
      3. Provide a new matching globalCss (fonts, animations, variables).
      4. Use Lucide icons consistently.

      Return ONLY JSON: { "blocks": [...], "globalCss": "string" }.
    `;
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Current Blocks: ${JSON.stringify(blocks)}`,
        config: { systemInstruction, responseMimeType: "application/json" }
      });
      const data = JSON.parse(response.text || '{}');
      return {
        blocks: data.blocks || [],
        globalCss: data.globalCss || ""
      };
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async generateSpeech(text: string): Promise<ArrayBuffer> {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: TTS_MODEL,
        contents: [{ parts: [{ text: `Say this professionally and persuasively: ${text}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
        },
      });
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) throw new Error("No audio data");

      const binaryString = atob(base64Audio);
      const bytes = new Uint8Array(binaryString.length);
      for (let i = 0; i < binaryString.length; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      return bytes.buffer;
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async parseToBlocks(prompt: string, tone: DesignTone = 'professional'): Promise<{ blocks: Block[], globalCss: string }> {
    const ai = this.getAI();
    const systemInstruction = `Architect a landing page. Tone: ${tone}. Use Tailwind + Lucide Icons. Ensure the HTML is high-quality. Return JSON format with 'blocks' array and 'globalCss' string.`;
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: prompt,
        config: { systemInstruction, responseMimeType: "application/json" }
      });
      const data = JSON.parse(response.text || '{}');
      return {
        blocks: data.blocks || [],
        globalCss: data.globalCss || ""
      };
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async addModule(instruction: string, existingBlocks: Block[], tone: DesignTone): Promise<Block> {
    const ai = this.getAI();
    const systemInstruction = `Generate a single HTML block based on the instruction. Tone: ${tone}. Use Tailwind. Return ONLY the JSON for one block object { id, type, name, html }.`;
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `New module request: ${instruction}. Current page structure has ${existingBlocks.length} blocks.`,
        config: { systemInstruction, responseMimeType: "application/json" }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async refineBlock(block: Block, instruction: string, tone: DesignTone): Promise<Block> {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: TEXT_MODEL,
        contents: `Block: ${block.html}\nInstruct: ${instruction}`,
        config: { 
            systemInstruction: "UI Refiner. Modify the HTML/Tailwind of the provided block. Return JSON block object.",
            responseMimeType: "application/json" 
        }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) { return this.handlePotentialKeyError(e); }
  }
}
export const geminiService = new GeminiService();

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { geminiService } from './services/geminiService';
import { Block, OmniState, LogEntry, DesignTone, Snapshot } from './types';
import { 
  Smartphone, Monitor, Trash2, Wand2, 
  Zap, Sparkles, ShieldCheck, X, CheckCircle, Search, 
  ChevronRight, Layers, Play, Volume2, Music, Palette, Settings2
} from 'lucide-react';
import { Header } from './components/Header';
import { LeftSidebar } from './components/LeftSidebar';
import { RightSidebar } from './components/RightSidebar';
import { Terminal } from './components/Terminal';

const STORAGE_KEY = 'omni_gen_v3_state_pro_final';

const getInitialState = (): OmniState => ({
  projectName: "Omni Project 3.0",
  metaTitle: "Landing Page AI",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#6366f1",
  fontFamily: "Inter",
  designTone: 'professional',
  borderRadius: '0.75rem',
  spacingScale: 1.0,
  shadowIntensity: 0.3,
  logs: [],
  snapshots: [],
  isAudioPlaying: false,
  features: {
    enableVoice: true,
    enableRemix: true,
    enableLiveEdit: true
  },
  googleFormUrl: ""
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [isAddingModule, setIsAddingModule] = useState(false);
  const [isRefining, setIsRefining] = useState(false);
  const [refineQuery, setRefineQuery] = useState('');
  const [showRefineInput, setShowRefineInput] = useState(false);
  const [newModuleQuery, setNewModuleQuery] = useState('');
  const [syncingBlocks, setSyncingBlocks] = useState<Set<string>>(new Set());
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('edit');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [isEditingTitle, setIsEditingTitle] = useState(false);
  const [sidebarTab, setSidebarTab] = useState<'blocks' | 'history'>('blocks');

  const audioContextRef = useRef<AudioContext | null>(null);

  const addLog = (type: LogEntry['type'], message: string) => {
    const newLog: LogEntry = { id: Math.random().toString(36).substr(2, 9), timestamp: new Date().toLocaleTimeString(), type, message };
    setState(prev => ({ ...prev, logs: [newLog, ...prev.logs].slice(0, 100) }));
  };

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved) {
      try { 
        const parsed = JSON.parse(saved);
        setState({ 
          ...parsed, 
          logs: [], 
          isAudioPlaying: false, 
          features: parsed.features || getInitialState().features,
          googleFormUrl: parsed.googleFormUrl || ""
        }); 
      } catch (e) { }
    }
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      const { logs, snapshots, isAudioPlaying, ...rest } = state;
      localStorage.setItem(STORAGE_KEY, JSON.stringify(rest));
      setIsSaved(true);
    }, 2000);
    setIsSaved(false);
    return () => clearTimeout(timer);
  }, [state.blocks, state.globalCss, state.accentColor, state.fontFamily, state.designTone, state.spacingScale, state.shadowIntensity, state.features, state.googleFormUrl]);

  const toggleFeature = (feature: keyof typeof state.features) => {
    setState(prev => ({
      ...prev,
      features: { ...prev.features, [feature]: !prev.features[feature] }
    }));
    addLog('info', `Đã ${!state.features[feature] ? 'bật' : 'tắt'} tính năng: ${String(feature)}`);
  };

  const createSnapshot = () => {
    const { logs, snapshots, ...stateToSave } = state;
    const newSnapshot: Snapshot = {
      id: Math.random().toString(36).substr(2, 9),
      name: `Snapshot ${state.snapshots.length + 1} - ${state.blocks.length} blocks`,
      timestamp: new Date().toLocaleString(),
      state: JSON.parse(JSON.stringify(stateToSave))
    };
    setState(prev => ({ ...prev, snapshots: [newSnapshot, ...prev.snapshots] }));
    addLog('success', 'Đã lưu Snapshot thành công.');
  };

  const restoreSnapshot = (snap: Snapshot) => {
    setState(prev => ({
      ...prev,
      ...snap.state,
      snapshots: prev.snapshots,
      logs: prev.logs
    }));
    setPreviewKey(k => k + 1);
    addLog('info', `Đã khôi phục phiên bản: ${snap.name}`);
  };

  const deleteSnapshot = (id: string) => {
    setState(prev => ({ ...prev, snapshots: prev.snapshots.filter(s => s.id !== id) }));
  };

  const moveBlock = (idx: number, dir: 'up' | 'down') => {
    const newBlocks = [...state.blocks];
    const targetIdx = dir === 'up' ? idx - 1 : idx + 1;
    if (targetIdx < 0 || targetIdx >= newBlocks.length) return;
    [newBlocks[idx], newBlocks[targetIdx]] = [newBlocks[targetIdx], newBlocks[idx]];
    setState(prev => ({ ...prev, blocks: newBlocks }));
  };

  const deleteBlock = (id: string) => {
    setState(prev => ({
      ...prev,
      blocks: prev.blocks.filter(b => b.id !== id),
      selectedBlockId: prev.selectedBlockId === id ? (prev.blocks[0]?.id || null) : prev.selectedBlockId
    }));
  };

  const handleAddModule = async () => {
    if (!newModuleQuery.trim()) return;
    setIsAddingModule(true);
    addLog('info', `AI đang tạo module mới: ${newModuleQuery}...`);
    try {
      const newBlock = await geminiService.addModule(newModuleQuery, state.blocks, state.designTone);
      if (newBlock && newBlock.html) {
        setState(prev => ({
          ...prev,
          blocks: [...prev.blocks, { ...newBlock, id: Math.random().toString(36).substr(2, 9) }],
          selectedBlockId: newBlock.id
        }));
        setNewModuleQuery('');
        setPreviewKey(k => k + 1);
        addLog('success', `Đã thêm module: ${newBlock.name}`);
      }
    } catch (e) {
      addLog('error', 'Không thể tạo module. Vui lòng thử lại.');
    } finally {
      setIsAddingModule(false);
    }
  };

  const deployFormBlock = () => {
    if (!state.googleFormUrl) {
      addLog('warning', 'Vui lòng nhập link Google Form trước.');
      return;
    }

    let embedUrl = state.googleFormUrl;
    if (!embedUrl.includes('embedded=true')) {
      embedUrl += (embedUrl.includes('?') ? '&' : '?') + 'embedded=true';
    }

    const newBlock: Block = {
      id: Math.random().toString(36).substr(2, 9),
      type: 'form',
      name: 'Google Form Section',
      html: `
        <section class="py-20 bg-slate-50 flex flex-col items-center">
          <div class="max-w-4xl w-full px-6 text-center mb-10">
            <h2 class="text-3xl font-black text-slate-900 uppercase tracking-tight mb-4">Contact Us</h2>
            <p class="text-slate-600">Please fill out the form below and we'll get back to you shortly.</p>
          </div>
          <div class="w-full max-w-2xl bg-white rounded-3xl overflow-hidden shadow-2xl border border-slate-200">
            <iframe 
              src="${embedUrl}" 
              width="100%" 
              height="800" 
              frameborder="0" 
              marginheight="0" 
              marginwidth="0"
              style="border: none;"
            >Loading…</iframe>
          </div>
        </section>
      `
    };

    setState(prev => ({
      ...prev,
      blocks: [...prev.blocks, newBlock],
      selectedBlockId: newBlock.id
    }));
    setViewMode('preview');
    addLog('success', 'Đã tích hợp Google Form vào trang web.');
  };

  const handleGlobalRemix = async (targetTone: DesignTone) => {
    if (!state.features.enableRemix) {
      setState(prev => ({ ...prev, designTone: targetTone }));
      return;
    }
    if (state.blocks.length === 0) return;
    setIsProcessing(true);
    addLog('info', `AI đang Remix website sang tone ${targetTone.toUpperCase()}...`);
    try {
      const result = await geminiService.globalRemix(state.blocks, targetTone);
      setState(prev => ({ 
        ...prev, 
        blocks: result.blocks || [], 
        globalCss: result.globalCss || prev.globalCss, 
        designTone: targetTone 
      }));
      setPreviewKey(k => k + 1);
      addLog('success', 'Remix thành công!');
    } catch (e) { addLog('error', 'Remix lỗi.'); } finally { setIsProcessing(false); }
  };

  const playNarration = async () => {
    if (!state.features.enableVoice || state.blocks.length === 0) return;
    setState(prev => ({ ...prev, isAudioPlaying: true }));
    addLog('info', 'Đang tạo kịch bản âm thanh...');
    try {
      const text = state.blocks.map(b => b.html.replace(/<[^>]*>/g, '')).join(' ').slice(0, 400);
      const audioBuffer = await geminiService.generateSpeech(text);
      const ctx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = ctx;

      const decode = async (data: ArrayBuffer, ctx: AudioContext): Promise<AudioBuffer> => {
        const dataInt16 = new Int16Array(data);
        const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
        const channelData = buffer.getChannelData(0);
        for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
        return buffer;
      };

      const buffer = await decode(audioBuffer, ctx);
      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => setState(prev => ({ ...prev, isAudioPlaying: false }));
      source.start();
    } catch (e) { 
      setState(prev => ({ ...prev, isAudioPlaying: false }));
      addLog('error', 'Âm thanh lỗi.');
    }
  };

  const generateWebsiteHtml = (isInternal: boolean = false) => {
    const content = state.blocks.map(b => isInternal ? `<div data-block-id="${b.id}" class="omni-block-wrapper">${b.html}</div>` : b.html).join('\n');
    const liveEditScript = (isInternal && state.features.enableLiveEdit) ? `
      <script>
        document.querySelectorAll('p, h1, h2, h3, h4, span, button').forEach(el => {
          if(el.innerText.trim().length > 0) el.contentEditable = 'true';
        });
      </script>
    ` : '';

    return `
      <!DOCTYPE html>
      <html>
      <head>
        <meta charset="UTF-8"><script src="https://cdn.tailwindcss.com"></script>
        <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;700&display=swap" rel="stylesheet">
        <style>
          :root { --accent: ${state.accentColor}; }
          body { font-family: '${state.fontFamily}', sans-serif; }
          ${state.globalCss}
        </style>
      </head>
      <body>${content}${liveEditScript}</body>
      </html>
    `;
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    addLog('info', 'Bắt đầu kiến trúc website...');
    try {
      const result = await geminiService.parseToBlocks(inputSource, state.designTone);
