import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Block, DesignTone } from "../types";

// Sử dụng Pro cho các tác vụ thiết kế và lập trình phức tạp để đảm bảo độ chính xác cao nhất
const COMPLEX_TEXT_MODEL = 'gemini-3-pro-preview'; 
const FLASH_TEXT_MODEL = 'gemini-3-flash-preview';
const IMAGE_MODEL = 'gemini-3-pro-image-preview';
const TTS_MODEL = 'gemini-2.5-flash-preview-tts';

export class GeminiService {
  private getAI() {
    return new GoogleGenAI({ apiKey: process.env.API_KEY });
  }

  private async handlePotentialKeyError(error: any): Promise<never> {
    if (error?.message?.includes("Requested entity was not found.") || error?.message?.includes("API_KEY_INVALID")) {
      // @ts-ignore
      if (window.aistudio) await window.aistudio.openSelectKey();
    }
    throw error;
  }

  async globalRemix(blocks: Block[], newTone: DesignTone): Promise<{ blocks: Block[], globalCss: string }> {
    const ai = this.getAI();
    const systemInstruction = `
      You are a World-Class Creative Director.
      Task: Transform the entire website's aesthetic to ${newTone.toUpperCase()} style.

      Rules:
      1. Rewrite Tailwind classes for ALL blocks to match the new style.
      2. Keep the content (text) exactly as is.
      3. Provide a new matching globalCss (fonts, animations, variables).
      4. Use Lucide icons consistently.

      Output must be valid JSON matching the provided schema.
    `;
    try {
      const response = await ai.models.generateContent({
        model: COMPLEX_TEXT_MODEL,
        contents: `Current Blocks: ${JSON.stringify(blocks)}`,
        config: { 
          systemInstruction, 
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              blocks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    type: { type: Type.STRING },
                    name: { type: Type.STRING },
                    html: { type: Type.STRING }
                  },
                  required: ["id", "type", "name", "html"]
                }
              },
              globalCss: { type: Type.STRING }
            },
            required: ["blocks", "globalCss"]
          }
        }
      });
      const data = JSON.parse(response.text || '{"blocks":[], "globalCss":""}');
      return data;
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async generateSpeech(text: string): Promise<ArrayBuffer> {
    const ai = this.getAI();
    try {
      const response = await ai.models.generateContent({
        model: TTS_MODEL,
        contents: [{ parts: [{ text: `Say this professionally and persuasively: ${text}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } },
          },
        },
      });
      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) throw new Error("No audio data");

      const binaryString = atob(base64Audio);
      const bytes = new Uint8Array(binaryString.length);
      for (let i = 0; i < binaryString.length; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }
      return bytes.buffer;
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async parseToBlocks(prompt: string, tone: DesignTone = 'professional'): Promise<{ blocks: Block[], globalCss: string }> {
    const ai = this.getAI();
    const systemInstruction = `
      You are a Professional Web Architect. 
      Build a high-converting landing page based on the prompt. 
      Tone: ${tone}. Style: Use modern Tailwind CSS 3.4+ and Lucide Icons.
      Ensure the HTML is semantic, clean, and beautiful.
      Generate at least 5 blocks: Hero, Problem, Solution, Pricing, FAQ.
      Output MUST be a JSON object with 'blocks' and 'globalCss'.
    `;
    try {
      const response = await ai.models.generateContent({
        model: COMPLEX_TEXT_MODEL,
        contents: prompt,
        config: { 
          systemInstruction, 
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              blocks: {
                type: Type.ARRAY,
                items: {
                  type: Type.OBJECT,
                  properties: {
                    id: { type: Type.STRING },
                    type: { type: Type.STRING },
                    name: { type: Type.STRING },
                    html: { type: Type.STRING }
                  },
                  required: ["id", "type", "name", "html"]
                }
              },
              globalCss: { type: Type.STRING }
            },
            required: ["blocks", "globalCss"]
          }
        }
      });
      const data = JSON.parse(response.text || '{"blocks":[], "globalCss":""}');
      return data;
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async addModule(instruction: string, existingBlocks: Block[], tone: DesignTone): Promise<Block> {
    const ai = this.getAI();
    const systemInstruction = `
      Create a new website section based on user request.
      Tone: ${tone}. Use Tailwind CSS.
      Return a single block object in JSON format.
    `;
    try {
      const response = await ai.models.generateContent({
        model: FLASH_TEXT_MODEL,
        contents: `New module request: ${instruction}. Current context: page has ${existingBlocks.length} sections.`,
        config: { 
          systemInstruction, 
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              type: { type: Type.STRING },
              name: { type: Type.STRING },
              html: { type: Type.STRING }
            },
            required: ["id", "type", "name", "html"]
          }
        }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) { return this.handlePotentialKeyError(e); }
  }

  async refineBlock(block: Block, instruction: string, tone: DesignTone): Promise<Block> {
    const ai = this.getAI();
    const systemInstruction = `
      Refine the following HTML block.
      Instruction: ${instruction}
      Maintain the ${tone} style and Tailwind CSS.
      Return the updated block object in JSON.
    `;
    try {
      const response = await ai.models.generateContent({
        model: FLASH_TEXT_MODEL,
        contents: `Block HTML: ${block.html}`,
        config: { 
          systemInstruction, 
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              type: { type: Type.STRING },
              name: { type: Type.STRING },
              html: { type: Type.STRING }
            },
            required: ["id", "type", "name", "html"]
          }
        }
      });
      return JSON.parse(response.text || '{}');
    } catch (e) { return this.handlePotentialKeyError(e); }
  }
}
export const geminiService = new GeminiService();

