      setNewModuleQuery('');
      setViewMode('preview');
      setPreviewKey(k => k + 1);
    } catch (e: any) { addLog('error', e.message); } finally { setIsAddingModule(false); }
  };

  const internalHtml = useMemo(() => generateIframeHtml(state, true), [state, previewKey]);

