          overflow: hidden; /* Cực kỳ quan trọng để che khuất ảnh khi kéo lên */
        }

        /* Handle Bar (Thanh điều hướng Elementor) */
        .elementor-handle-bar {
          position: absolute; top: 0; left: 50%; transform: translate(-50%, -50%);
          background: var(--accent); color: white; display: none; gap: 2px; padding: 4px 8px;
          border-radius: 6px; z-index: 100; cursor: grab; align-items: center;
          box-shadow: 0 4px 15px rgba(0,0,0,0.2);
        }
        .elementor-section-wrap:hover > .elementor-handle-bar,
        .elementor-section-wrap.active > .elementor-handle-bar { display: flex; }

        .handle-item { 
          cursor: pointer; padding: 5px; border-radius: 4px; transition: background 0.2s;
          display: flex; align-items: center; justify-content: center;
        }
        .handle-item:hover { background: rgba(255,255,255,0.2); }

        /* Resize Handle (Thanh kéo sát đáy) */
        .elementor-resize-handle {
          position: absolute; bottom: -5px; left: 0; right: 0; height: 15px;
          cursor: ns-resize; display: none; align-items: center; justify-content: center;
          z-index: 100;
        }
        .elementor-section-wrap:hover .elementor-resize-handle,
        .elementor-section-wrap.active .elementor-resize-handle { display: flex; }

        .resize-dot { 
          width: 50px; height: 6px; background: var(--accent); border-radius: 3px; 
          opacity: 0.9; box-shadow: 0 2px 5px rgba(0,0,0,0.2);
          border: 1px solid rgba(255,255,255,0.3);
        }
        .elementor-resize-handle:hover .resize-dot { transform: scaleY(1.5); background: #fff; border-color: var(--accent); }

        .elementor-section-wrap.resizing .elementor-content-inner {
          border-bottom: 2px dashed var(--accent);
        }

        /* AI Image UI */
        .ai-image-target { transition: all 0.5s ease; cursor: pointer; max-width: 100%; height: auto; }
        .ai-image-target.is-generating { filter: blur(5px) brightness(0.5); }

        [contenteditable="true"]:focus { outline: 2px dashed var(--accent); outline-offset: 4px; border-radius: 4px; }

        #canvas-add-btn {
          background: var(--accent); color: white; border: none; padding: 14px 28px;
          font-weight: 900; border-radius: 99px; cursor: pointer; display: block; margin: 40px auto;
          box-shadow: 0 10px 20px rgba(0,0,0,0.1); transition: transform 0.2s;
        }
        #canvas-add-btn:hover { transform: scale(1.05); }

        ${state.globalCss}
      </style>
    </head>
    <body>
      ${content}
      <div class="py-20 flex justify-center bg-slate-50 border-t border-dashed border-slate-200">
         <button id="canvas-add-btn">+ THÊM SECTION MỚI</button>
      </div>
      ${scripts}
    </body>
    </html>
  `;
};

import { OmniState } from '../types';

export const generateIframeHtml = (state: OmniState, isInternal: boolean = true): string => {
  const content = state.blocks.map(b => {
    if (!isInternal) return b.html;
    return `
      <div data-block-id="${b.id}" class="elementor-section-wrap ${state.selectedBlockId === b.id ? 'active' : ''}">
        <!-- Thanh điều khiển phía trên -->
        <div class="elementor-handle-bar">
          <div class="handle-item move-up" title="Di chuyển lên">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="m18 15-6-6-6 6"/></svg>
          </div>
          <div class="handle-item move-down" title="Di chuyển xuống">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="m6 9 6 6 6-6"/></svg>
          </div>
          <div class="handle-item drag-handle" title="Nắm để kéo">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><circle cx="9" cy="12" r="1"/><circle cx="9" cy="5" r="1"/><circle cx="9" cy="19" r="1"/><circle cx="15" cy="12" r="1"/><circle cx="15" cy="5" r="1"/><circle cx="15" cy="19" r="1"/></svg>
          </div>
          <div class="handle-item delete-section" title="Xóa section">
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="M18 6 6 18M6 6l12 12"/></svg>
          </div>
        </div>

        <!-- Container chứa nội dung -->
        <div class="elementor-content-inner">
          ${b.html}
        </div>

        <!-- Thanh kéo giãn chiều cao ở dưới -->
        <div class="elementor-resize-handle" title="Kéo để chỉnh chiều cao">
           <div class="resize-dot"></div>
        </div>
      </div>
    `;
  }).join('\n');

  const scripts = isInternal ? `
    <script>
      (function() {
        function sendToParent(data) { window.parent.postMessage(data, '*'); }

        document.querySelectorAll('.elementor-section-wrap').forEach(section => {
          const id = section.getAttribute('data-block-id');
          const innerContainer = section.querySelector('.elementor-content-inner');
          const resizeHandle = section.querySelector('.elementor-resize-handle');

          // Nút bấm cơ bản
          section.querySelector('.move-up').onclick = (e) => { e.stopPropagation(); sendToParent({ type: 'MOVE_BLOCK', blockId: id, direction: 'up' }); };
          section.querySelector('.move-down').onclick = (e) => { e.stopPropagation(); sendToParent({ type: 'MOVE_BLOCK', blockId: id, direction: 'down' }); };
          section.querySelector('.delete-section').onclick = (e) => { e.stopPropagation(); sendToParent({ type: 'DELETE_BLOCK', blockId: id }); };

          section.onclick = () => sendToParent({ type: 'SELECT_BLOCK', blockId: id });

          // Logic Kéo giãn chiều cao
          let isResizing = false;
          let startY, startHeight, targetElement;

          resizeHandle.onmousedown = (e) => {
            isResizing = true;
            startY = e.clientY;

            // Tìm phần tử thật sự chứa nội dung (thường là section đầu tiên bên trong innerContainer)
            targetElement = innerContainer.firstElementChild || innerContainer;
            startHeight = targetElement.offsetHeight;

            document.body.style.cursor = 'ns-resize';
            section.classList.add('resizing');
            e.preventDefault();
            e.stopPropagation();
          };

          window.addEventListener('mousemove', (e) => {
            if (!isResizing || !targetElement) return;
            const deltaY = e.clientY - startY;
            const newHeight = Math.max(20, startHeight + deltaY);

            // Gán style trực tiếp vào PHẦN TỬ NỘI DUNG để khi lấy innerHTML nó sẽ chứa luôn style này
            targetElement.style.height = newHeight + 'px';
            targetElement.style.minHeight = newHeight + 'px';
            targetElement.style.overflow = 'hidden';
            targetElement.style.display = 'block'; // Đảm bảo height có tác dụng
          });

          window.addEventListener('mouseup', () => {
            if (isResizing) {
              isResizing = false;
              document.body.style.cursor = 'default';
              section.classList.remove('resizing');

              // Gửi nội dung đã được cập nhật inline-style về parent
              const updatedHtml = innerContainer.innerHTML;
              sendToParent({ 
                type: 'UPDATE_BLOCK_HTML', 
                blockId: id, 
                newHtml: updatedHtml 
              });
              targetElement = null;
            }
          });

          // Text editing
          section.querySelectorAll('h1, h2, h3, h4, h5, h6, p, span, a, button').forEach(el => {
            if (el.innerText.trim()) {
              el.contentEditable = "true";
              el.addEventListener('blur', () => {
                sendToParent({ type: 'UPDATE_BLOCK_HTML', blockId: id, newHtml: innerContainer.innerHTML });
              });
            }
          });

          // Image interaction
          section.querySelectorAll('img').forEach((img, index) => {
            img.classList.add('ai-image-target');
            if (img.src.includes('placehold.co')) img.classList.add('is-generating');

            img.onclick = (e) => {
              e.stopPropagation();
              const prompt = img.getAttribute('data-ai-prompt');
              sendToParent({ type: 'REGENERATE_IMAGE', blockId: id, imgIndex: index, prompt: prompt });
            };
          });
        });

        document.getElementById('canvas-add-btn').onclick = () => sendToParent({ type: 'ADD_SECTION_PROMPT' });
      })();
    </script>
  ` : '';

  return `
    <!DOCTYPE html>
    <html lang="vi">
    <head>
      <meta charset="UTF-8">
      <script src="https://cdn.tailwindcss.com"></script>
      <link href="https://fonts.googleapis.com/css2?family=${state.fontFamily}:wght@400;500;600;700&display=swap" rel="stylesheet">
      <style>
        :root { --accent: ${state.accentColor}; --radius: ${state.borderRadius}; }
        body { font-family: '${state.fontFamily}', sans-serif; margin: 0; padding: 0; background: #fff; overflow-x: hidden; }

        .elementor-section-wrap { position: relative; transition: outline 0.1s ease; }
        .elementor-section-wrap:hover { outline: 2px solid var(--accent); outline-offset: -2px; }
        .elementor-section-wrap.active { outline: 3px solid var(--accent); outline-offset: -3px; z-index: 10; }

        .elementor-content-inner {
          position: relative;
          width: 100%;
        }

        /* Handle Bar */
        .elementor-handle-bar {
          position: absolute; top: 0; left: 50%; transform: translate(-50%, -50%);
          background: var(--accent); color: white; display: none; gap: 2px; padding: 4px 8px;
          border-radius: 6px; z-index: 100; cursor: grab; align-items: center;
          box-shadow: 0 4px 15px rgba(0,0,0,0.2);
        }
        .elementor-section-wrap:hover > .elementor-handle-bar,
        .elementor-section-wrap.active > .elementor-handle-bar { display: flex; }

        .handle-item { 
          cursor: pointer; padding: 5px; border-radius: 4px; transition: background 0.2s;
          display: flex; align-items: center; justify-content: center;
        }
        .handle-item:hover { background: rgba(255,255,255,0.2); }

        /* Resize Handle */
        .elementor-resize-handle {
          position: absolute; bottom: -8px; left: 0; right: 0; height: 16px;
          cursor: ns-resize; display: none; align-items: center; justify-content: center;
          z-index: 100;
        }
        .elementor-section-wrap:hover .elementor-resize-handle,
        .elementor-section-wrap.active .elementor-resize-handle { display: flex; }

        .resize-dot { 
          width: 60px; height: 6px; background: var(--accent); border-radius: 3px; 
          opacity: 0.9; box-shadow: 0 2px 8px rgba(0,0,0,0.3);
          border: 1px solid rgba(255,255,255,0.4);
          transition: all 0.2s;
        }
        .elementor-resize-handle:hover .resize-dot { 
          width: 80px; transform: scaleY(1.3); background: #fff; border-color: var(--accent); 
        }

        .elementor-section-wrap.resizing { outline: 2px dashed var(--accent) !important; }

        /* AI Image UI */
        .ai-image-target { transition: all 0.5s ease; cursor: pointer; max-width: 100%; }
        .ai-image-target.is-generating { filter: blur(5px) brightness(0.5); }

        [contenteditable="true"]:focus { outline: 2px dashed var(--accent); outline-offset: 4px; border-radius: 4px; }

        #canvas-add-btn {
          background: var(--accent); color: white; border: none; padding: 14px 28px;
          font-weight: 900; border-radius: 99px; cursor: pointer; display: block; margin: 40px auto;
          box-shadow: 0 10px 20px rgba(0,0,0,0.1); transition: transform 0.2s;
        }
        #canvas-add-btn:hover { transform: scale(1.05); }

        ${state.globalCss}
      </style>
    </head>
    <body>
      ${content}
      <div class="py-20 flex justify-center bg-slate-50 border-t border-dashed border-slate-200">
         <button id="canvas-add-btn">+ THÊM SECTION MỚI</button>
      </div>
      ${scripts}
    </body>
    </html>
  `;
};

export interface Block {
  id: string;
  type: string;
  name: string;
  html: string;
  css?: string;
  heights?: {
    mobile?: number;
    tablet?: number;
    desktop?: number;
  };
}

export interface LogEntry {
  id: string;
  timestamp: string;
  type: 'info' | 'success' | 'error' | 'warning';
  message: string;
}

export type DesignTone = 'professional' | 'minimalist' | 'cyberpunk' | 'playful' | 'brutalist';

export interface Snapshot {
  id: string;
  timestamp: string;
  name: string;
  state: Omit<OmniState, 'logs' | 'snapshots'>;
}

export interface OmniState {
  projectName: string;
  metaTitle: string;
  blocks: Block[];
  selectedBlockId: string | null;
  globalCss: string;
  accentColor: string;
  fontFamily: string;
  designTone: DesignTone;
  borderRadius: string;
  spacingScale: number;
  shadowIntensity: number;
  logs: LogEntry[];
  snapshots: Snapshot[];
  googleFormUrl: string;
  canvasHeights: {
    mobile: number;
    tablet: number;
    desktop: number;
  };
}

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { geminiService } from './services/geminiService';
import { OmniState, LogEntry, Block } from './types';
import { Header } from './components/Header';
import { LeftSidebar } from './components/LeftSidebar';
import { RightSidebar } from './components/RightSidebar';
import { Terminal } from './components/Terminal';
import { BuildScreen } from './components/BuildScreen';
import { PreviewCanvas } from './components/PreviewCanvas';
import { generateIframeHtml } from './utils/iframeHelper';

const getInitialState = (): OmniState => ({
  projectName: "Trang Web Elementor",
  metaTitle: "Landing Page Architect",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#3b82f6",
  fontFamily: "Inter",
  designTone: 'professional',
  borderRadius: '0.75rem',
  spacingScale: 1.0,
  shadowIntensity: 0.1,
  logs: [],
  snapshots: [],
  googleFormUrl: "",
  canvasHeights: {
    mobile: 800,
    tablet: 1024,
    desktop: 2000
  }
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [isAddingModule, setIsAddingModule] = useState(false);
  const [newModuleQuery, setNewModuleQuery] = useState('');
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('preview');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [showHud, setShowHud] = useState(true);

  const addLog = useCallback((type: LogEntry['type'], message: string) => {
    const newLog: LogEntry = { id: Math.random().toString(36).substr(2, 9), timestamp: new Date().toLocaleTimeString(), type, message };
    setState(prev => ({ ...prev, logs: [newLog, ...prev.logs].slice(0, 50) }));
  }, []);

  const handleRegenerateImage = async (blockId: string, imgIndex: number, prompt: string, isPro: boolean = false) => {
    // @ts-ignore
    if (window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      addLog('warning', 'Bạn cần chọn API Key trả phí để tạo hình ảnh.');
      // @ts-ignore
      await window.aistudio.openSelectKey();
      return;
    }
    addLog('info', `Đang tạo ảnh AI: ${prompt.substring(0, 30)}...`);
    try {
      const imageUrl = await geminiService.generateAiImage(prompt, isPro);
      setState(prev => ({
        ...prev,
        blocks: prev.blocks.map(b => {
          if (b.id !== blockId) return b;
          const parser = new DOMParser();
          const doc = parser.parseFromString(b.html, 'text/html');
          const imgs = doc.querySelectorAll('img');
          if (imgs[imgIndex]) imgs[imgIndex].src = imageUrl;
          return { ...b, html: doc.body.innerHTML };
        })
      }));
      addLog('success', 'Ảnh đã sẵn sàng!');
      setPreviewKey(k => k + 1);
    } catch (e: any) { addLog('error', `Lỗi tạo ảnh: ${e.message}`); }
  };

  const autoInitializeImages = async (blocks: Block[]) => {
    for (const block of blocks) {
      const parser = new DOMParser();
      const doc = parser.parseFromString(block.html, 'text/html');
      const imgs = Array.from(doc.querySelectorAll('img'));
      for (let i = 0; i < imgs.length; i++) {
        const prompt = imgs[i].getAttribute('data-ai-prompt');
        if (prompt) await handleRegenerateImage(block.id, i, prompt, false);
      }
    }
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    try {
      const result = await geminiService.parseToBlocks(inputSource, state.designTone, inputSource.includes('<') ? inputSource : undefined);
      setState(prev => ({ ...prev, blocks: result.blocks, globalCss: result.globalCss, selectedBlockId: result.blocks[0]?.id || null }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);
      addLog('success', 'Đã xây dựng khung trang web.');
      autoInitializeImages(result.blocks);
    } catch (e: any) { addLog('error', e.message); } finally { setIsProcessing(false); }
  };

  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      const { type, blockId, newHtml, direction, imgIndex, prompt, height, device } = event.data;
      if (!type) return;
      switch (type) {
        case 'UPDATE_BLOCK_HTML':
          setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === blockId ? { ...b, html: newHtml } : b) }));
          break;
        case 'UPDATE_BLOCK_HEIGHT':
          setState(prev => ({
            ...prev,
            blocks: prev.blocks.map(b => {
              if (b.id !== blockId) return b;
              return {
                ...b,
                heights: { ...b.heights, [device]: height }
              };
            })
          }));
          addLog('info', `Đã lưu chiều cao ${height}px cho ${device}`);
          break;
        case 'MOVE_BLOCK':
          handleMoveBlock(state.blocks.findIndex(b => b.id === blockId), direction);
          break;
        case 'DELETE_BLOCK':
          if(confirm('Xóa Section này?')) setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== blockId) }));
          break;
        case 'SELECT_BLOCK':
          setState(prev => ({ ...prev, selectedBlockId: blockId }));
          break;
        case 'ADD_SECTION_PROMPT':
          setViewMode('edit');
          break;
        case 'REGENERATE_IMAGE':
          handleRegenerateImage(blockId, imgIndex, prompt, true);
          break;
      }
    };
    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, [state.blocks, addLog]);

  const handleMoveBlock = (idx: number, dir: 'up' | 'down') => {
    setState(prev => {
      const newBlocks = [...prev.blocks];
      const target = dir === 'up' ? idx - 1 : idx + 1;
      if (target < 0 || target >= newBlocks.length) return prev;
      [newBlocks[idx], newBlocks[target]] = [newBlocks[target], newBlocks[idx]];
      return { ...prev, blocks: newBlocks };
    });
    setPreviewKey(k => k + 1);
  };

  const handleAddModule = async () => {
    if (!newModuleQuery.trim()) return;
    setIsAddingModule(true);
    try {
      const context = state.blocks.map(b => b.html).join(' ');
      const newBlock = await geminiService.generateSingleBlock(newModuleQuery, state.designTone, context);
      setState(prev => ({ ...prev, blocks: [...prev.blocks, newBlock], selectedBlockId: newBlock.id }));
      setNewModuleQuery('');
      setViewMode('preview');
      setPreviewKey(k => k + 1);
      autoInitializeImages([newBlock]);
    } catch (e: any) { addLog('error', e.message); } finally { setIsAddingModule(false); }
  };

  const internalHtml = useMemo(() => generateIframeHtml(state, true, previewDevice), [state, previewKey, previewDevice]);

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <Header 
        projectName={state.projectName} isEditingTitle={false} setIsEditingTitle={() => {}} setProjectName={(name) => setState(prev => ({ ...prev, projectName: name }))}
        isSaved={isSaved} createSnapshot={() => {}} showTerminal={showTerminal} setShowTerminal={setShowTerminal} viewMode={viewMode} setViewMode={setViewMode}
        handleExport={() => {
           const finalHtml = generateIframeHtml(state, false, 'desktop');
           const blob = new Blob([finalHtml], { type: 'text/html' });
           const url = URL.createObjectURL(blob);
           const a = document.createElement('a');
           a.href = url; a.download = `${state.projectName}.html`; a.click();
        }}
      />
      <main className="flex-1 flex overflow-hidden">
        <LeftSidebar 
          sidebarTab="blocks" setSidebarTab={() => {}} blocks={state.blocks} selectedBlockId={state.selectedBlockId} setSelectedBlockId={(id) => setState(prev => ({ ...prev, selectedBlockId: id }))}
          setViewMode={setViewMode} moveBlock={handleMoveBlock} deleteBlock={(id) => setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== id) }))}
          syncingBlocks={new Set()} newModuleQuery={newModuleQuery} setNewModuleQuery={setNewModuleQuery} handleAddModule={handleAddModule} isAddingModule={isAddingModule}
          snapshots={state.snapshots} restoreSnapshot={() => {}} deleteSnapshot={() => {}} designTone={state.designTone} setDesignTone={(tone) => setState(prev => ({ ...prev, designTone: tone }))}
        />
        <section className="flex-1 flex flex-col bg-[#020617] relative">
          {(state.blocks.length === 0 || viewMode === 'edit') ? (
            <BuildScreen inputSource={inputSource} setInputSource={setInputSource} handleBuild={handleBuild} isProcessing={isProcessing} hasBlocks={state.blocks.length > 0} onCancel={() => setViewMode('preview')} />
          ) : (
            <PreviewCanvas 
              previewDevice={previewDevice} setPreviewDevice={setPreviewDevice} setViewMode={setViewMode} internalHtml={internalHtml} previewKey={previewKey}
              showHud={showHud} setShowHud={setShowHud} spacingScale={state.spacingScale} setSpacingScale={(s) => setState(prev => ({ ...prev, spacingScale: s }))}
              shadowIntensity={state.shadowIntensity} setShadowIntensity={(sh) => setState(prev => ({ ...prev, shadowIntensity: sh }))}
              canvasHeight={state.canvasHeights[previewDevice]}
              setCanvasHeight={(h) => setState(prev => ({...prev, canvasHeights: {...prev.canvasHeights, [previewDevice]: h}}))}
            />
          )}
        </section>
        <RightSidebar 
          accentColor={state.accentColor} setAccentColor={(c) => setState(prev => ({ ...prev, accentColor: c }))} fontFamily={state.fontFamily} setFontFamily={(f) => setState(prev => ({ ...prev, fontFamily: f }))}
          borderRadius={state.borderRadius} setBorderRadius={(r) => setState(prev => ({ ...prev, borderRadius: r }))} spacingScale={state.spacingScale} setSpacingScale={(s) => setState(prev => ({ ...prev, spacingScale: s }))}
          shadowIntensity={state.shadowIntensity} setShadowIntensity={(sh) => setState(prev => ({ ...prev, shadowIntensity: sh }))}
          googleFormUrl={state.googleFormUrl} setGoogleFormUrl={(u) => setState(prev => ({ ...prev, googleFormUrl: u }))} deployFormBlock={() => {}} handleReset={() => setState(getInitialState())}
        />
      </main>
      {showTerminal && <Terminal logs={state.logs} onClose={() => setShowTerminal(false)} />}
      <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-[100] flex gap-2">
         <button 
           // @ts-ignore
           onClick={() => window.aistudio.openSelectKey()}
           className="px-6 py-2.5 bg-slate-900/80 backdrop-blur-xl border border-blue-500/50 text-blue-400 text-[10px] font-black uppercase tracking-widest rounded-full shadow-2xl hover:bg-blue-500 hover:text-white transition-all"
         >
           Cài đặt Gemini AI Key
         </button>
      </div>
      {(isProcessing || isAddingModule) && <div className="absolute inset-0 bg-slate-950/90 z-[100] flex flex-col items-center justify-center">
        <div className="w-16 h-16 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mb-4"></div>
