import React from 'react';
import { Layers, ChevronUp, ChevronDown, Trash2, Plus, Sparkles, MousePointer2, Loader2 } from 'lucide-react';
import { Block, DesignTone, Snapshot } from '../types';

interface LeftSidebarProps {
  sidebarTab: 'blocks' | 'history';
  setSidebarTab: (tab: 'blocks' | 'history') => void;
  blocks: Block[];
  selectedBlockId: string | null;
  setSelectedBlockId: (id: string) => void;
  setViewMode: (mode: 'edit' | 'preview') => void;
  moveBlock: (idx: number, dir: 'up' | 'down') => void;
  deleteBlock: (id: string) => void;
  syncingBlocks: Set<string>;
  newModuleQuery: string;
  setNewModuleQuery: (val: string) => void;
  handleAddModule: () => void;
  isAddingModule: boolean;
  snapshots: Snapshot[];
  restoreSnapshot: (snap: Snapshot) => void;
  deleteSnapshot: (id: string) => void;
  designTone: DesignTone;
  setDesignTone: (tone: DesignTone) => void;
}

export const LeftSidebar: React.FC<LeftSidebarProps> = ({
  blocks, selectedBlockId, setSelectedBlockId, setViewMode,
  moveBlock, deleteBlock, newModuleQuery, setNewModuleQuery, handleAddModule, isAddingModule
}) => {
  return (
    <aside className="w-full lg:w-72 h-full bg-[#0b0f1a] border-r border-white/5 flex flex-col shrink-0 shadow-2xl">
      <div className="p-5 bg-[#131929] border-b border-white/5 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <Layers className="w-4 h-4 text-blue-400" />
          <span className="text-[11px] font-black uppercase tracking-widest text-slate-300">Cấu trúc trang</span>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-5 custom-scrollbar">
        <div className="space-y-2">
          {blocks.map((block, idx) => (
            <div 
              key={block.id} 
              onClick={() => { setSelectedBlockId(block.id); setViewMode('preview'); }}
              className={`group flex items-center gap-3 p-4 rounded-2xl cursor-pointer transition-all border ${selectedBlockId === block.id ? 'bg-blue-600/20 border-blue-500/40 text-white shadow-xl' : 'bg-transparent border-transparent hover:bg-white/5 text-slate-500'}`}
            >
              <MousePointer2 className={`w-3.5 h-3.5 ${selectedBlockId === block.id ? 'text-blue-400' : 'text-slate-700'}`} />
              <span className="text-[10px] font-black uppercase truncate flex-1 tracking-tight">{block.name}</span>
              <div className="flex items-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                <button onClick={(e) => { e.stopPropagation(); moveBlock(idx, 'up'); }} disabled={idx === 0} className="p-1.5 hover:text-white disabled:opacity-20"><ChevronUp className="w-4 h-4" /></button>
                <button onClick={(e) => { e.stopPropagation(); moveBlock(idx, 'down'); }} disabled={idx === blocks.length - 1} className="p-1.5 hover:text-white disabled:opacity-20"><ChevronDown className="w-4 h-4" /></button>
                <button onClick={(e) => { e.stopPropagation(); deleteBlock(block.id); }} className="p-1.5 hover:text-red-400"><Trash2 className="w-4 h-4" /></button>
              </div>
            </div>
          ))}
          {blocks.length === 0 && (
            <div className="text-[10px] text-slate-600 italic text-center py-20 border-2 border-dashed border-white/5 rounded-3xl bg-slate-900/20">
              Chưa có section nào.<br/>Nhập mô tả bên dưới để bắt đầu.
            </div>
          )}
        </div>

        <div className="mt-10 pt-8 border-t border-white/5 space-y-5">
           <div className="text-[10px] font-black text-slate-500 uppercase flex items-center gap-2 tracking-widest">
             <Sparkles className="w-3.5 h-3.5 text-blue-400" /> AI Widget Creator
           </div>
           <div className="relative">
             <textarea
               value={newModuleQuery}
               onChange={(e) => setNewModuleQuery(e.target.value)}
               placeholder="Ví dụ: 'Thêm bảng giá 3 cột chuyên nghiệp'..."
               className="w-full bg-slate-900 border border-white/10 rounded-2xl p-5 text-xs font-medium text-white outline-none focus:border-blue-500/50 resize-none h-32 placeholder:text-slate-700 transition-all focus:ring-2 focus:ring-blue-500/10"
             />
           </div>
           <button 
             onClick={handleAddModule}
             disabled={isAddingModule || !newModuleQuery.trim()}
             className="w-full py-4 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shadow-lg shadow-blue-600/20 flex items-center justify-center gap-3 disabled:opacity-50 disabled:bg-slate-800"
           >
             {isAddingModule ? <Loader2 className="w-4 h-4 animate-spin" /> : <Plus className="w-4 h-4" />}
             Insert Widget
           </button>
        </div>
      </div>

      <div className="p-6 bg-slate-950/50 border-t border-white/5">
        <div className="text-[8px] font-black text-slate-700 uppercase tracking-[0.3em] mb-1">Omni Engine v2.5</div>
        <div className="text-[8px] font-bold text-slate-800 uppercase">Mobile-Optimized Interface</div>
      </div>
    </aside>
  );
};

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { geminiService } from './services/geminiService';
import { OmniState, LogEntry, Block } from './types';
import { Header } from './components/Header';
import { LeftSidebar } from './components/LeftSidebar';
import { RightSidebar } from './components/RightSidebar';
import { Terminal } from './components/Terminal';
import { BuildScreen } from './components/BuildScreen';
import { PreviewCanvas } from './components/PreviewCanvas';
import { generateIframeHtml } from './utils/iframeHelper';
import { Menu, X, Sparkles } from 'lucide-react';

const getInitialState = (): OmniState => ({
  projectName: "Dự án Thiết kế Mới",
  metaTitle: "Landing Page Architect",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#3b82f6",
  fontFamily: "Inter",
  designTone: 'professional',
  borderRadius: '0.75rem',
  spacingScale: 1.0,
  shadowIntensity: 0.1,
  logs: [],
  snapshots: [],
  googleFormUrl: "",
  canvasHeights: {
    mobile: 800,
    tablet: 1024,
    desktop: 1800
  }
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [isAddingModule, setIsAddingModule] = useState(false);
  const [newModuleQuery, setNewModuleQuery] = useState('');
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('preview');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [showHud, setShowHud] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const addLog = useCallback((type: LogEntry['type'], message: string) => {
    const newLog: LogEntry = { id: Math.random().toString(36).substr(2, 9), timestamp: new Date().toLocaleTimeString(), type, message };
    setState(prev => ({ ...prev, logs: [newLog, ...prev.logs].slice(0, 50) }));
  }, []);

  const updateBlockImage = (blockId: string, imgIndex: number, newUrl: string) => {
    setState(prev => ({
      ...prev,
      blocks: prev.blocks.map(b => {
        if (b.id !== blockId) return b;
        const parser = new DOMParser();
        const doc = parser.parseFromString(b.html, 'text/html');
        const imgs = doc.querySelectorAll('img');
        if (imgs[imgIndex]) {
          imgs[imgIndex].src = newUrl;
          imgs[imgIndex].classList.remove('is-generating');
        }
        return { ...b, html: doc.body.innerHTML };
      })
    }));
    setPreviewKey(k => k + 1);
  };

  const handleRegenerateImage = async (blockId: string, imgIndex: number, prompt: string, isPro: boolean = false) => {
    // @ts-ignore
    if (isPro && window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      addLog('warning', 'Vui lòng chọn API Key để sử dụng tính năng AI.');
      // @ts-ignore
      await window.aistudio.openSelectKey();
      return;
    }
    addLog('info', `AI đang xử lý hình ảnh #${imgIndex + 1}...`);
    try {
      const imageUrl = await geminiService.generateAiImage(prompt, isPro);
      updateBlockImage(blockId, imgIndex, imageUrl);
      addLog('success', 'Đã cập nhật ảnh AI.');
    } catch (e: any) { addLog('error', `Lỗi AI: ${e.message}`); }
  };

  const handleFileUpload = (blockId: string, imgIndex: number) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e: any) => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (event: any) => {
        updateBlockImage(blockId, imgIndex, event.target.result);
        addLog('success', `Đã upload: ${file.name}`);
      };
      reader.readAsDataURL(file);
    };
    input.click();
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    try {
      const result = await geminiService.parseToBlocks(inputSource, state.designTone, inputSource.includes('<') ? inputSource : undefined);
      setState(prev => ({ ...prev, blocks: result.blocks, globalCss: result.globalCss, selectedBlockId: result.blocks[0]?.id || null }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);
      addLog('success', 'Giao diện đã được xây dựng.');

      result.blocks.forEach(block => {
        const parser = new DOMParser();
        const doc = parser.parseFromString(block.html, 'text/html');
        doc.querySelectorAll('img').forEach((img, idx) => {
          const prompt = img.getAttribute('data-ai-prompt');
          if (prompt) handleRegenerateImage(block.id, idx, prompt, false);
        });
      });
    } catch (e: any) { addLog('error', e.message); } finally { setIsProcessing(false); }
  };

  const deployFormBlock = async () => {
    if (!state.googleFormUrl.trim()) {
      addLog('warning', 'Vui lòng nhập Link Google Form trước khi đồng bộ.');
      return;
    }
    setIsAddingModule(true);
    addLog('info', 'Đang thiết kế Section Lead Capture (Mobile Optimized)...');
    try {
      // Prompt được nâng cấp để giải quyết vấn đề double-scroll trên mobile
      const prompt = `Create a professional Lead Capture section for this Google Form: ${state.googleFormUrl}. 
      CRITICAL FOR MOBILE UX: 
      1. On screens smaller than 768px, display a 'Click to Fill' overlay over the form. 
      2. When clicked, use JavaScript (inline) to make the form container 'fixed top-0 left-0 w-full h-full z-[9999]' so it fills the screen and eliminates double scrollbars. 
      3. Add a prominent 'Close Form' button at the top/corner of this fixed view to allow users to return to the page. 
      4. Ensure a clean, professional Tailwind UI for both desktop and mobile states.`;

      const context = state.blocks.map(b => b.html).join(' ');
      const newBlock = await geminiService.generateSingleBlock(prompt, state.designTone, context);
      setState(prev => ({ ...prev, blocks: [...prev.blocks, newBlock], selectedBlockId: newBlock.id }));
      setPreviewKey(k => k + 1);
      addLog('success', 'Đã thêm Form Block thông minh.');
    } catch (e: any) { addLog('error', `Lỗi khi đồng bộ Form: ${e.message}`); } finally { setIsAddingModule(false); }
  };

  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      const { type, blockId, newHtml, direction, imgIndex, prompt, height, device } = event.data;
      if (!type) return;
      switch (type) {
        case 'UPDATE_BLOCK_HTML':
          setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === blockId ? { ...b, html: newHtml } : b) }));
          break;
        case 'UPDATE_BLOCK_HEIGHT':
          setState(prev => ({
            ...prev,
            blocks: prev.blocks.map(b => b.id === blockId ? { ...b, heights: { ...b.heights, [device]: height } } : b)
          }));
          break;
        case 'MOVE_BLOCK':
          handleMoveBlock(state.blocks.findIndex(b => b.id === blockId), direction);
          break;
        case 'DELETE_BLOCK':
          if(confirm('Xóa Section này?')) setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== blockId) }));
          break;
        case 'SELECT_BLOCK':
          setState(prev => ({ ...prev, selectedBlockId: blockId }));
          break;
        case 'ADD_SECTION_PROMPT':
          setViewMode('edit');
          break;
        case 'REGENERATE_IMAGE':
          handleRegenerateImage(blockId, imgIndex, prompt, true);
          break;
        case 'UPLOAD_IMAGE':
          handleFileUpload(blockId, imgIndex);
          break;
      }
    };
    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, [state.blocks, addLog]);

  const handleMoveBlock = (idx: number, dir: 'up' | 'down') => {
    setState(prev => {
      const newBlocks = [...prev.blocks];
      const target = dir === 'up' ? idx - 1 : idx + 1;
      if (target < 0 || target >= newBlocks.length) return prev;
      [newBlocks[idx], newBlocks[target]] = [newBlocks[target], newBlocks[idx]];
      return { ...prev, blocks: newBlocks };
    });
    setPreviewKey(k => k + 1);
  };

  const handleAddModule = async () => {
    if (!newModuleQuery.trim()) return;
    setIsAddingModule(true);
    setIsSidebarOpen(false); 
    try {
      const context = state.blocks.map(b => b.html).join(' ');
      const newBlock = await geminiService.generateSingleBlock(newModuleQuery, state.designTone, context);
      setState(prev => ({ ...prev, blocks: [...prev.blocks, newBlock], selectedBlockId: newBlock.id }));
      setNewModuleQuery('');
      setViewMode('preview');
      setPreviewKey(k => k + 1);

      const parser = new DOMParser();
      const doc = parser.parseFromString(newBlock.html, 'text/html');
      doc.querySelectorAll('img').forEach((img, idx) => {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) handleRegenerateImage(newBlock.id, idx, prompt, false);
      });
    } catch (e: any) { addLog('error', e.message); } finally { setIsAddingModule(false); }
  };

  const internalHtml = useMemo(() => generateIframeHtml(state, true, previewDevice), [state, previewKey, previewDevice]);

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <Header 
        projectName={state.projectName} isEditingTitle={false} setIsEditingTitle={() => {}} setProjectName={(name) => setState(prev => ({ ...prev, projectName: name }))}
        isSaved={isSaved} createSnapshot={() => {}} showTerminal={showTerminal} setShowTerminal={setShowTerminal} viewMode={viewMode} setViewMode={setViewMode}
        handleExport={() => {
           const finalHtml = generateIframeHtml(state, false, 'desktop');
           const blob = new Blob([finalHtml], { type: 'text/html' });
           const url = URL.createObjectURL(blob);
           const a = document.createElement('a');
           a.href = url; a.download = `${state.projectName}.html`; a.click();
        }}
      />

      <button 
        onClick={() => setIsSidebarOpen(!isSidebarOpen)}
        className="lg:hidden fixed bottom-6 left-6 z-[110] w-14 h-14 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center active:scale-90 transition-transform"
      >
        {isSidebarOpen ? <X /> : <Menu />}
      </button>

      <main className="flex-1 flex overflow-hidden relative">
        <div className={`
          fixed inset-y-0 left-0 z-[100] w-72 lg:relative lg:translate-x-0 transition-transform duration-300 ease-in-out
          ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
        `}>
          <LeftSidebar 
            sidebarTab="blocks" setSidebarTab={() => {}} blocks={state.blocks} selectedBlockId={state.selectedBlockId} setSelectedBlockId={(id) => setState(prev => ({ ...prev, selectedBlockId: id }))}
            setViewMode={setViewMode} moveBlock={handleMoveBlock} deleteBlock={(id) => setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== id) }))}
            syncingBlocks={new Set()} newModuleQuery={newModuleQuery} setNewModuleQuery={setNewModuleQuery} handleAddModule={handleAddModule} isAddingModule={isAddingModule}
            snapshots={state.snapshots} restoreSnapshot={() => {}} deleteSnapshot={() => {}} designTone={state.designTone} setDesignTone={(tone) => setState(prev => ({ ...prev, designTone: tone }))}
          />
        </div>

        {isSidebarOpen && <div onClick={() => setIsSidebarOpen(false)} className="lg:hidden fixed inset-0 bg-black/60 backdrop-blur-sm z-[90]" />}

        <section className="flex-1 flex flex-col bg-[#020617] relative">
          {(state.blocks.length === 0 || viewMode === 'edit') ? (
            <BuildScreen inputSource={inputSource} setInputSource={setInputSource} handleBuild={handleBuild} isProcessing={isProcessing} hasBlocks={state.blocks.length > 0} onCancel={() => setViewMode('preview')} />
          ) : (
            <PreviewCanvas 
              previewDevice={previewDevice} setPreviewDevice={setPreviewDevice} setViewMode={setViewMode} internalHtml={internalHtml} previewKey={previewKey}
              showHud={showHud} setShowHud={setShowHud} spacingScale={state.spacingScale} setSpacingScale={(s) => setState(prev => ({ ...prev, spacingScale: s }))}
              shadowIntensity={state.shadowIntensity} setShadowIntensity={(sh) => setState(prev => ({ ...prev, shadowIntensity: sh }))}
              canvasHeight={state.canvasHeights[previewDevice]}
              setCanvasHeight={(h) => setState(prev => ({...prev, canvasHeights: {...prev.canvasHeights, [previewDevice]: h}}))}
            />
          )}
        </section>

        <div className="hidden lg:block">
          <RightSidebar 
            accentColor={state.accentColor} setAccentColor={(c) => setState(prev => ({ ...prev, accentColor: c }))} fontFamily={state.fontFamily} setFontFamily={(f) => setState(prev => ({ ...prev, fontFamily: f }))}
            borderRadius={state.borderRadius} setBorderRadius={(r) => setState(prev => ({ ...prev, borderRadius: r }))} spacingScale={state.spacingScale} setSpacingScale={(s) => setState(prev => ({ ...prev, spacingScale: s }))}
            shadowIntensity={state.shadowIntensity} setShadowIntensity={(sh) => setState(prev => ({ ...prev, shadowIntensity: sh }))}
            googleFormUrl={state.googleFormUrl} setGoogleFormUrl={(u) => setState(prev => ({ ...prev, googleFormUrl: u }))} deployFormBlock={deployFormBlock} handleReset={() => setState(getInitialState())}
          />
        </div>
      </main>

      {showTerminal && <Terminal logs={state.logs} onClose={() => setShowTerminal(false)} />}

      <div className="fixed bottom-6 right-6 lg:left-1/2 lg:-translate-x-1/2 z-[100] flex gap-2">
         <button 
           // @ts-ignore
           onClick={() => window.aistudio.openSelectKey()}
           className="px-4 lg:px-6 py-2.5 bg-slate-900/80 backdrop-blur-xl border border-blue-500/50 text-blue-400 text-[9px] lg:text-[10px] font-black uppercase tracking-widest rounded-full shadow-2xl hover:bg-blue-500 hover:text-white transition-all flex items-center gap-2"
         >
           <Sparkles className="w-3 h-3" /> Cài đặt Gemini AI
         </button>
      </div>

      {(isProcessing || isAddingModule) && (
        <div className="fixed inset-0 bg-slate-950/90 z-[200] flex flex-col items-center justify-center p-6 text-center">
          <div className="w-16 h-16 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mb-4"></div>
          <div className="text-white font-black uppercase tracking-widest text-sm">Omni Engine Active</div>
          <div className="text-slate-400 text-[10px] mt-2 animate-pulse uppercase tracking-[0.2em]">Hệ thống AI đang xử lý yêu cầu...</div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { geminiService } from './services/geminiService';
import { OmniState, LogEntry, Block } from './types';
import { Header } from './components/Header';
import { LeftSidebar } from './components/LeftSidebar';
import { RightSidebar } from './components/RightSidebar';
import { Terminal } from './components/Terminal';
import { BuildScreen } from './components/BuildScreen';
import { PreviewCanvas } from './components/PreviewCanvas';
import { generateIframeHtml } from './utils/iframeHelper';
import { Menu, X, Sparkles } from 'lucide-react';

const getInitialState = (): OmniState => ({
  projectName: "Dự án Thiết kế Mới",
  metaTitle: "Landing Page Architect",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#3b82f6",
  fontFamily: "Inter",
  designTone: 'professional',
  borderRadius: '0.75rem',
  spacingScale: 1.0,
  shadowIntensity: 0.1,
  logs: [],
  snapshots: [],
  googleFormUrl: "",
  canvasHeights: {
    mobile: 800,
    tablet: 1024,
    desktop: 1800
  }
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [isAddingModule, setIsAddingModule] = useState(false);
  const [newModuleQuery, setNewModuleQuery] = useState('');
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('preview');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [showHud, setShowHud] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const addLog = useCallback((type: LogEntry['type'], message: string) => {
    const newLog: LogEntry = { id: Math.random().toString(36).substr(2, 9), timestamp: new Date().toLocaleTimeString(), type, message };
    setState(prev => ({ ...prev, logs: [newLog, ...prev.logs].slice(0, 50) }));
  }, []);

  const updateBlockImage = (blockId: string, imgIndex: number, newUrl: string) => {
    setState(prev => ({
      ...prev,
      blocks: prev.blocks.map(b => {
        if (b.id !== blockId) return b;
        const parser = new DOMParser();
        const doc = parser.parseFromString(b.html, 'text/html');
        const imgs = doc.querySelectorAll('img');
        if (imgs[imgIndex]) {
          imgs[imgIndex].src = newUrl;
          imgs[imgIndex].classList.remove('is-generating');
        }
        return { ...b, html: doc.body.innerHTML };
      })
    }));
    setPreviewKey(k => k + 1);
  };

  const handleRegenerateImage = async (blockId: string, imgIndex: number, prompt: string, isPro: boolean = false) => {
    // @ts-ignore
    if (isPro && window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      addLog('warning', 'Vui lòng chọn API Key để sử dụng tính năng AI.');
      // @ts-ignore
      await window.aistudio.openSelectKey();
      return;
    }
    addLog('info', `AI đang xử lý hình ảnh #${imgIndex + 1}...`);
    try {
      const imageUrl = await geminiService.generateAiImage(prompt, isPro);
      updateBlockImage(blockId, imgIndex, imageUrl);
      addLog('success', 'Đã cập nhật ảnh AI.');
    } catch (e: any) { addLog('error', `Lỗi AI: ${e.message}`); }
  };

  const handleFileUpload = (blockId: string, imgIndex: number) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e: any) => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (event: any) => {
        updateBlockImage(blockId, imgIndex, event.target.result);
        addLog('success', `Đã upload: ${file.name}`);
      };
      reader.readAsDataURL(file);
    };
    input.click();
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    try {
      const result = await geminiService.parseToBlocks(inputSource, state.designTone, inputSource.includes('<') ? inputSource : undefined);
      setState(prev => ({ ...prev, blocks: result.blocks, globalCss: result.globalCss, selectedBlockId: result.blocks[0]?.id || null }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);
      addLog('success', 'Giao diện đã được xây dựng.');

      result.blocks.forEach(block => {
        const parser = new DOMParser();
        const doc = parser.parseFromString(block.html, 'text/html');
        doc.querySelectorAll('img').forEach((img, idx) => {
          const prompt = img.getAttribute('data-ai-prompt');
          if (prompt) handleRegenerateImage(block.id, idx, prompt, false);
        });
      });
    } catch (e: any) { addLog('error', e.message); } finally { setIsProcessing(false); }
  };

  const deployFormBlock = async () => {
    if (!state.googleFormUrl.trim()) {
      addLog('warning', 'Vui lòng nhập Link Google Form trước khi đồng bộ.');
      return;
    }
    setIsAddingModule(true);
    addLog('info', 'Đang thiết kế Section Lead Capture thông minh cho di động...');
    try {
      // Prompt chi tiết để giải quyết bài toán "Lớp phủ nhấp để mở Form toàn màn hình"
      const prompt = `Create a professional Lead Capture section using this Google Form URL: ${state.googleFormUrl}.

      MOBILE OPTIMIZATION REQUIREMENTS:
      1. Design an overlay that covers the form ONLY on mobile devices. 
      2. The overlay must be visually appealing with a button or text saying 'NHẤP ĐỂ BẮT ĐẦU ĐIỀN FORM'.
      3. Implement an INLINE JAVASCRIPT function: When the overlay or container is clicked, toggle a class (e.g., 'is-fullscreen') on the form wrapper.
      4. The 'is-fullscreen' class must use Tailwind classes to make the form wrapper: fixed, top-0, left-0, w-screen, h-screen, z-[99999], bg-white. This eliminates double scrolling.
      5. Include a 'Đóng Form' or 'Hoàn tất' button visible only in fullscreen mode to return to the original page layout.
      6. For Desktop: Display the form normally as part of the page flow.
      7. Use modern Tailwind UI with nice typography and shadows.`;

      const context = state.blocks.map(b => b.html).join(' ');
      const newBlock = await geminiService.generateSingleBlock(prompt, state.designTone, context);
      setState(prev => ({ ...prev, blocks: [...prev.blocks, newBlock], selectedBlockId: newBlock.id }));
      setPreviewKey(k => k + 1);
      addLog('success', 'Đã thêm Form Block với cơ chế "Click-to-Fill" toàn màn hình cho di động.');
    } catch (e: any) { addLog('error', `Lỗi khi đồng bộ Form: ${e.message}`); } finally { setIsAddingModule(false); }
  };

  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      const { type, blockId, newHtml, direction, imgIndex, prompt, height, device } = event.data;
      if (!type) return;
      switch (type) {
        case 'UPDATE_BLOCK_HTML':
          setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === blockId ? { ...b, html: newHtml } : b) }));
          break;
        case 'UPDATE_BLOCK_HEIGHT':
          setState(prev => ({
            ...prev,
            blocks: prev.blocks.map(b => b.id === blockId ? { ...b, heights: { ...b.heights, [device]: height } } : b)
          }));
          break;
        case 'MOVE_BLOCK':
          handleMoveBlock(state.blocks.findIndex(b => b.id === blockId), direction);
          break;
        case 'DELETE_BLOCK':
          if(confirm('Xóa Section này?')) setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== blockId) }));
          break;
        case 'SELECT_BLOCK':
          setState(prev => ({ ...prev, selectedBlockId: blockId }));
          break;
        case 'ADD_SECTION_PROMPT':
          setViewMode('edit');
          break;
        case 'REGENERATE_IMAGE':
          handleRegenerateImage(blockId, imgIndex, prompt, true);
          break;
        case 'UPLOAD_IMAGE':
          handleFileUpload(blockId, imgIndex);
          break;
      }
    };
    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, [state.blocks, addLog]);

  const handleMoveBlock = (idx: number, dir: 'up' | 'down') => {
    setState(prev => {
      const newBlocks = [...prev.blocks];
      const target = dir === 'up' ? idx - 1 : idx + 1;
      if (target < 0 || target >= newBlocks.length) return prev;
      [newBlocks[idx], newBlocks[target]] = [newBlocks[target], newBlocks[idx]];
      return { ...prev, blocks: newBlocks };
    });
    setPreviewKey(k => k + 1);
  };

  const handleAddModule = async () => {
    if (!newModuleQuery.trim()) return;
    setIsAddingModule(true);
    setIsSidebarOpen(false); 
    try {
      const context = state.blocks.map(b => b.html).join(' ');
      const newBlock = await geminiService.generateSingleBlock(newModuleQuery, state.designTone, context);
      setState(prev => ({ ...prev, blocks: [...prev.blocks, newBlock], selectedBlockId: newBlock.id }));
      setNewModuleQuery('');
      setViewMode('preview');
      setPreviewKey(k => k + 1);

      const parser = new DOMParser();
      const doc = parser.parseFromString(newBlock.html, 'text/html');
      doc.querySelectorAll('img').forEach((img, idx) => {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) handleRegenerateImage(newBlock.id, idx, prompt, false);
      });
    } catch (e: any) { addLog('error', e.message); } finally { setIsAddingModule(false); }
  };

  const internalHtml = useMemo(() => generateIframeHtml(state, true, previewDevice), [state, previewKey, previewDevice]);

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <Header 
        projectName={state.projectName} isEditingTitle={false} setIsEditingTitle={() => {}} setProjectName={(name) => setState(prev => ({ ...prev, projectName: name }))}
        isSaved={isSaved} createSnapshot={() => {}} showTerminal={showTerminal} setShowTerminal={setShowTerminal} viewMode={viewMode} setViewMode={setViewMode}
        handleExport={() => {
           const finalHtml = generateIframeHtml(state, false, 'desktop');
           const blob = new Blob([finalHtml], { type: 'text/html' });
           const url = URL.createObjectURL(blob);
           const a = document.createElement('a');
           a.href = url; a.download = `${state.projectName}.html`; a.click();
        }}
      />

      <button 
        onClick={() => setIsSidebarOpen(!isSidebarOpen)}
        className="lg:hidden fixed bottom-6 left-6 z-[110] w-14 h-14 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center active:scale-90 transition-transform"
      >
        {isSidebarOpen ? <X /> : <Menu />}
      </button>

      <main className="flex-1 flex overflow-hidden relative">
        <div className={`
          fixed inset-y-0 left-0 z-[100] w-72 lg:relative lg:translate-x-0 transition-transform duration-300 ease-in-out
          ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
        `}>
          <LeftSidebar 
            sidebarTab="blocks" setSidebarTab={() => {}} blocks={state.blocks} selectedBlockId={state.selectedBlockId} setSelectedBlockId={(id) => setState(prev => ({ ...prev, selectedBlockId: id }))}
            setViewMode={setViewMode} moveBlock={handleMoveBlock} deleteBlock={(id) => setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== id) }))}
            syncingBlocks={new Set()} newModuleQuery={newModuleQuery} setNewModuleQuery={setNewModuleQuery} handleAddModule={handleAddModule} isAddingModule={isAddingModule}
            snapshots={state.snapshots} restoreSnapshot={() => {}} deleteSnapshot={() => {}} designTone={state.designTone} setDesignTone={(tone) => setState(prev => ({ ...prev, designTone: tone }))}
          />
        </div>

        {isSidebarOpen && <div onClick={() => setIsSidebarOpen(false)} className="lg:hidden fixed inset-0 bg-black/60 backdrop-blur-sm z-[90]" />}

        <section className="flex-1 flex flex-col bg-[#020617] relative">
          {(state.blocks.length === 0 || viewMode === 'edit') ? (
            <BuildScreen inputSource={inputSource} setInputSource={setInputSource} handleBuild={handleBuild} isProcessing={isProcessing} hasBlocks={state.blocks.length > 0} onCancel={() => setViewMode('preview')} />
          ) : (
            <PreviewCanvas 
              previewDevice={previewDevice} setPreviewDevice={setPreviewDevice} setViewMode={setViewMode} internalHtml={internalHtml} previewKey={previewKey}
              showHud={showHud} setShowHud={setShowHud} spacingScale={state.spacingScale} setSpacingScale={(s) => setState(prev => ({ ...prev, spacingScale: s }))}
              shadowIntensity={state.shadowIntensity} setShadowIntensity={(sh) => setState(prev => ({ ...prev, shadowIntensity: sh }))}
              canvasHeight={state.canvasHeights[previewDevice]}
              setCanvasHeight={(h) => setState(prev => ({...prev, canvasHeights: {...prev.canvasHeights, [previewDevice]: h}}))}
            />
          )}
        </section>

        <div className="hidden lg:block">
          <RightSidebar 
            accentColor={state.accentColor} setAccentColor={(c) => setState(prev => ({ ...prev, accentColor: c }))} fontFamily={state.fontFamily} setFontFamily={(f) => setState(prev => ({ ...prev, fontFamily: f }))}
            borderRadius={state.borderRadius} setBorderRadius={(r) => setState(prev => ({ ...prev, borderRadius: r }))} spacingScale={state.spacingScale} setSpacingScale={(s) => setState(prev => ({ ...prev, spacingScale: s }))}
            shadowIntensity={state.shadowIntensity} setShadowIntensity={(sh) => setState(prev => ({ ...prev, shadowIntensity: sh }))}
            googleFormUrl={state.googleFormUrl} setGoogleFormUrl={(u) => setState(prev => ({ ...prev, googleFormUrl: u }))} deployFormBlock={deployFormBlock} handleReset={() => setState(getInitialState())}
          />
        </div>
      </main>

      {showTerminal && <Terminal logs={state.logs} onClose={() => setShowTerminal(false)} />}

      <div className="fixed bottom-6 right-6 lg:left-1/2 lg:-translate-x-1/2 z-[100] flex gap-2">
         <button 
           // @ts-ignore
           onClick={() => window.aistudio.openSelectKey()}
           className="px-4 lg:px-6 py-2.5 bg-slate-900/80 backdrop-blur-xl border border-blue-500/50 text-blue-400 text-[9px] lg:text-[10px] font-black uppercase tracking-widest rounded-full shadow-2xl hover:bg-blue-500 hover:text-white transition-all flex items-center gap-2"
         >
           <Sparkles className="w-3 h-3" /> Cài đặt Gemini AI
         </button>
      </div>

      {(isProcessing || isAddingModule) && (
        <div className="fixed inset-0 bg-slate-950/90 z-[200] flex flex-col items-center justify-center p-6 text-center">
          <div className="w-16 h-16 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mb-4"></div>
          <div className="text-white font-black uppercase tracking-widest text-sm">Omni Engine Active</div>
          <div className="text-slate-400 text-[10px] mt-2 animate-pulse uppercase tracking-[0.2em]">Hệ thống AI đang xử lý yêu cầu...</div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { geminiService } from './services/geminiService';
import { OmniState, LogEntry, Block } from './types';
import { Header } from './components/Header';
import { LeftSidebar } from './components/LeftSidebar';
import { RightSidebar } from './components/RightSidebar';
import { Terminal } from './components/Terminal';
import { BuildScreen } from './components/BuildScreen';
import { PreviewCanvas } from './components/PreviewCanvas';
import { generateIframeHtml } from './utils/iframeHelper';
import { Menu, X, Sparkles } from 'lucide-react';

const getInitialState = (): OmniState => ({
  projectName: "Dự án Thiết kế Mới",
  metaTitle: "Landing Page Architect",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#3b82f6",
  fontFamily: "Inter",
  designTone: 'professional',
  borderRadius: '0.75rem',
  spacingScale: 1.0,
  shadowIntensity: 0.1,
  logs: [],
  snapshots: [],
  googleFormUrl: "",
  canvasHeights: {
    mobile: 800,
    tablet: 1024,
    desktop: 1800
  }
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [isAddingModule, setIsAddingModule] = useState(false);
  const [newModuleQuery, setNewModuleQuery] = useState('');
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('preview');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [showHud, setShowHud] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const addLog = useCallback((type: LogEntry['type'], message: string) => {
    const newLog: LogEntry = { id: Math.random().toString(36).substr(2, 9), timestamp: new Date().toLocaleTimeString(), type, message };
    setState(prev => ({ ...prev, logs: [newLog, ...prev.logs].slice(0, 50) }));
  }, []);

  const updateBlockImage = (blockId: string, imgIndex: number, newUrl: string) => {
    setState(prev => ({
      ...prev,
      blocks: prev.blocks.map(b => {
        if (b.id !== blockId) return b;
        const parser = new DOMParser();
        const doc = parser.parseFromString(b.html, 'text/html');
        const imgs = doc.querySelectorAll('img');
        if (imgs[imgIndex]) {
          imgs[imgIndex].src = newUrl;
          imgs[imgIndex].classList.remove('is-generating');
        }
        return { ...b, html: doc.body.innerHTML };
      })
    }));
    setPreviewKey(k => k + 1);
  };

  const handleRegenerateImage = async (blockId: string, imgIndex: number, prompt: string, isPro: boolean = false) => {
    // @ts-ignore
    if (isPro && window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      addLog('warning', 'Vui lòng chọn API Key để sử dụng tính năng AI.');
      // @ts-ignore
      await window.aistudio.openSelectKey();
      return;
    }
    addLog('info', `AI đang xử lý hình ảnh #${imgIndex + 1}...`);
    try {
      const imageUrl = await geminiService.generateAiImage(prompt, isPro);
      updateBlockImage(blockId, imgIndex, imageUrl);
      addLog('success', 'Đã cập nhật ảnh AI.');
    } catch (e: any) { addLog('error', `Lỗi AI: ${e.message}`); }
  };

  const handleFileUpload = (blockId: string, imgIndex: number) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e: any) => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (event: any) => {
        updateBlockImage(blockId, imgIndex, event.target.result);
        addLog('success', `Đã upload: ${file.name}`);
      };
      reader.readAsDataURL(file);
    };
    input.click();
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    try {
      const result = await geminiService.parseToBlocks(inputSource, state.designTone, inputSource.includes('<') ? inputSource : undefined);
      setState(prev => ({ ...prev, blocks: result.blocks, globalCss: result.globalCss, selectedBlockId: result.blocks[0]?.id || null }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);
      addLog('success', 'Giao diện đã được xây dựng.');

      result.blocks.forEach(block => {
        const parser = new DOMParser();
        const doc = parser.parseFromString(block.html, 'text/html');
        doc.querySelectorAll('img').forEach((img, idx) => {
          const prompt = img.getAttribute('data-ai-prompt');
          if (prompt) handleRegenerateImage(block.id, idx, prompt, false);
        });
      });
    } catch (e: any) { addLog('error', e.message); } finally { setIsProcessing(false); }
  };

  const deployFormBlock = async () => {
    if (!state.googleFormUrl.trim()) {
      addLog('warning', 'Vui lòng nhập Link Google Form trước khi đồng bộ.');
      return;
    }
    setIsAddingModule(true);
    addLog('info', 'Đang thiết kế Section Lead Capture cảm ứng toàn màn hình...');
    try {
      // Prompt được thiết kế để tạo trải nghiệm chạm là mở ngay lập tức, không dùng overlay văn bản
      const prompt = `Create a professional Lead Capture section for this Google Form: ${state.googleFormUrl}.

      MOBILE UX ENHANCEMENT (Tap-to-Focus):
      1. On Mobile: The form container must act as a touch-trigger. DO NOT use visible text overlays or labels like 'Click here'. The form should look normal.
      2. When a user taps ANYWHERE on the form section on a mobile device, it must immediately transition to a 'Fixed Fullscreen Mode'.
      3. Fullscreen Mode CSS: The container becomes 'fixed top-0 left-0 w-full h-full z-[99999] bg-white'. This ensures the user only scrolls the form, NOT the main page.
      4. Close Mechanism: In fullscreen mode, add a floating 'X' or 'Đóng' button in the top-right corner using JavaScript to remove the fullscreen class.
      5. Implementation: Use a wrapper div with an inline onclick handler that detects mobile screens. Use Tailwind for all styling.
      6. For Desktop: The form should be embedded naturally within the page flow without any special triggers.`;

      const context = state.blocks.map(b => b.html).join(' ');
      const newBlock = await geminiService.generateSingleBlock(prompt, state.designTone, context);
      setState(prev => ({ ...prev, blocks: [...prev.blocks, newBlock], selectedBlockId: newBlock.id }));
      setPreviewKey(k => k + 1);
      addLog('success', 'Đã thêm Form Block thông minh: Chạm để nhập liệu toàn màn hình trên di động.');
    } catch (e: any) { addLog('error', `Lỗi khi đồng bộ Form: ${e.message}`); } finally { setIsAddingModule(false); }
  };

  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      const { type, blockId, newHtml, direction, imgIndex, prompt, height, device } = event.data;
      if (!type) return;
      switch (type) {
        case 'UPDATE_BLOCK_HTML':
          setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === blockId ? { ...b, html: newHtml } : b) }));
          break;
        case 'UPDATE_BLOCK_HEIGHT':
          setState(prev => ({
            ...prev,
            blocks: prev.blocks.map(b => b.id === blockId ? { ...b, heights: { ...b.heights, [device]: height } } : b)
          }));
          break;
        case 'MOVE_BLOCK':
          handleMoveBlock(state.blocks.findIndex(b => b.id === blockId), direction);
          break;
        case 'DELETE_BLOCK':
          if(confirm('Xóa Section này?')) setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== blockId) }));
          break;
        case 'SELECT_BLOCK':
          setState(prev => ({ ...prev, selectedBlockId: blockId }));
          break;
        case 'ADD_SECTION_PROMPT':
          setViewMode('edit');
          break;
        case 'REGENERATE_IMAGE':
          handleRegenerateImage(blockId, imgIndex, prompt, true);
          break;
        case 'UPLOAD_IMAGE':
          handleFileUpload(blockId, imgIndex);
          break;
      }
    };
    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, [state.blocks, addLog]);

  const handleMoveBlock = (idx: number, dir: 'up' | 'down') => {
    setState(prev => {
      const newBlocks = [...prev.blocks];
      const target = dir === 'up' ? idx - 1 : idx + 1;
      if (target < 0 || target >= newBlocks.length) return prev;
      [newBlocks[idx], newBlocks[target]] = [newBlocks[target], newBlocks[idx]];
      return { ...prev, blocks: newBlocks };
    });
    setPreviewKey(k => k + 1);
  };

  const handleAddModule = async () => {
    if (!newModuleQuery.trim()) return;
    setIsAddingModule(true);
    setIsSidebarOpen(false); 
    try {
      const context = state.blocks.map(b => b.html).join(' ');
      const newBlock = await geminiService.generateSingleBlock(newModuleQuery, state.designTone, context);
      setState(prev => ({ ...prev, blocks: [...prev.blocks, newBlock], selectedBlockId: newBlock.id }));
      setNewModuleQuery('');
      setViewMode('preview');
      setPreviewKey(k => k + 1);

      const parser = new DOMParser();
      const doc = parser.parseFromString(newBlock.html, 'text/html');
      doc.querySelectorAll('img').forEach((img, idx) => {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) handleRegenerateImage(newBlock.id, idx, prompt, false);
      });
    } catch (e: any) { addLog('error', e.message); } finally { setIsAddingModule(false); }
  };

  const internalHtml = useMemo(() => generateIframeHtml(state, true, previewDevice), [state, previewKey, previewDevice]);

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <Header 
        projectName={state.projectName} isEditingTitle={false} setIsEditingTitle={() => {}} setProjectName={(name) => setState(prev => ({ ...prev, projectName: name }))}
        isSaved={isSaved} createSnapshot={() => {}} showTerminal={showTerminal} setShowTerminal={setShowTerminal} viewMode={viewMode} setViewMode={setViewMode}
        handleExport={() => {
           const finalHtml = generateIframeHtml(state, false, 'desktop');
           const blob = new Blob([finalHtml], { type: 'text/html' });
           const url = URL.createObjectURL(blob);
           const a = document.createElement('a');
           a.href = url; a.download = `${state.projectName}.html`; a.click();
        }}
      />

      <button 
        onClick={() => setIsSidebarOpen(!isSidebarOpen)}
        className="lg:hidden fixed bottom-6 left-6 z-[110] w-14 h-14 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center active:scale-90 transition-transform"
      >
        {isSidebarOpen ? <X /> : <Menu />}
      </button>

      <main className="flex-1 flex overflow-hidden relative">
        <div className={`
          fixed inset-y-0 left-0 z-[100] w-72 lg:relative lg:translate-x-0 transition-transform duration-300 ease-in-out
          ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
        `}>
          <LeftSidebar 
            sidebarTab="blocks" setSidebarTab={() => {}} blocks={state.blocks} selectedBlockId={state.selectedBlockId} setSelectedBlockId={(id) => setState(prev => ({ ...prev, selectedBlockId: id }))}
            setViewMode={setViewMode} moveBlock={handleMoveBlock} deleteBlock={(id) => setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== id) }))}
            syncingBlocks={new Set()} newModuleQuery={newModuleQuery} setNewModuleQuery={setNewModuleQuery} handleAddModule={handleAddModule} isAddingModule={isAddingModule}
            snapshots={state.snapshots} restoreSnapshot={() => {}} deleteSnapshot={() => {}} designTone={state.designTone} setDesignTone={(tone) => setState(prev => ({ ...prev, designTone: tone }))}
          />
        </div>

        {isSidebarOpen && <div onClick={() => setIsSidebarOpen(false)} className="lg:hidden fixed inset-0 bg-black/60 backdrop-blur-sm z-[90]" />}

        <section className="flex-1 flex flex-col bg-[#020617] relative">
          {(state.blocks.length === 0 || viewMode === 'edit') ? (
            <BuildScreen inputSource={inputSource} setInputSource={setInputSource} handleBuild={handleBuild} isProcessing={isProcessing} hasBlocks={state.blocks.length > 0} onCancel={() => setViewMode('preview')} />
          ) : (
            <PreviewCanvas 
              previewDevice={previewDevice} setPreviewDevice={setPreviewDevice} setViewMode={setViewMode} internalHtml={internalHtml} previewKey={previewKey}
              showHud={showHud} setShowHud={setShowHud} spacingScale={state.spacingScale} setSpacingScale={(s) => setState(prev => ({ ...prev, spacingScale: s }))}
              shadowIntensity={state.shadowIntensity} setShadowIntensity={(sh) => setState(prev => ({ ...prev, shadowIntensity: sh }))}
              canvasHeight={state.canvasHeights[previewDevice]}
              setCanvasHeight={(h) => setState(prev => ({...prev, canvasHeights: {...prev.canvasHeights, [previewDevice]: h}}))}
            />
          )}
        </section>

        <div className="hidden lg:block">
          <RightSidebar 
            accentColor={state.accentColor} setAccentColor={(c) => setState(prev => ({ ...prev, accentColor: c }))} fontFamily={state.fontFamily} setFontFamily={(f) => setState(prev => ({ ...prev, fontFamily: f }))}
            borderRadius={state.borderRadius} setBorderRadius={(r) => setState(prev => ({ ...prev, borderRadius: r }))} spacingScale={state.spacingScale} setSpacingScale={(s) => setState(prev => ({ ...prev, spacingScale: s }))}
            shadowIntensity={state.shadowIntensity} setShadowIntensity={(sh) => setState(prev => ({ ...prev, shadowIntensity: sh }))}
            googleFormUrl={state.googleFormUrl} setGoogleFormUrl={(u) => setState(prev => ({ ...prev, googleFormUrl: u }))} deployFormBlock={deployFormBlock} handleReset={() => setState(getInitialState())}
          />
        </div>
      </main>

      {showTerminal && <Terminal logs={state.logs} onClose={() => setShowTerminal(false)} />}

      <div className="fixed bottom-6 right-6 lg:left-1/2 lg:-translate-x-1/2 z-[100] flex gap-2">
         <button 
           // @ts-ignore
           onClick={() => window.aistudio.openSelectKey()}
           className="px-4 lg:px-6 py-2.5 bg-slate-900/80 backdrop-blur-xl border border-blue-500/50 text-blue-400 text-[9px] lg:text-[10px] font-black uppercase tracking-widest rounded-full shadow-2xl hover:bg-blue-500 hover:text-white transition-all flex items-center gap-2"
         >
           <Sparkles className="w-3 h-3" /> Cài đặt Gemini AI
