import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { geminiService } from './services/geminiService';
import { OmniState, LogEntry, Block } from './types';
import { Header } from './components/Header';
import { LeftSidebar } from './components/LeftSidebar';
import { RightSidebar } from './components/RightSidebar';
import { Terminal } from './components/Terminal';
import { BuildScreen } from './components/BuildScreen';
import { PreviewCanvas } from './components/PreviewCanvas';
import { generateIframeHtml } from './utils/iframeHelper';
import { Menu, X, Sparkles } from 'lucide-react';

const getInitialState = (): OmniState => ({
  projectName: "Dự án Thiết kế Mới",
  metaTitle: "Landing Page Architect",
  blocks: [],
  selectedBlockId: null,
  globalCss: "",
  accentColor: "#3b82f6",
  fontFamily: "Inter",
  designTone: 'professional',
  borderRadius: '0.75rem',
  spacingScale: 1.0,
  shadowIntensity: 0.1,
  logs: [],
  snapshots: [],
  googleFormUrl: "",
  canvasHeights: {
    mobile: 800,
    tablet: 1024,
    desktop: 1800
  }
});

export default function App() {
  const [state, setState] = useState<OmniState>(getInitialState());
  const [isProcessing, setIsProcessing] = useState(false);
  const [isAddingModule, setIsAddingModule] = useState(false);
  const [newModuleQuery, setNewModuleQuery] = useState('');
  const [viewMode, setViewMode] = useState<'edit' | 'preview'>('preview');
  const [previewDevice, setPreviewDevice] = useState<'mobile' | 'tablet' | 'desktop'>('desktop');
  const [inputSource, setInputSource] = useState('');
  const [previewKey, setPreviewKey] = useState(0);
  const [showTerminal, setShowTerminal] = useState(false);
  const [isSaved, setIsSaved] = useState(true);
  const [showHud, setShowHud] = useState(true);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const addLog = useCallback((type: LogEntry['type'], message: string) => {
    const newLog: LogEntry = { id: Math.random().toString(36).substr(2, 9), timestamp: new Date().toLocaleTimeString(), type, message };
    setState(prev => ({ ...prev, logs: [newLog, ...prev.logs].slice(0, 50) }));
  }, []);

  const updateBlockImage = (blockId: string, imgIndex: number, newUrl: string) => {
    setState(prev => ({
      ...prev,
      blocks: prev.blocks.map(b => {
        if (b.id !== blockId) return b;
        const parser = new DOMParser();
        const doc = parser.parseFromString(b.html, 'text/html');
        const imgs = doc.querySelectorAll('img');
        if (imgs[imgIndex]) {
          imgs[imgIndex].src = newUrl;
          imgs[imgIndex].classList.remove('is-generating');
        }
        return { ...b, html: doc.body.innerHTML };
      })
    }));
    setPreviewKey(k => k + 1);
  };

  const handleRegenerateImage = async (blockId: string, imgIndex: number, prompt: string, isPro: boolean = false) => {
    // @ts-ignore
    if (isPro && window.aistudio && !(await window.aistudio.hasSelectedApiKey())) {
      addLog('warning', 'Vui lòng chọn API Key để sử dụng tính năng AI.');
      // @ts-ignore
      await window.aistudio.openSelectKey();
      return;
    }
    addLog('info', `AI đang xử lý hình ảnh #${imgIndex + 1}...`);
    try {
      const imageUrl = await geminiService.generateAiImage(prompt, isPro);
      updateBlockImage(blockId, imgIndex, imageUrl);
      addLog('success', 'Đã cập nhật ảnh AI.');
    } catch (e: any) { addLog('error', `Lỗi AI: ${e.message}`); }
  };

  const handleFileUpload = (blockId: string, imgIndex: number) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e: any) => {
      const file = e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (event: any) => {
        updateBlockImage(blockId, imgIndex, event.target.result);
        addLog('success', `Đã upload: ${file.name}`);
      };
      reader.readAsDataURL(file);
    };
    input.click();
  };

  const handleBuild = async () => {
    if (!inputSource.trim()) return;
    setIsProcessing(true);
    try {
      const result = await geminiService.parseToBlocks(inputSource, state.designTone, inputSource.includes('<') ? inputSource : undefined);
      setState(prev => ({ ...prev, blocks: result.blocks, globalCss: result.globalCss, selectedBlockId: result.blocks[0]?.id || null }));
      setViewMode('preview');
      setPreviewKey(k => k + 1);
      addLog('success', 'Giao diện đã được xây dựng.');

      result.blocks.forEach(block => {
        const parser = new DOMParser();
        const doc = parser.parseFromString(block.html, 'text/html');
        doc.querySelectorAll('img').forEach((img, idx) => {
          const prompt = img.getAttribute('data-ai-prompt');
          if (prompt) handleRegenerateImage(block.id, idx, prompt, false);
        });
      });
    } catch (e: any) { addLog('error', e.message); } finally { setIsProcessing(false); }
  };

  const deployFormBlock = async () => {
    if (!state.googleFormUrl.trim()) {
      addLog('warning', 'Vui lòng nhập Link Google Form trước khi đồng bộ.');
      return;
    }
    setIsAddingModule(true);
    addLog('info', 'Đang thiết kế Section Lead Capture thông minh (Vùng chạm vô hình)...');
    try {
      // Prompt được tinh chỉnh để giải quyết triệt để vấn đề click không hoạt động trên mobile
      // Giải pháp: Sử dụng một div trong suốt tuyệt đối đè lên iframe để bắt sự kiện click ban đầu
      const prompt = `Create a professional Lead Capture section for this Google Form: ${state.googleFormUrl}.

      MOBILE TAP-TO-FULLSCREEN LOGIC (CRITICAL):
      1. Structure:
         - A main container with 'relative' positioning.
         - Inside, the Google Form Iframe.
         - Also inside, a TRANSPARENT 'trigger-div' (absolute inset-0, z-20, only visible on mobile).
      2. Behavior:
         - On Mobile: When 'trigger-div' is clicked, use JavaScript to:
           a) Add 'fixed top-0 left-0 w-screen h-screen z-[99999] bg-white' to the main container.
           b) Hide the 'trigger-div' (so the user can now interact with the actual form).
           c) Show a 'Floating Close Button' (X) at the top-right of the fullscreen view.
         - On Click 'Floating Close Button': Remove fullscreen classes and show 'trigger-div' again.
      3. UI Requirements:
         - NO visible overlays, text, or labels. It must look like a normal form section.
         - The fullscreen transition must be instant and smooth.
         - For Desktop: No special behavior, just a standard clean embed.
      4. Styling: Use Tailwind CSS. Ensure the 'Floating Close Button' is high-contrast and easy to tap.`;

      const context = state.blocks.map(b => b.html).join(' ');
      const newBlock = await geminiService.generateSingleBlock(prompt, state.designTone, context);
      setState(prev => ({ ...prev, blocks: [...prev.blocks, newBlock], selectedBlockId: newBlock.id }));
      setPreviewKey(k => k + 1);
      addLog('success', 'Đã thêm Form Block thông minh: Chạm vô hình để mở toàn màn hình.');
    } catch (e: any) { addLog('error', `Lỗi khi đồng bộ Form: ${e.message}`); } finally { setIsAddingModule(false); }
  };

  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      const { type, blockId, newHtml, direction, imgIndex, prompt, height, device } = event.data;
      if (!type) return;
      switch (type) {
        case 'UPDATE_BLOCK_HTML':
          setState(prev => ({ ...prev, blocks: prev.blocks.map(b => b.id === blockId ? { ...b, html: newHtml } : b) }));
          break;
        case 'UPDATE_BLOCK_HEIGHT':
          setState(prev => ({
            ...prev,
            blocks: prev.blocks.map(b => b.id === blockId ? { ...b, heights: { ...b.heights, [device]: height } } : b)
          }));
          break;
        case 'MOVE_BLOCK':
          handleMoveBlock(state.blocks.findIndex(b => b.id === blockId), direction);
          break;
        case 'DELETE_BLOCK':
          if(confirm('Xóa Section này?')) setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== blockId) }));
          break;
        case 'SELECT_BLOCK':
          setState(prev => ({ ...prev, selectedBlockId: blockId }));
          break;
        case 'ADD_SECTION_PROMPT':
          setViewMode('edit');
          break;
        case 'REGENERATE_IMAGE':
          handleRegenerateImage(blockId, imgIndex, prompt, true);
          break;
        case 'UPLOAD_IMAGE':
          handleFileUpload(blockId, imgIndex);
          break;
      }
    };
    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, [state.blocks, addLog]);

  const handleMoveBlock = (idx: number, dir: 'up' | 'down') => {
    setState(prev => {
      const newBlocks = [...prev.blocks];
      const target = dir === 'up' ? idx - 1 : idx + 1;
      if (target < 0 || target >= newBlocks.length) return prev;
      [newBlocks[idx], newBlocks[target]] = [newBlocks[target], newBlocks[idx]];
      return { ...prev, blocks: newBlocks };
    });
    setPreviewKey(k => k + 1);
  };

  const handleAddModule = async () => {
    if (!newModuleQuery.trim()) return;
    setIsAddingModule(true);
    setIsSidebarOpen(false); 
    try {
      const context = state.blocks.map(b => b.html).join(' ');
      const newBlock = await geminiService.generateSingleBlock(newModuleQuery, state.designTone, context);
      setState(prev => ({ ...prev, blocks: [...prev.blocks, newBlock], selectedBlockId: newBlock.id }));
      setNewModuleQuery('');
      setViewMode('preview');
      setPreviewKey(k => k + 1);

      const parser = new DOMParser();
      const doc = parser.parseFromString(newBlock.html, 'text/html');
      doc.querySelectorAll('img').forEach((img, idx) => {
        const prompt = img.getAttribute('data-ai-prompt');
        if (prompt) handleRegenerateImage(newBlock.id, idx, prompt, false);
      });
    } catch (e: any) { addLog('error', e.message); } finally { setIsAddingModule(false); }
  };

  const internalHtml = useMemo(() => generateIframeHtml(state, true, previewDevice), [state, previewKey, previewDevice]);

  return (
    <div className="min-h-screen flex flex-col bg-[#020617] text-slate-200 font-inter overflow-hidden relative">
      <Header 
        projectName={state.projectName} isEditingTitle={false} setIsEditingTitle={() => {}} setProjectName={(name) => setState(prev => ({ ...prev, projectName: name }))}
        isSaved={isSaved} createSnapshot={() => {}} showTerminal={showTerminal} setShowTerminal={setShowTerminal} viewMode={viewMode} setViewMode={setViewMode}
        handleExport={() => {
           const finalHtml = generateIframeHtml(state, false, 'desktop');
           const blob = new Blob([finalHtml], { type: 'text/html' });
           const url = URL.createObjectURL(blob);
           const a = document.createElement('a');
           a.href = url; a.download = `${state.projectName}.html`; a.click();
        }}
      />

      <button 
        onClick={() => setIsSidebarOpen(!isSidebarOpen)}
        className="lg:hidden fixed bottom-6 left-6 z-[110] w-14 h-14 bg-indigo-600 text-white rounded-full shadow-2xl flex items-center justify-center active:scale-90 transition-transform"
      >
        {isSidebarOpen ? <X /> : <Menu />}
      </button>

      <main className="flex-1 flex overflow-hidden relative">
        <div className={`
          fixed inset-y-0 left-0 z-[100] w-72 lg:relative lg:translate-x-0 transition-transform duration-300 ease-in-out
          ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full'}
        `}>
          <LeftSidebar 
            sidebarTab="blocks" setSidebarTab={() => {}} blocks={state.blocks} selectedBlockId={state.selectedBlockId} setSelectedBlockId={(id) => setState(prev => ({ ...prev, selectedBlockId: id }))}
            setViewMode={setViewMode} moveBlock={handleMoveBlock} deleteBlock={(id) => setState(prev => ({ ...prev, blocks: prev.blocks.filter(b => b.id !== id) }))}
            syncingBlocks={new Set()} newModuleQuery={newModuleQuery} setNewModuleQuery={setNewModuleQuery} handleAddModule={handleAddModule} isAddingModule={isAddingModule}
            snapshots={state.snapshots} restoreSnapshot={() => {}} deleteSnapshot={() => {}} designTone={state.designTone} setDesignTone={(tone) => setState(prev => ({ ...prev, designTone: tone }))}
          />
        </div>

        {isSidebarOpen && <div onClick={() => setIsSidebarOpen(false)} className="lg:hidden fixed inset-0 bg-black/60 backdrop-blur-sm z-[90]" />}

        <section className="flex-1 flex flex-col bg-[#020617] relative">
          {(state.blocks.length === 0 || viewMode === 'edit') ? (
            <BuildScreen inputSource={inputSource} setInputSource={setInputSource} handleBuild={handleBuild} isProcessing={isProcessing} hasBlocks={state.blocks.length > 0} onCancel={() => setViewMode('preview')} />
          ) : (
            <PreviewCanvas 
              previewDevice={previewDevice} setPreviewDevice={setPreviewDevice} setViewMode={setViewMode} internalHtml={internalHtml} previewKey={previewKey}
              showHud={showHud} setShowHud={setShowHud} spacingScale={state.spacingScale} setSpacingScale={(s) => setState(prev => ({ ...prev, spacingScale: s }))}
              shadowIntensity={state.shadowIntensity} setShadowIntensity={(sh) => setState(prev => ({ ...prev, shadowIntensity: sh }))}
              canvasHeight={state.canvasHeights[previewDevice]}
              setCanvasHeight={(h) => setState(prev => ({...prev, canvasHeights: {...prev.canvasHeights, [previewDevice]: h}}))}
            />
          )}
        </section>

        <div className="hidden lg:block">
          <RightSidebar 
            accentColor={state.accentColor} setAccentColor={(c) => setState(prev => ({ ...prev, accentColor: c }))} fontFamily={state.fontFamily} setFontFamily={(f) => setState(prev => ({ ...prev, fontFamily: f }))}
            borderRadius={state.borderRadius} setBorderRadius={(r) => setState(prev => ({ ...prev, borderRadius: r }))} spacingScale={state.spacingScale} setSpacingScale={(s) => setState(prev => ({ ...prev, spacingScale: s }))}
            shadowIntensity={state.shadowIntensity} setShadowIntensity={(sh) => setState(prev => ({ ...prev, shadowIntensity: sh }))}
            googleFormUrl={state.googleFormUrl} setGoogleFormUrl={(u) => setState(prev => ({ ...prev, googleFormUrl: u }))} deployFormBlock={deployFormBlock} handleReset={() => setState(getInitialState())}
          />
        </div>
      </main>

      {showTerminal && <Terminal logs={state.logs} onClose={() => setShowTerminal(false)} />}

      <div className="fixed bottom-6 right-6 lg:left-1/2 lg:-translate-x-1/2 z-[100] flex gap-2">
         <button 
           // @ts-ignore
           onClick={() => window.aistudio.openSelectKey()}
           className="px-4 lg:px-6 py-2.5 bg-slate-900/80 backdrop-blur-xl border border-blue-500/50 text-blue-400 text-[9px] lg:text-[10px] font-black uppercase tracking-widest rounded-full shadow-2xl hover:bg-blue-500 hover:text-white transition-all flex items-center gap-2"
         >
           <Sparkles className="w-3 h-3" /> Cài đặt Gemini AI
         </button>
      </div>

      {(isProcessing || isAddingModule) && (
        <div className="fixed inset-0 bg-slate-950/90 z-[200] flex flex-col items-center justify-center p-6 text-center">
          <div className="w-16 h-16 border-4 border-blue-500 border-t-transparent rounded-full animate-spin mb-4"></div>
          <div className="text-white font-black uppercase tracking-widest text-sm">Omni Engine Active</div>
          <div className="text-slate-400 text-[10px] mt-2 animate-pulse uppercase tracking-[0.2em]">Hệ thống AI đang xử lý yêu cầu...</div>
        </div>
      )}
    </div>
  );
}

